const List<String> layoutMadina15Pages3 = <String>[
  '11;21;0;\nT;0;9:100:1:وَٱلسَّٰبِقُونَ ٱلۡأَوَّلُونَ مِنَ ٱلۡمُهَٰجِرِينَ وَٱلۡأَنصَارِ وَٱلَّذِينَ\nT;0;9:100:0:ٱتَّبَعُوهُم بِإِحۡسَٰنࣲ رَّضِيَ ٱللَّهُ عَنۡهُمۡ وَرَضُواْ عَنۡهُ وَأَعَدَّ\nT;0;9:100:0:لَهُمۡ جَنَّٰتࣲ تَجۡرِي تَحۡتَهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدࣰاۚ\nT;0;9:100:2:ذَٰلِكَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ¦9:101:1:وَمِمَّنۡ حَوۡلَكُم مِّنَ ٱلۡأَعۡرَابِ\nT;0;9:101:0:مُنَٰفِقُونَۖ وَمِنۡ أَهۡلِ ٱلۡمَدِينَةِ مَرَدُواْ عَلَى ٱلنِّفَاقِ لَا تَعۡلَمُهُمۡۖ\nT;0;9:101:0:نَحۡنُ نَعۡلَمُهُمۡۚ سَنُعَذِّبُهُم مَّرَّتَيۡنِ ثُمَّ يُرَدُّونَ إِلَىٰ عَذَابٍ\nT;0;9:101:2:عَظِيمࣲ¦9:102:1:وَءَاخَرُونَ ٱعۡتَرَفُواْ بِذُنُوبِهِمۡ خَلَطُواْ عَمَلࣰا صَٰلِحࣰا\nT;0;9:102:2:وَءَاخَرَ سَيِّئًا عَسَى ٱللَّهُ أَن يَتُوبَ عَلَيۡهِمۡۚ إِنَّ ٱللَّهَ غَفُورࣱ رَّحِيمٌ\nT;0;9:103:1:خُذۡ مِنۡ أَمۡوَٰلِهِمۡ صَدَقَةࣰ تُطَهِّرُهُمۡ وَتُزَكِّيهِم بِهَا وَصَلِّ عَلَيۡهِمۡۖ\nT;0;9:103:2:إِنَّ صَلَوٰتَكَ سَكَنࣱ لَّهُمۡۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌ¦9:104:1:أَلَمۡ يَعۡلَمُوٓاْ أَنَّ\nT;0;9:104:0:ٱللَّهَ هُوَ يَقۡبَلُ ٱلتَّوۡبَةَ عَنۡ عِبَادِهِۦ وَيَأۡخُذُ ٱلصَّدَقَٰتِ وَأَنَّ\nT;0;9:104:2:ٱللَّهَ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ¦9:105:1:وَقُلِ ٱعۡمَلُواْ فَسَيَرَى ٱللَّهُ عَمَلَكُمۡ\nT;0;9:105:0:وَرَسُولُهُۥ وَٱلۡمُؤۡمِنُونَۖ وَسَتُرَدُّونَ إِلَىٰ عَٰلِمِ ٱلۡغَيۡبِ وَٱلشَّهَٰدَةِ\nT;0;9:105:2:فَيُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَ¦9:106:1:وَءَاخَرُونَ مُرۡجَوۡنَ لِأَمۡرِ ٱللَّهِ\nT;0;9:106:2:إِمَّا يُعَذِّبُهُمۡ وَإِمَّا يَتُوبُ عَلَيۡهِمۡۗ وَٱللَّهُ عَلِيمٌ حَكِيمࣱ',
  '11;21;0;82\nT;0;9:107:1:وَٱلَّذِينَ ٱتَّخَذُواْ مَسۡجِدࣰا ضِرَارࣰا وَكُفۡرࣰا وَتَفۡرِيقَۢا بَيۡنَ\nT;0;9:107:0:ٱلۡمُؤۡمِنِينَ وَإِرۡصَادࣰا لِّمَنۡ حَارَبَ ٱللَّهَ وَرَسُولَهُۥ مِن قَبۡلُۚ\nT;0;9:107:0:وَلَيَحۡلِفُنَّ إِنۡ أَرَدۡنَآ إِلَّا ٱلۡحُسۡنَىٰۖ وَٱللَّهُ يَشۡهَدُ إِنَّهُمۡ\nT;0;9:107:2:لَكَٰذِبُونَ¦9:108:1:لَا تَقُمۡ فِيهِ أَبَدࣰاۚ لَّمَسۡجِدٌ أُسِّسَ عَلَى ٱلتَّقۡوَىٰ\nT;0;9:108:0:مِنۡ أَوَّلِ يَوۡمٍ أَحَقُّ أَن تَقُومَ فِيهِۚ فِيهِ رِجَالࣱ يُحِبُّونَ أَن\nT;0;9:108:2:يَتَطَهَّرُواْۚ وَٱللَّهُ يُحِبُّ ٱلۡمُطَّهِّرِينَ¦9:109:1:أَفَمَنۡ أَسَّسَ بُنۡيَٰنَهُۥ\nT;0;9:109:0:عَلَىٰ تَقۡوَىٰ مِنَ ٱللَّهِ وَرِضۡوَٰنٍ خَيۡرٌ أَم مَّنۡ أَسَّسَ بُنۡيَٰنَهُۥ\nT;0;9:109:0:عَلَىٰ شَفَا جُرُفٍ هَارࣲ فَٱنۡهَارَ بِهِۦ فِي نَارِ جَهَنَّمَۗ وَٱللَّهُ لَا يَهۡدِي\nT;0;9:109:2:ٱلۡقَوۡمَ ٱلظَّٰلِمِينَ¦9:110:1:لَا يَزَالُ بُنۡيَٰنُهُمُ ٱلَّذِي بَنَوۡاْ رِيبَةࣰ\nT;0;9:110:2:فِي قُلُوبِهِمۡ إِلَّآ أَن تَقَطَّعَ قُلُوبُهُمۡۗ وَٱللَّهُ عَلِيمٌ حَكِيمٌ\nT;0;9:111:1:۞ إِنَّ ٱللَّهَ ٱشۡتَرَىٰ مِنَ ٱلۡمُؤۡمِنِينَ أَنفُسَهُمۡ وَأَمۡوَٰلَهُم\nT;0;9:111:0:بِأَنَّ لَهُمُ ٱلۡجَنَّةَۚ يُقَٰتِلُونَ فِي سَبِيلِ ٱللَّهِ فَيَقۡتُلُونَ\nT;0;9:111:0:وَيُقۡتَلُونَۖ وَعۡدًا عَلَيۡهِ حَقࣰّا فِي ٱلتَّوۡرَىٰةِ وَٱلۡإِنجِيلِ\nT;0;9:111:0:وَٱلۡقُرۡءَانِۚ وَمَنۡ أَوۡفَىٰ بِعَهۡدِهِۦ مِنَ ٱللَّهِۚ فَٱسۡتَبۡشِرُواْ\nT;0;9:111:2:بِبَيۡعِكُمُ ٱلَّذِي بَايَعۡتُم بِهِۦۚ وَذَٰلِكَ هُوَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ',
  '11;21;1;\nT;0;9:112:1:ٱلتَّٰٓئِبُونَ ٱلۡعَٰبِدُونَ ٱلۡحَٰمِدُونَ ٱلسَّٰٓئِحُونَ\nT;0;9:112:0:ٱلرَّٰكِعُونَ ٱلسَّٰجِدُونَ ٱلۡأٓمِرُونَ بِٱلۡمَعۡرُوفِ\nT;0;9:112:0:وَٱلنَّاهُونَ عَنِ ٱلۡمُنكَرِ وَٱلۡحَٰفِظُونَ لِحُدُودِ ٱللَّهِۗ\nT;0;9:112:2:وَبَشِّرِ ٱلۡمُؤۡمِنِينَ¦9:113:1:مَا كَانَ لِلنَّبِيِّ وَٱلَّذِينَ ءَامَنُوٓاْ\nT;0;9:113:0:أَن يَسۡتَغۡفِرُواْ لِلۡمُشۡرِكِينَ وَلَوۡ كَانُوٓاْ أُوْلِي قُرۡبَىٰ\nT;0;9:113:2:مِنۢ بَعۡدِ مَا تَبَيَّنَ لَهُمۡ أَنَّهُمۡ أَصۡحَٰبُ ٱلۡجَحِيمِ¦9:114:1:وَمَا\nT;0;9:114:0:كَانَ ٱسۡتِغۡفَارُ إِبۡرَٰهِيمَ لِأَبِيهِ إِلَّا عَن مَّوۡعِدَةࣲ وَعَدَهَآ\nT;0;9:114:0:إِيَّاهُ فَلَمَّا تَبَيَّنَ لَهُۥٓ أَنَّهُۥ عَدُوࣱّ لِّلَّهِ تَبَرَّأَ مِنۡهُۚ إِنَّ إِبۡرَٰهِيمَ\nT;0;9:114:2:لَأَوَّٰهٌ حَلِيمࣱ¦9:115:1:وَمَا كَانَ ٱللَّهُ لِيُضِلَّ قَوۡمَۢا بَعۡدَ إِذۡ\nT;0;9:115:0:هَدَىٰهُمۡ حَتَّىٰ يُبَيِّنَ لَهُم مَّا يَتَّقُونَۚ إِنَّ ٱللَّهَ بِكُلِّ شَيۡءٍ\nT;0;9:115:2:عَلِيمٌ¦9:116:1:إِنَّ ٱللَّهَ لَهُۥ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ يُحۡيِۦ\nT;0;9:116:2:وَيُمِيتُۚ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِن وَلِيࣲّ وَلَا نَصِيرࣲ\nT;0;9:117:1:لَّقَد تَّابَ ٱللَّهُ عَلَى ٱلنَّبِيِّ وَٱلۡمُهَٰجِرِينَ وَٱلۡأَنصَارِ ٱلَّذِينَ\nT;0;9:117:0:ٱتَّبَعُوهُ فِي سَاعَةِ ٱلۡعُسۡرَةِ مِنۢ بَعۡدِ مَا كَادَ يَزِيغُ قُلُوبُ\nT;0;9:117:2:فَرِيقࣲ مِّنۡهُمۡ ثُمَّ تَابَ عَلَيۡهِمۡۚ إِنَّهُۥ بِهِمۡ رَءُوفࣱ رَّحِيمࣱ',
  '11;21;1;83\nT;0;9:118:1:وَعَلَى ٱلثَّلَٰثَةِ ٱلَّذِينَ خُلِّفُواْ حَتَّىٰٓ إِذَا ضَاقَتۡ عَلَيۡهِمُ ٱلۡأَرۡضُ\nT;0;9:118:0:بِمَا رَحُبَتۡ وَضَاقَتۡ عَلَيۡهِمۡ أَنفُسُهُمۡ وَظَنُّوٓاْ أَن لَّا مَلۡجَأَ\nT;0;9:118:0:مِنَ ٱللَّهِ إِلَّآ إِلَيۡهِ ثُمَّ تَابَ عَلَيۡهِمۡ لِيَتُوبُوٓاْۚ إِنَّ ٱللَّهَ هُوَ ٱلتَّوَّابُ\nT;0;9:118:2:ٱلرَّحِيمُ¦9:119:1:يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ ٱللَّهَ وَكُونُواْ مَعَ\nT;0;9:119:2:ٱلصَّٰدِقِينَ¦9:120:1:مَا كَانَ لِأَهۡلِ ٱلۡمَدِينَةِ وَمَنۡ حَوۡلَهُم\nT;0;9:120:0:مِّنَ ٱلۡأَعۡرَابِ أَن يَتَخَلَّفُواْ عَن رَّسُولِ ٱللَّهِ وَلَا يَرۡغَبُواْ\nT;0;9:120:0:بِأَنفُسِهِمۡ عَن نَّفۡسِهِۦۚ ذَٰلِكَ بِأَنَّهُمۡ لَا يُصِيبُهُمۡ ظَمَأࣱ\nT;0;9:120:0:وَلَا نَصَبࣱ وَلَا مَخۡمَصَةࣱ فِي سَبِيلِ ٱللَّهِ وَلَا يَطَـُٔونَ مَوۡطِئࣰا\nT;0;9:120:0:يَغِيظُ ٱلۡكُفَّارَ وَلَا يَنَالُونَ مِنۡ عَدُوࣲّ نَّيۡلًا إِلَّا كُتِبَ\nT;0;9:120:2:لَهُم بِهِۦ عَمَلࣱ صَٰلِحٌۚ إِنَّ ٱللَّهَ لَا يُضِيعُ أَجۡرَ ٱلۡمُحۡسِنِينَ\nT;0;9:121:1:وَلَا يُنفِقُونَ نَفَقَةࣰ صَغِيرَةࣰ وَلَا كَبِيرَةࣰ وَلَا يَقۡطَعُونَ\nT;0;9:121:0:وَادِيًا إِلَّا كُتِبَ لَهُمۡ لِيَجۡزِيَهُمُ ٱللَّهُ أَحۡسَنَ مَا كَانُواْ\nT;0;9:121:2:يَعۡمَلُونَ¦9:122:1:۞ وَمَا كَانَ ٱلۡمُؤۡمِنُونَ لِيَنفِرُواْ كَآفَّةࣰۚ\nT;0;9:122:0:فَلَوۡلَا نَفَرَ مِن كُلِّ فِرۡقَةࣲ مِّنۡهُمۡ طَآئِفَةࣱ لِّيَتَفَقَّهُواْ فِي ٱلدِّينِ\nT;0;9:122:2:وَلِيُنذِرُواْ قَوۡمَهُمۡ إِذَا رَجَعُوٓاْ إِلَيۡهِمۡ لَعَلَّهُمۡ يَحۡذَرُونَ',
  '11;21;2;\nT;0;9:123:1:يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ قَٰتِلُواْ ٱلَّذِينَ يَلُونَكُم مِّنَ\nT;0;9:123:0:ٱلۡكُفَّارِ وَلۡيَجِدُواْ فِيكُمۡ غِلۡظَةࣰۚ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ\nT;0;9:123:2:مَعَ ٱلۡمُتَّقِينَ¦9:124:1:وَإِذَا مَآ أُنزِلَتۡ سُورَةࣱ فَمِنۡهُم مَّن\nT;0;9:124:0:يَقُولُ أَيُّكُمۡ زَادَتۡهُ هَٰذِهِۦٓ إِيمَٰنࣰاۚ فَأَمَّا ٱلَّذِينَ\nT;0;9:124:2:ءَامَنُواْ فَزَادَتۡهُمۡ إِيمَٰنࣰا وَهُمۡ يَسۡتَبۡشِرُونَ\nT;0;9:125:1:وَأَمَّا ٱلَّذِينَ فِي قُلُوبِهِم مَّرَضࣱ فَزَادَتۡهُمۡ رِجۡسًا إِلَىٰ\nT;0;9:125:2:رِجۡسِهِمۡ وَمَاتُواْ وَهُمۡ كَٰفِرُونَ¦9:126:1:أَوَلَا يَرَوۡنَ\nT;0;9:126:0:أَنَّهُمۡ يُفۡتَنُونَ فِي كُلِّ عَامࣲ مَّرَّةً أَوۡ مَرَّتَيۡنِ ثُمَّ\nT;0;9:126:2:لَا يَتُوبُونَ وَلَا هُمۡ يَذَّكَّرُونَ¦9:127:1:وَإِذَا مَآ أُنزِلَتۡ\nT;0;9:127:0:سُورَةࣱ نَّظَرَ بَعۡضُهُمۡ إِلَىٰ بَعۡضٍ هَلۡ يَرَىٰكُم مِّنۡ\nT;0;9:127:0:أَحَدࣲ ثُمَّ ٱنصَرَفُواْۚ صَرَفَ ٱللَّهُ قُلُوبَهُم بِأَنَّهُمۡ قَوۡمࣱ\nT;0;9:127:2:لَّا يَفۡقَهُونَ¦9:128:1:لَقَدۡ جَآءَكُمۡ رَسُولࣱ مِّنۡ أَنفُسِكُمۡ\nT;0;9:128:0:عَزِيزٌ عَلَيۡهِ مَا عَنِتُّمۡ حَرِيصٌ عَلَيۡكُم بِٱلۡمُؤۡمِنِينَ\nT;0;9:128:2:رَءُوفࣱ رَّحِيمࣱ¦9:129:1:فَإِن تَوَلَّوۡاْ فَقُلۡ حَسۡبِيَ ٱللَّهُ لَآ إِلَٰهَ\nT;2;9:129:2:إِلَّا هُوَۖ عَلَيۡهِ تَوَكَّلۡتُۖ وَهُوَ رَبُّ ٱلۡعَرۡشِ ٱلۡعَظِيمِ',
  '11;21;2;\nH;10\nB;10\nT;0;10:1:3:الٓرۚ تِلۡكَ ءَايَٰتُ ٱلۡكِتَٰبِ ٱلۡحَكِيمِ¦10:2:1:أَكَانَ لِلنَّاسِ عَجَبًا أَنۡ\nT;0;10:2:0:أَوۡحَيۡنَآ إِلَىٰ رَجُلࣲ مِّنۡهُمۡ أَنۡ أَنذِرِ ٱلنَّاسَ وَبَشِّرِ ٱلَّذِينَ ءَامَنُوٓاْ\nT;0;10:2:0:أَنَّ لَهُمۡ قَدَمَ صِدۡقٍ عِندَ رَبِّهِمۡۗ قَالَ ٱلۡكَٰفِرُونَ إِنَّ هَٰذَا\nT;0;10:2:2:لَسَٰحِرࣱ مُّبِينٌ¦10:3:1:إِنَّ رَبَّكُمُ ٱللَّهُ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ\nT;0;10:3:0:فِي سِتَّةِ أَيَّامࣲ ثُمَّ ٱسۡتَوَىٰ عَلَى ٱلۡعَرۡشِۖ يُدَبِّرُ ٱلۡأَمۡرَۖ مَا مِن شَفِيعٍ\nT;0;10:3:2:إِلَّا مِنۢ بَعۡدِ إِذۡنِهِۦۚ ذَٰلِكُمُ ٱللَّهُ رَبُّكُمۡ فَٱعۡبُدُوهُۚ أَفَلَا تَذَكَّرُونَ\nT;0;10:4:1:إِلَيۡهِ مَرۡجِعُكُمۡ جَمِيعࣰاۖ وَعۡدَ ٱللَّهِ حَقًّاۚ إِنَّهُۥ يَبۡدَؤُاْ ٱلۡخَلۡقَ ثُمَّ يُعِيدُهُۥ\nT;0;10:4:0:لِيَجۡزِيَ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ بِٱلۡقِسۡطِۚ وَٱلَّذِينَ كَفَرُواْ\nT;0;10:4:2:لَهُمۡ شَرَابࣱ مِّنۡ حَمِيمࣲ وَعَذَابٌ أَلِيمُۢ بِمَا كَانُواْ يَكۡفُرُونَ\nT;0;10:5:1:هُوَ ٱلَّذِي جَعَلَ ٱلشَّمۡسَ ضِيَآءࣰ وَٱلۡقَمَرَ نُورࣰا وَقَدَّرَهُۥ مَنَازِلَ\nT;0;10:5:0:لِتَعۡلَمُواْ عَدَدَ ٱلسِّنِينَ وَٱلۡحِسَابَۚ مَا خَلَقَ ٱللَّهُ ذَٰلِكَ إِلَّا بِٱلۡحَقِّۚ\nT;0;10:5:2:يُفَصِّلُ ٱلۡأٓيَٰتِ لِقَوۡمࣲ يَعۡلَمُونَ¦10:6:1:إِنَّ فِي ٱخۡتِلَٰفِ ٱلَّيۡلِ وَٱلنَّهَارِ\nT;0;10:6:2:وَمَا خَلَقَ ٱللَّهُ فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ لَأٓيَٰتࣲ لِّقَوۡمࣲ يَتَّقُونَ',
  '11;21;2;84\nT;0;10:7:1:إِنَّ ٱلَّذِينَ لَا يَرۡجُونَ لِقَآءَنَا وَرَضُواْ بِٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَٱطۡمَأَنُّواْ\nT;0;10:7:2:بِهَا وَٱلَّذِينَ هُمۡ عَنۡ ءَايَٰتِنَا غَٰفِلُونَ¦10:8:1:أُوْلَٰٓئِكَ مَأۡوَىٰهُمُ\nT;0;10:8:2:ٱلنَّارُ بِمَا كَانُواْ يَكۡسِبُونَ¦10:9:1:إِنَّ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ\nT;0;10:9:0:ٱلصَّٰلِحَٰتِ يَهۡدِيهِمۡ رَبُّهُم بِإِيمَٰنِهِمۡۖ تَجۡرِي مِن تَحۡتِهِمُ\nT;0;10:9:2:ٱلۡأَنۡهَٰرُ فِي جَنَّٰتِ ٱلنَّعِيمِ¦10:10:1:دَعۡوَىٰهُمۡ فِيهَا سُبۡحَٰنَكَ\nT;0;10:10:0:ٱللَّهُمَّ وَتَحِيَّتُهُمۡ فِيهَا سَلَٰمࣱۚ وَءَاخِرُ دَعۡوَىٰهُمۡ أَنِ ٱلۡحَمۡدُ\nT;0;10:10:2:لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ¦10:11:1:۞ وَلَوۡ يُعَجِّلُ ٱللَّهُ لِلنَّاسِ ٱلشَّرَّ\nT;0;10:11:0:ٱسۡتِعۡجَالَهُم بِٱلۡخَيۡرِ لَقُضِيَ إِلَيۡهِمۡ أَجَلُهُمۡۖ فَنَذَرُ ٱلَّذِينَ\nT;0;10:11:2:لَا يَرۡجُونَ لِقَآءَنَا فِي طُغۡيَٰنِهِمۡ يَعۡمَهُونَ¦10:12:1:وَإِذَا مَسَّ ٱلۡإِنسَٰنَ\nT;0;10:12:0:ٱلضُّرُّ دَعَانَا لِجَنۢبِهِۦٓ أَوۡ قَاعِدًا أَوۡ قَآئِمࣰا فَلَمَّا كَشَفۡنَا\nT;0;10:12:0:عَنۡهُ ضُرَّهُۥ مَرَّ كَأَن لَّمۡ يَدۡعُنَآ إِلَىٰ ضُرࣲّ مَّسَّهُۥۚ كَذَٰلِكَ زُيِّنَ\nT;0;10:12:2:لِلۡمُسۡرِفِينَ مَا كَانُواْ يَعۡمَلُونَ¦10:13:1:وَلَقَدۡ أَهۡلَكۡنَا ٱلۡقُرُونَ\nT;0;10:13:0:مِن قَبۡلِكُمۡ لَمَّا ظَلَمُواْ وَجَآءَتۡهُمۡ رُسُلُهُم بِٱلۡبَيِّنَٰتِ وَمَا كَانُواْ\nT;0;10:13:2:لِيُؤۡمِنُواْۚ كَذَٰلِكَ نَجۡزِي ٱلۡقَوۡمَ ٱلۡمُجۡرِمِينَ¦10:14:1:ثُمَّ جَعَلۡنَٰكُمۡ\nT;0;10:14:2:خَلَٰٓئِفَ فِي ٱلۡأَرۡضِ مِنۢ بَعۡدِهِمۡ لِنَنظُرَ كَيۡفَ تَعۡمَلُونَ',
  '11;21;3;\nT;0;10:15:1:وَإِذَا تُتۡلَىٰ عَلَيۡهِمۡ ءَايَاتُنَا بَيِّنَٰتࣲ قَالَ ٱلَّذِينَ لَا يَرۡجُونَ\nT;0;10:15:0:لِقَآءَنَا ٱئۡتِ بِقُرۡءَانٍ غَيۡرِ هَٰذَآ أَوۡ بَدِّلۡهُۚ قُلۡ مَا يَكُونُ\nT;0;10:15:0:لِيٓ أَنۡ أُبَدِّلَهُۥ مِن تِلۡقَآيِٕ نَفۡسِيٓۖ إِنۡ أَتَّبِعُ إِلَّا مَا يُوحَىٰٓ إِلَيَّۖ\nT;0;10:15:2:إِنِّيٓ أَخَافُ إِنۡ عَصَيۡتُ رَبِّي عَذَابَ يَوۡمٍ عَظِيمࣲ¦10:16:1:قُل\nT;0;10:16:0:لَّوۡ شَآءَ ٱللَّهُ مَا تَلَوۡتُهُۥ عَلَيۡكُمۡ وَلَآ أَدۡرَىٰكُم بِهِۦۖ\nT;0;10:16:2:فَقَدۡ لَبِثۡتُ فِيكُمۡ عُمُرࣰا مِّن قَبۡلِهِۦٓۚ أَفَلَا تَعۡقِلُونَ\nT;0;10:17:1:فَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوۡ كَذَّبَ بِـَٔايَٰتِهِۦٓۚ\nT;0;10:17:2:إِنَّهُۥ لَا يُفۡلِحُ ٱلۡمُجۡرِمُونَ¦10:18:1:وَيَعۡبُدُونَ مِن دُونِ ٱللَّهِ\nT;0;10:18:0:مَا لَا يَضُرُّهُمۡ وَلَا يَنفَعُهُمۡ وَيَقُولُونَ هَٰٓؤُلَآءِ شُفَعَٰٓؤُنَا\nT;0;10:18:0:عِندَ ٱللَّهِۚ قُلۡ أَتُنَبِّـُٔونَ ٱللَّهَ بِمَا لَا يَعۡلَمُ فِي ٱلسَّمَٰوَٰتِ وَلَا\nT;0;10:18:2:فِي ٱلۡأَرۡضِۚ سُبۡحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا يُشۡرِكُونَ¦10:19:1:وَمَا\nT;0;10:19:0:كَانَ ٱلنَّاسُ إِلَّآ أُمَّةࣰ وَٰحِدَةࣰ فَٱخۡتَلَفُواْۚ وَلَوۡلَا كَلِمَةࣱ\nT;0;10:19:2:سَبَقَتۡ مِن رَّبِّكَ لَقُضِيَ بَيۡنَهُمۡ فِيمَا فِيهِ يَخۡتَلِفُونَ\nT;0;10:20:1:وَيَقُولُونَ لَوۡلَآ أُنزِلَ عَلَيۡهِ ءَايَةࣱ مِّن رَّبِّهِۦۖ فَقُلۡ إِنَّمَا\nT;0;10:20:2:ٱلۡغَيۡبُ لِلَّهِ فَٱنتَظِرُوٓاْ إِنِّي مَعَكُم مِّنَ ٱلۡمُنتَظِرِينَ',
  '11;21;3;\nT;0;10:21:1:وَإِذَآ أَذَقۡنَا ٱلنَّاسَ رَحۡمَةࣰ مِّنۢ بَعۡدِ ضَرَّآءَ مَسَّتۡهُمۡ إِذَا لَهُم مَّكۡرࣱ\nT;0;10:21:2:فِيٓ ءَايَاتِنَاۚ قُلِ ٱللَّهُ أَسۡرَعُ مَكۡرًاۚ إِنَّ رُسُلَنَا يَكۡتُبُونَ مَا تَمۡكُرُونَ\nT;0;10:22:1:هُوَ ٱلَّذِي يُسَيِّرُكُمۡ فِي ٱلۡبَرِّ وَٱلۡبَحۡرِۖ حَتَّىٰٓ إِذَا كُنتُمۡ فِي ٱلۡفُلۡكِ\nT;0;10:22:0:وَجَرَيۡنَ بِهِم بِرِيحࣲ طَيِّبَةࣲ وَفَرِحُواْ بِهَا جَآءَتۡهَا رِيحٌ عَاصِفࣱ\nT;0;10:22:0:وَجَآءَهُمُ ٱلۡمَوۡجُ مِن كُلِّ مَكَانࣲ وَظَنُّوٓاْ أَنَّهُمۡ أُحِيطَ بِهِمۡ\nT;0;10:22:0:دَعَوُاْ ٱللَّهَ مُخۡلِصِينَ لَهُ ٱلدِّينَ لَئِنۡ أَنجَيۡتَنَا مِنۡ هَٰذِهِۦ لَنَكُونَنَّ\nT;0;10:22:2:مِنَ ٱلشَّٰكِرِينَ¦10:23:1:فَلَمَّآ أَنجَىٰهُمۡ إِذَا هُمۡ يَبۡغُونَ فِي ٱلۡأَرۡضِ بِغَيۡرِ\nT;0;10:23:0:ٱلۡحَقِّۗ يَٰٓأَيُّهَا ٱلنَّاسُ إِنَّمَا بَغۡيُكُمۡ عَلَىٰٓ أَنفُسِكُمۖ مَّتَٰعَ ٱلۡحَيَوٰةِ\nT;0;10:23:2:ٱلدُّنۡيَاۖ ثُمَّ إِلَيۡنَا مَرۡجِعُكُمۡ فَنُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَ\nT;0;10:24:1:إِنَّمَا مَثَلُ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا كَمَآءٍ أَنزَلۡنَٰهُ مِنَ ٱلسَّمَآءِ فَٱخۡتَلَطَ\nT;0;10:24:0:بِهِۦ نَبَاتُ ٱلۡأَرۡضِ مِمَّا يَأۡكُلُ ٱلنَّاسُ وَٱلۡأَنۡعَٰمُ حَتَّىٰٓ إِذَآ\nT;0;10:24:0:أَخَذَتِ ٱلۡأَرۡضُ زُخۡرُفَهَا وَٱزَّيَّنَتۡ وَظَنَّ أَهۡلُهَآ أَنَّهُمۡ قَٰدِرُونَ\nT;0;10:24:0:عَلَيۡهَآ أَتَىٰهَآ أَمۡرُنَا لَيۡلًا أَوۡ نَهَارࣰا فَجَعَلۡنَٰهَا حَصِيدࣰا كَأَن لَّمۡ تَغۡنَ\nT;0;10:24:2:بِٱلۡأَمۡسِۚ كَذَٰلِكَ نُفَصِّلُ ٱلۡأٓيَٰتِ لِقَوۡمࣲ يَتَفَكَّرُونَ¦10:25:1:وَٱللَّهُ يَدۡعُوٓاْ\nT;0;10:25:2:إِلَىٰ دَارِ ٱلسَّلَٰمِ وَيَهۡدِي مَن يَشَآءُ إِلَىٰ صِرَٰطࣲ مُّسۡتَقِيمࣲ',
  '11;22;0;85\nT;0;10:26:1:۞ لِّلَّذِينَ أَحۡسَنُواْ ٱلۡحُسۡنَىٰ وَزِيَادَةࣱۖ وَلَا يَرۡهَقُ وُجُوهَهُمۡ قَتَرࣱ\nT;0;10:26:2:وَلَا ذِلَّةٌۚ أُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلۡجَنَّةِۖ هُمۡ فِيهَا خَٰلِدُونَ¦10:27:1:وَٱلَّذِينَ\nT;0;10:27:0:كَسَبُواْ ٱلسَّيِّـَٔاتِ جَزَآءُ سَيِّئَةِۭ بِمِثۡلِهَا وَتَرۡهَقُهُمۡ ذِلَّةࣱۖ مَّا لَهُم\nT;0;10:27:0:مِّنَ ٱللَّهِ مِنۡ عَاصِمࣲۖ كَأَنَّمَآ أُغۡشِيَتۡ وُجُوهُهُمۡ قِطَعࣰا مِّنَ ٱلَّيۡلِ\nT;0;10:27:2:مُظۡلِمًاۚ أُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ فِيهَا خَٰلِدُونَ¦10:28:1:وَيَوۡمَ نَحۡشُرُهُمۡ\nT;0;10:28:0:جَمِيعࣰا ثُمَّ نَقُولُ لِلَّذِينَ أَشۡرَكُواْ مَكَانَكُمۡ أَنتُمۡ وَشُرَكَآؤُكُمۡۚ فَزَيَّلۡنَا\nT;0;10:28:2:بَيۡنَهُمۡۖ وَقَالَ شُرَكَآؤُهُم مَّا كُنتُمۡ إِيَّانَا تَعۡبُدُونَ¦10:29:1:فَكَفَىٰ بِٱللَّهِ\nT;0;10:29:2:شَهِيدَۢا بَيۡنَنَا وَبَيۡنَكُمۡ إِن كُنَّا عَنۡ عِبَادَتِكُمۡ لَغَٰفِلِينَ\nT;0;10:30:1:هُنَالِكَ تَبۡلُواْ كُلُّ نَفۡسࣲ مَّآ أَسۡلَفَتۡۚ وَرُدُّوٓاْ إِلَى ٱللَّهِ مَوۡلَىٰهُمُ\nT;0;10:30:2:ٱلۡحَقِّۖ وَضَلَّ عَنۡهُم مَّا كَانُواْ يَفۡتَرُونَ¦10:31:1:قُلۡ مَن يَرۡزُقُكُم مِّنَ\nT;0;10:31:0:ٱلسَّمَآءِ وَٱلۡأَرۡضِ أَمَّن يَمۡلِكُ ٱلسَّمۡعَ وَٱلۡأَبۡصَٰرَ وَمَن يُخۡرِجُ\nT;0;10:31:0:ٱلۡحَيَّ مِنَ ٱلۡمَيِّتِ وَيُخۡرِجُ ٱلۡمَيِّتَ مِنَ ٱلۡحَيِّ وَمَن يُدَبِّرُ ٱلۡأَمۡرَۚ\nT;0;10:31:2:فَسَيَقُولُونَ ٱللَّهُۚ فَقُلۡ أَفَلَا تَتَّقُونَ¦10:32:1:فَذَٰلِكُمُ ٱللَّهُ رَبُّكُمُ\nT;0;10:32:2:ٱلۡحَقُّۖ فَمَاذَا بَعۡدَ ٱلۡحَقِّ إِلَّا ٱلضَّلَٰلُۖ فَأَنَّىٰ تُصۡرَفُونَ¦10:33:1:كَذَٰلِكَ\nT;0;10:33:2:حَقَّتۡ كَلِمَتُ رَبِّكَ عَلَى ٱلَّذِينَ فَسَقُوٓاْ أَنَّهُمۡ لَا يُؤۡمِنُونَ',
  '11;22;0;\nT;0;10:34:1:قُلۡ هَلۡ مِن شُرَكَآئِكُم مَّن يَبۡدَؤُاْ ٱلۡخَلۡقَ ثُمَّ يُعِيدُهُۥۚ قُلِ ٱللَّهُ يَبۡدَؤُاْ\nT;0;10:34:2:ٱلۡخَلۡقَ ثُمَّ يُعِيدُهُۥۖ فَأَنَّىٰ تُؤۡفَكُونَ¦10:35:1:قُلۡ هَلۡ مِن شُرَكَآئِكُم مَّن يَهۡدِيٓ\nT;0;10:35:0:إِلَى ٱلۡحَقِّۚ قُلِ ٱللَّهُ يَهۡدِي لِلۡحَقِّۗ أَفَمَن يَهۡدِيٓ إِلَى ٱلۡحَقِّ أَحَقُّ أَن\nT;0;10:35:2:يُتَّبَعَ أَمَّن لَّا يَهِدِّيٓ إِلَّآ أَن يُهۡدَىٰۖ فَمَا لَكُمۡ كَيۡفَ تَحۡكُمُونَ\nT;0;10:36:1:وَمَا يَتَّبِعُ أَكۡثَرُهُمۡ إِلَّا ظَنًّاۚ إِنَّ ٱلظَّنَّ لَا يُغۡنِي مِنَ ٱلۡحَقِّ شَيۡـًٔاۚ\nT;0;10:36:2:إِنَّ ٱللَّهَ عَلِيمُۢ بِمَا يَفۡعَلُونَ¦10:37:1:وَمَا كَانَ هَٰذَا ٱلۡقُرۡءَانُ أَن يُفۡتَرَىٰ\nT;0;10:37:0:مِن دُونِ ٱللَّهِ وَلَٰكِن تَصۡدِيقَ ٱلَّذِي بَيۡنَ يَدَيۡهِ وَتَفۡصِيلَ ٱلۡكِتَٰبِ\nT;0;10:37:2:لَا رَيۡبَ فِيهِ مِن رَّبِّ ٱلۡعَٰلَمِينَ¦10:38:1:أَمۡ يَقُولُونَ ٱفۡتَرَىٰهُۖ قُلۡ فَأۡتُواْ بِسُورَةࣲ\nT;0;10:38:2:مِّثۡلِهِۦ وَٱدۡعُواْ مَنِ ٱسۡتَطَعۡتُم مِّن دُونِ ٱللَّهِ إِن كُنتُمۡ صَٰدِقِينَ\nT;0;10:39:1:بَلۡ كَذَّبُواْ بِمَا لَمۡ يُحِيطُواْ بِعِلۡمِهِۦ وَلَمَّا يَأۡتِهِمۡ تَأۡوِيلُهُۥۚ كَذَٰلِكَ\nT;0;10:39:2:كَذَّبَ ٱلَّذِينَ مِن قَبۡلِهِمۡۖ فَٱنظُرۡ كَيۡفَ كَانَ عَٰقِبَةُ ٱلظَّٰلِمِينَ\nT;0;10:40:1:وَمِنۡهُم مَّن يُؤۡمِنُ بِهِۦ وَمِنۡهُم مَّن لَّا يُؤۡمِنُ بِهِۦۚ وَرَبُّكَ أَعۡلَمُ\nT;0;10:40:2:بِٱلۡمُفۡسِدِينَ¦10:41:1:وَإِن كَذَّبُوكَ فَقُل لِّي عَمَلِي وَلَكُمۡ عَمَلُكُمۡۖ أَنتُم\nT;0;10:41:2:بَرِيٓـُٔونَ مِمَّآ أَعۡمَلُ وَأَنَا۠ بَرِيٓءࣱ مِّمَّا تَعۡمَلُونَ¦10:42:1:وَمِنۡهُم مَّن\nT;0;10:42:2:يَسۡتَمِعُونَ إِلَيۡكَۚ أَفَأَنتَ تُسۡمِعُ ٱلصُّمَّ وَلَوۡ كَانُواْ لَا يَعۡقِلُونَ',
  '11;22;0;86\nT;0;10:43:3:وَمِنۡهُم مَّن يَنظُرُ إِلَيۡكَۚ أَفَأَنتَ تَهۡدِي ٱلۡعُمۡيَ وَلَوۡ كَانُواْ لَا يُبۡصِرُونَ\nT;0;10:44:1:إِنَّ ٱللَّهَ لَا يَظۡلِمُ ٱلنَّاسَ شَيۡـࣰٔا وَلَٰكِنَّ ٱلنَّاسَ أَنفُسَهُمۡ\nT;0;10:44:2:يَظۡلِمُونَ¦10:45:1:وَيَوۡمَ يَحۡشُرُهُمۡ كَأَن لَّمۡ يَلۡبَثُوٓاْ إِلَّا سَاعَةࣰ مِّنَ ٱلنَّهَارِ\nT;0;10:45:0:يَتَعَارَفُونَ بَيۡنَهُمۡۚ قَدۡ خَسِرَ ٱلَّذِينَ كَذَّبُواْ بِلِقَآءِ ٱللَّهِ وَمَا كَانُواْ\nT;0;10:45:2:مُهۡتَدِينَ¦10:46:1:وَإِمَّا نُرِيَنَّكَ بَعۡضَ ٱلَّذِي نَعِدُهُمۡ أَوۡ نَتَوَفَّيَنَّكَ\nT;0;10:46:2:فَإِلَيۡنَا مَرۡجِعُهُمۡ ثُمَّ ٱللَّهُ شَهِيدٌ عَلَىٰ مَا يَفۡعَلُونَ¦10:47:1:وَلِكُلِّ\nT;0;10:47:0:أُمَّةࣲ رَّسُولࣱۖ فَإِذَا جَآءَ رَسُولُهُمۡ قُضِيَ بَيۡنَهُم بِٱلۡقِسۡطِ وَهُمۡ\nT;0;10:47:2:لَا يُظۡلَمُونَ¦10:48:3:وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلۡوَعۡدُ إِن كُنتُمۡ صَٰدِقِينَ\nT;0;10:49:1:قُل لَّآ أَمۡلِكُ لِنَفۡسِي ضَرࣰّا وَلَا نَفۡعًا إِلَّا مَا شَآءَ ٱللَّهُۗ لِكُلِّ أُمَّةٍ\nT;0;10:49:2:أَجَلٌۚ إِذَا جَآءَ أَجَلُهُمۡ فَلَا يَسۡتَـٔۡخِرُونَ سَاعَةࣰ وَلَا يَسۡتَقۡدِمُونَ\nT;0;10:50:1:قُلۡ أَرَءَيۡتُمۡ إِنۡ أَتَىٰكُمۡ عَذَابُهُۥ بَيَٰتًا أَوۡ نَهَارࣰا مَّاذَا يَسۡتَعۡجِلُ مِنۡهُ\nT;0;10:50:2:ٱلۡمُجۡرِمُونَ¦10:51:1:أَثُمَّ إِذَا مَا وَقَعَ ءَامَنتُم بِهِۦٓۚ ءَآلۡـَٰٔنَ وَقَدۡ كُنتُم بِهِۦ\nT;0;10:51:2:تَسۡتَعۡجِلُونَ¦10:52:1:ثُمَّ قِيلَ لِلَّذِينَ ظَلَمُواْ ذُوقُواْ عَذَابَ ٱلۡخُلۡدِ\nT;0;10:52:2:هَلۡ تُجۡزَوۡنَ إِلَّا بِمَا كُنتُمۡ تَكۡسِبُونَ¦10:53:1:۞ وَيَسۡتَنۢبِـُٔونَكَ\nT;0;10:53:2:أَحَقٌّ هُوَۖ قُلۡ إِي وَرَبِّيٓ إِنَّهُۥ لَحَقࣱّۖ وَمَآ أَنتُم بِمُعۡجِزِينَ',
  '11;22;1;\nT;0;10:54:1:وَلَوۡ أَنَّ لِكُلِّ نَفۡسࣲ ظَلَمَتۡ مَا فِي ٱلۡأَرۡضِ لَٱفۡتَدَتۡ بِهِۦۗ وَأَسَرُّواْ\nT;0;10:54:0:ٱلنَّدَامَةَ لَمَّا رَأَوُاْ ٱلۡعَذَابَۖ وَقُضِيَ بَيۡنَهُم بِٱلۡقِسۡطِ وَهُمۡ\nT;0;10:54:2:لَا يُظۡلَمُونَ¦10:55:1:أَلَآ إِنَّ لِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۗ أَلَآ إِنَّ\nT;0;10:55:2:وَعۡدَ ٱللَّهِ حَقࣱّ وَلَٰكِنَّ أَكۡثَرَهُمۡ لَا يَعۡلَمُونَ¦10:56:1:هُوَ يُحۡيِۦ وَيُمِيتُ\nT;0;10:56:2:وَإِلَيۡهِ تُرۡجَعُونَ¦10:57:1:يَٰٓأَيُّهَا ٱلنَّاسُ قَدۡ جَآءَتۡكُم مَّوۡعِظَةࣱ\nT;0;10:57:2:مِّن رَّبِّكُمۡ وَشِفَآءࣱ لِّمَا فِي ٱلصُّدُورِ وَهُدࣰى وَرَحۡمَةࣱ لِّلۡمُؤۡمِنِينَ\nT;0;10:58:1:قُلۡ بِفَضۡلِ ٱللَّهِ وَبِرَحۡمَتِهِۦ فَبِذَٰلِكَ فَلۡيَفۡرَحُواْ هُوَ خَيۡرࣱ مِّمَّا\nT;0;10:58:2:يَجۡمَعُونَ¦10:59:1:قُلۡ أَرَءَيۡتُم مَّآ أَنزَلَ ٱللَّهُ لَكُم مِّن رِّزۡقࣲ\nT;0;10:59:0:فَجَعَلۡتُم مِّنۡهُ حَرَامࣰا وَحَلَٰلࣰا قُلۡ ءَآللَّهُ أَذِنَ لَكُمۡۖ أَمۡ عَلَى\nT;0;10:59:2:ٱللَّهِ تَفۡتَرُونَ¦10:60:1:وَمَا ظَنُّ ٱلَّذِينَ يَفۡتَرُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَ\nT;0;10:60:0:يَوۡمَ ٱلۡقِيَٰمَةِۗ إِنَّ ٱللَّهَ لَذُو فَضۡلٍ عَلَى ٱلنَّاسِ وَلَٰكِنَّ أَكۡثَرَهُمۡ\nT;0;10:60:2:لَا يَشۡكُرُونَ¦10:61:1:وَمَا تَكُونُ فِي شَأۡنࣲ وَمَا تَتۡلُواْ مِنۡهُ مِن قُرۡءَانࣲ\nT;0;10:61:0:وَلَا تَعۡمَلُونَ مِنۡ عَمَلٍ إِلَّا كُنَّا عَلَيۡكُمۡ شُهُودًا إِذۡ تُفِيضُونَ\nT;0;10:61:0:فِيهِۚ وَمَا يَعۡزُبُ عَن رَّبِّكَ مِن مِّثۡقَالِ ذَرَّةࣲ فِي ٱلۡأَرۡضِ وَلَا فِي\nT;0;10:61:2:ٱلسَّمَآءِ وَلَآ أَصۡغَرَ مِن ذَٰلِكَ وَلَآ أَكۡبَرَ إِلَّا فِي كِتَٰبࣲ مُّبِينٍ',
  '11;22;1;\nT;0;10:62:3:أَلَآ إِنَّ أَوۡلِيَآءَ ٱللَّهِ لَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ\nT;0;10:63:3:ٱلَّذِينَ ءَامَنُواْ وَكَانُواْ يَتَّقُونَ¦10:64:1:لَهُمُ ٱلۡبُشۡرَىٰ\nT;0;10:64:0:فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَفِي ٱلۡأٓخِرَةِۚ لَا تَبۡدِيلَ لِكَلِمَٰتِ\nT;0;10:64:2:ٱللَّهِۚ ذَٰلِكَ هُوَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ¦10:65:1:وَلَا يَحۡزُنكَ قَوۡلُهُمۡۘ إِنَّ\nT;0;10:65:2:ٱلۡعِزَّةَ لِلَّهِ جَمِيعًاۚ هُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ¦10:66:1:أَلَآ إِنَّ لِلَّهِ\nT;0;10:66:0:مَن فِي ٱلسَّمَٰوَٰتِ وَمَن فِي ٱلۡأَرۡضِۗ وَمَا يَتَّبِعُ ٱلَّذِينَ\nT;0;10:66:0:يَدۡعُونَ مِن دُونِ ٱللَّهِ شُرَكَآءَۚ إِن يَتَّبِعُونَ إِلَّا ٱلظَّنَّ\nT;0;10:66:2:وَإِنۡ هُمۡ إِلَّا يَخۡرُصُونَ¦10:67:1:هُوَ ٱلَّذِي جَعَلَ لَكُمُ\nT;0;10:67:0:ٱلَّيۡلَ لِتَسۡكُنُواْ فِيهِ وَٱلنَّهَارَ مُبۡصِرًاۚ إِنَّ فِي ذَٰلِكَ\nT;0;10:67:2:لَأٓيَٰتࣲ لِّقَوۡمࣲ يَسۡمَعُونَ¦10:68:1:قَالُواْ ٱتَّخَذَ ٱللَّهُ وَلَدࣰاۗ\nT;0;10:68:0:سُبۡحَٰنَهُۥۖ هُوَ ٱلۡغَنِيُّۖ لَهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۚ\nT;0;10:68:0:إِنۡ عِندَكُم مِّن سُلۡطَٰنِۭ بِهَٰذَآۚ أَتَقُولُونَ عَلَى ٱللَّهِ\nT;0;10:68:2:مَا لَا تَعۡلَمُونَ¦10:69:1:قُلۡ إِنَّ ٱلَّذِينَ يَفۡتَرُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَ\nT;0;10:69:2:لَا يُفۡلِحُونَ¦10:70:1:مَتَٰعࣱ فِي ٱلدُّنۡيَا ثُمَّ إِلَيۡنَا مَرۡجِعُهُمۡ ثُمَّ\nT;0;10:70:2:نُذِيقُهُمُ ٱلۡعَذَابَ ٱلشَّدِيدَ بِمَا كَانُواْ يَكۡفُرُونَ',
  '11;22;2;87\nT;0;10:71:1:۞ وَٱتۡلُ عَلَيۡهِمۡ نَبَأَ نُوحٍ إِذۡ قَالَ لِقَوۡمِهِۦ يَٰقَوۡمِ إِن كَانَ كَبُرَ\nT;0;10:71:0:عَلَيۡكُم مَّقَامِي وَتَذۡكِيرِي بِـَٔايَٰتِ ٱللَّهِ فَعَلَى ٱللَّهِ تَوَكَّلۡتُ\nT;0;10:71:0:فَأَجۡمِعُوٓاْ أَمۡرَكُمۡ وَشُرَكَآءَكُمۡ ثُمَّ لَا يَكُنۡ أَمۡرُكُمۡ عَلَيۡكُمۡ غُمَّةࣰ ثُمَّ\nT;0;10:71:2:ٱقۡضُوٓاْ إِلَيَّ وَلَا تُنظِرُونِ¦10:72:1:فَإِن تَوَلَّيۡتُمۡ فَمَا سَأَلۡتُكُم مِّنۡ أَجۡرٍۖ\nT;0;10:72:2:إِنۡ أَجۡرِيَ إِلَّا عَلَى ٱللَّهِۖ وَأُمِرۡتُ أَنۡ أَكُونَ مِنَ ٱلۡمُسۡلِمِينَ\nT;0;10:73:1:فَكَذَّبُوهُ فَنَجَّيۡنَٰهُ وَمَن مَّعَهُۥ فِي ٱلۡفُلۡكِ وَجَعَلۡنَٰهُمۡ خَلَٰٓئِفَ\nT;0;10:73:2:وَأَغۡرَقۡنَا ٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَاۖ فَٱنظُرۡ كَيۡفَ كَانَ عَٰقِبَةُ ٱلۡمُنذَرِينَ\nT;0;10:74:1:ثُمَّ بَعَثۡنَا مِنۢ بَعۡدِهِۦ رُسُلًا إِلَىٰ قَوۡمِهِمۡ فَجَآءُوهُم بِٱلۡبَيِّنَٰتِ\nT;0;10:74:0:فَمَا كَانُواْ لِيُؤۡمِنُواْ بِمَا كَذَّبُواْ بِهِۦ مِن قَبۡلُۚ كَذَٰلِكَ نَطۡبَعُ عَلَىٰ قُلُوبِ\nT;0;10:74:2:ٱلۡمُعۡتَدِينَ¦10:75:1:ثُمَّ بَعَثۡنَا مِنۢ بَعۡدِهِم مُّوسَىٰ وَهَٰرُونَ إِلَىٰ فِرۡعَوۡنَ\nT;0;10:75:2:وَمَلَإِيْهِۦ بِـَٔايَٰتِنَا فَٱسۡتَكۡبَرُواْ وَكَانُواْ قَوۡمࣰا مُّجۡرِمِينَ\nT;0;10:76:3:فَلَمَّا جَآءَهُمُ ٱلۡحَقُّ مِنۡ عِندِنَا قَالُوٓاْ إِنَّ هَٰذَا لَسِحۡرࣱ مُّبِينࣱ\nT;0;10:77:1:قَالَ مُوسَىٰٓ أَتَقُولُونَ لِلۡحَقِّ لَمَّا جَآءَكُمۡۖ أَسِحۡرٌ هَٰذَا وَلَا يُفۡلِحُ\nT;0;10:77:2:ٱلسَّٰحِرُونَ¦10:78:1:قَالُوٓاْ أَجِئۡتَنَا لِتَلۡفِتَنَا عَمَّا وَجَدۡنَا عَلَيۡهِ ءَابَآءَنَا\nT;0;10:78:2:وَتَكُونَ لَكُمَا ٱلۡكِبۡرِيَآءُ فِي ٱلۡأَرۡضِ وَمَا نَحۡنُ لَكُمَا بِمُؤۡمِنِينَ',
  '11;22;2;\nT;0;10:79:3:وَقَالَ فِرۡعَوۡنُ ٱئۡتُونِي بِكُلِّ سَٰحِرٍ عَلِيمࣲ¦10:80:1:فَلَمَّا جَآءَ ٱلسَّحَرَةُ\nT;0;10:80:2:قَالَ لَهُم مُّوسَىٰٓ أَلۡقُواْ مَآ أَنتُم مُّلۡقُونَ¦10:81:1:فَلَمَّآ أَلۡقَوۡاْ قَالَ\nT;0;10:81:0:مُوسَىٰ مَا جِئۡتُم بِهِ ٱلسِّحۡرُۖ إِنَّ ٱللَّهَ سَيُبۡطِلُهُۥٓ إِنَّ ٱللَّهَ لَا يُصۡلِحُ\nT;0;10:81:2:عَمَلَ ٱلۡمُفۡسِدِينَ¦10:82:1:وَيُحِقُّ ٱللَّهُ ٱلۡحَقَّ بِكَلِمَٰتِهِۦ وَلَوۡ كَرِهَ\nT;0;10:82:2:ٱلۡمُجۡرِمُونَ¦10:83:1:فَمَآ ءَامَنَ لِمُوسَىٰٓ إِلَّا ذُرِّيَّةࣱ مِّن قَوۡمِهِۦ عَلَىٰ\nT;0;10:83:0:خَوۡفࣲ مِّن فِرۡعَوۡنَ وَمَلَإِيْهِمۡ أَن يَفۡتِنَهُمۡۚ وَإِنَّ فِرۡعَوۡنَ لَعَالࣲ\nT;0;10:83:2:فِي ٱلۡأَرۡضِ وَإِنَّهُۥ لَمِنَ ٱلۡمُسۡرِفِينَ¦10:84:1:وَقَالَ مُوسَىٰ يَٰقَوۡمِ إِن\nT;0;10:84:2:كُنتُمۡ ءَامَنتُم بِٱللَّهِ فَعَلَيۡهِ تَوَكَّلُوٓاْ إِن كُنتُم مُّسۡلِمِينَ\nT;0;10:85:3:فَقَالُواْ عَلَى ٱللَّهِ تَوَكَّلۡنَا رَبَّنَا لَا تَجۡعَلۡنَا فِتۡنَةࣰ لِّلۡقَوۡمِ ٱلظَّٰلِمِينَ\nT;0;10:86:3:وَنَجِّنَا بِرَحۡمَتِكَ مِنَ ٱلۡقَوۡمِ ٱلۡكَٰفِرِينَ¦10:87:1:وَأَوۡحَيۡنَآ إِلَىٰ مُوسَىٰ\nT;0;10:87:0:وَأَخِيهِ أَن تَبَوَّءَا لِقَوۡمِكُمَا بِمِصۡرَ بُيُوتࣰا وَٱجۡعَلُواْ بُيُوتَكُمۡ\nT;0;10:87:2:قِبۡلَةࣰ وَأَقِيمُواْ ٱلصَّلَوٰةَۗ وَبَشِّرِ ٱلۡمُؤۡمِنِينَ¦10:88:1:وَقَالَ مُوسَىٰ\nT;0;10:88:0:رَبَّنَآ إِنَّكَ ءَاتَيۡتَ فِرۡعَوۡنَ وَمَلَأَهُۥ زِينَةࣰ وَأَمۡوَٰلࣰا فِي ٱلۡحَيَوٰةِ\nT;0;10:88:0:ٱلدُّنۡيَا رَبَّنَا لِيُضِلُّواْ عَن سَبِيلِكَۖ رَبَّنَا ٱطۡمِسۡ عَلَىٰٓ أَمۡوَٰلِهِمۡ\nT;0;10:88:2:وَٱشۡدُدۡ عَلَىٰ قُلُوبِهِمۡ فَلَا يُؤۡمِنُواْ حَتَّىٰ يَرَوُاْ ٱلۡعَذَابَ ٱلۡأَلِيمَ',
  '11;22;2;88\nT;0;10:89:1:قَالَ قَدۡ أُجِيبَت دَّعۡوَتُكُمَا فَٱسۡتَقِيمَا وَلَا تَتَّبِعَآنِّ سَبِيلَ\nT;0;10:89:2:ٱلَّذِينَ لَا يَعۡلَمُونَ¦10:90:1:۞ وَجَٰوَزۡنَا بِبَنِيٓ إِسۡرَٰٓءِيلَ ٱلۡبَحۡرَ فَأَتۡبَعَهُمۡ\nT;0;10:90:0:فِرۡعَوۡنُ وَجُنُودُهُۥ بَغۡيࣰا وَعَدۡوًاۖ حَتَّىٰٓ إِذَآ أَدۡرَكَهُ ٱلۡغَرَقُ\nT;0;10:90:0:قَالَ ءَامَنتُ أَنَّهُۥ لَآ إِلَٰهَ إِلَّا ٱلَّذِيٓ ءَامَنَتۡ بِهِۦ بَنُوٓاْ إِسۡرَٰٓءِيلَ\nT;0;10:90:2:وَأَنَا۠ مِنَ ٱلۡمُسۡلِمِينَ¦10:91:1:ءَآلۡـَٰٔنَ وَقَدۡ عَصَيۡتَ قَبۡلُ وَكُنتَ\nT;0;10:91:2:مِنَ ٱلۡمُفۡسِدِينَ¦10:92:1:فَٱلۡيَوۡمَ نُنَجِّيكَ بِبَدَنِكَ لِتَكُونَ لِمَنۡ\nT;0;10:92:2:خَلۡفَكَ ءَايَةࣰۚ وَإِنَّ كَثِيرࣰا مِّنَ ٱلنَّاسِ عَنۡ ءَايَٰتِنَا لَغَٰفِلُونَ\nT;0;10:93:1:وَلَقَدۡ بَوَّأۡنَا بَنِيٓ إِسۡرَٰٓءِيلَ مُبَوَّأَ صِدۡقࣲ وَرَزَقۡنَٰهُم مِّنَ\nT;0;10:93:0:ٱلطَّيِّبَٰتِ فَمَا ٱخۡتَلَفُواْ حَتَّىٰ جَآءَهُمُ ٱلۡعِلۡمُۚ إِنَّ رَبَّكَ يَقۡضِي\nT;0;10:93:2:بَيۡنَهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ فِيمَا كَانُواْ فِيهِ يَخۡتَلِفُونَ¦10:94:1:فَإِن كُنتَ فِي شَكࣲّ\nT;0;10:94:0:مِّمَّآ أَنزَلۡنَآ إِلَيۡكَ فَسۡـَٔلِ ٱلَّذِينَ يَقۡرَءُونَ ٱلۡكِتَٰبَ مِن\nT;0;10:94:2:قَبۡلِكَۚ لَقَدۡ جَآءَكَ ٱلۡحَقُّ مِن رَّبِّكَ فَلَا تَكُونَنَّ مِنَ ٱلۡمُمۡتَرِينَ\nT;0;10:95:3:وَلَا تَكُونَنَّ مِنَ ٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِ ٱللَّهِ فَتَكُونَ مِنَ ٱلۡخَٰسِرِينَ\nT;0;10:96:3:إِنَّ ٱلَّذِينَ حَقَّتۡ عَلَيۡهِمۡ كَلِمَتُ رَبِّكَ لَا يُؤۡمِنُونَ\nT;0;10:97:3:وَلَوۡ جَآءَتۡهُمۡ كُلُّ ءَايَةٍ حَتَّىٰ يَرَوُاْ ٱلۡعَذَابَ ٱلۡأَلِيمَ',
  '11;22;3;\nT;0;10:98:1:فَلَوۡلَا كَانَتۡ قَرۡيَةٌ ءَامَنَتۡ فَنَفَعَهَآ إِيمَٰنُهَآ إِلَّا قَوۡمَ يُونُسَ\nT;0;10:98:0:لَمَّآ ءَامَنُواْ كَشَفۡنَا عَنۡهُمۡ عَذَابَ ٱلۡخِزۡيِ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا\nT;0;10:98:2:وَمَتَّعۡنَٰهُمۡ إِلَىٰ حِينࣲ¦10:99:1:وَلَوۡ شَآءَ رَبُّكَ لَأٓمَنَ مَن فِي ٱلۡأَرۡضِ\nT;0;10:99:2:كُلُّهُمۡ جَمِيعًاۚ أَفَأَنتَ تُكۡرِهُ ٱلنَّاسَ حَتَّىٰ يَكُونُواْ مُؤۡمِنِينَ\nT;0;10:100:1:وَمَا كَانَ لِنَفۡسٍ أَن تُؤۡمِنَ إِلَّا بِإِذۡنِ ٱللَّهِۚ وَيَجۡعَلُ ٱلرِّجۡسَ\nT;0;10:100:2:عَلَى ٱلَّذِينَ لَا يَعۡقِلُونَ¦10:101:1:قُلِ ٱنظُرُواْ مَاذَا فِي ٱلسَّمَٰوَٰتِ\nT;0;10:101:2:وَٱلۡأَرۡضِۚ وَمَا تُغۡنِي ٱلۡأٓيَٰتُ وَٱلنُّذُرُ عَن قَوۡمࣲ لَّا يُؤۡمِنُونَ\nT;0;10:102:1:فَهَلۡ يَنتَظِرُونَ إِلَّا مِثۡلَ أَيَّامِ ٱلَّذِينَ خَلَوۡاْ مِن قَبۡلِهِمۡۚ\nT;0;10:102:2:قُلۡ فَٱنتَظِرُوٓاْ إِنِّي مَعَكُم مِّنَ ٱلۡمُنتَظِرِينَ¦10:103:1:ثُمَّ نُنَجِّي\nT;0;10:103:2:رُسُلَنَا وَٱلَّذِينَ ءَامَنُواْۚ كَذَٰلِكَ حَقًّا عَلَيۡنَا نُنجِ ٱلۡمُؤۡمِنِينَ\nT;0;10:104:1:قُلۡ يَٰٓأَيُّهَا ٱلنَّاسُ إِن كُنتُمۡ فِي شَكࣲّ مِّن دِينِي فَلَآ أَعۡبُدُ ٱلَّذِينَ\nT;0;10:104:0:تَعۡبُدُونَ مِن دُونِ ٱللَّهِ وَلَٰكِنۡ أَعۡبُدُ ٱللَّهَ ٱلَّذِي يَتَوَفَّىٰكُمۡۖ وَأُمِرۡتُ\nT;0;10:104:2:أَنۡ أَكُونَ مِنَ ٱلۡمُؤۡمِنِينَ¦10:105:1:وَأَنۡ أَقِمۡ وَجۡهَكَ لِلدِّينِ حَنِيفࣰا\nT;0;10:105:2:وَلَا تَكُونَنَّ مِنَ ٱلۡمُشۡرِكِينَ¦10:106:1:وَلَا تَدۡعُ مِن دُونِ ٱللَّهِ مَا لَا\nT;0;10:106:2:يَنفَعُكَ وَلَا يَضُرُّكَۖ فَإِن فَعَلۡتَ فَإِنَّكَ إِذࣰا مِّنَ ٱلظَّٰلِمِينَ',
  '11;22;3;\nT;0;10:107:1:وَإِن يَمۡسَسۡكَ ٱللَّهُ بِضُرࣲّ فَلَا كَاشِفَ لَهُۥٓ إِلَّا هُوَۖ وَإِن يُرِدۡكَ\nT;0;10:107:0:بِخَيۡرࣲ فَلَا رَآدَّ لِفَضۡلِهِۦۚ يُصِيبُ بِهِۦ مَن يَشَآءُ مِنۡ عِبَادِهِۦۚ\nT;0;10:107:2:وَهُوَ ٱلۡغَفُورُ ٱلرَّحِيمُ¦10:108:1:قُلۡ يَٰٓأَيُّهَا ٱلنَّاسُ قَدۡ جَآءَكُمُ ٱلۡحَقُّ\nT;0;10:108:0:مِن رَّبِّكُمۡۖ فَمَنِ ٱهۡتَدَىٰ فَإِنَّمَا يَهۡتَدِي لِنَفۡسِهِۦۖ وَمَن ضَلَّ\nT;0;10:108:2:فَإِنَّمَا يَضِلُّ عَلَيۡهَاۖ وَمَآ أَنَا۠ عَلَيۡكُم بِوَكِيلࣲ¦10:109:1:وَٱتَّبِعۡ مَا يُوحَىٰٓ\nT;2;10:109:2:إِلَيۡكَ وَٱصۡبِرۡ حَتَّىٰ يَحۡكُمَ ٱللَّهُۚ وَهُوَ خَيۡرُ ٱلۡحَٰكِمِينَ\nH;11\nB;11\nT;0;11:1:3:الٓرۚ كِتَٰبٌ أُحۡكِمَتۡ ءَايَٰتُهُۥ ثُمَّ فُصِّلَتۡ مِن لَّدُنۡ حَكِيمٍ خَبِيرٍ\nT;0;11:2:3:أَلَّا تَعۡبُدُوٓاْ إِلَّا ٱللَّهَۚ إِنَّنِي لَكُم مِّنۡهُ نَذِيرࣱ وَبَشِيرࣱ¦11:3:1:وَأَنِ ٱسۡتَغۡفِرُواْ\nT;0;11:3:0:رَبَّكُمۡ ثُمَّ تُوبُوٓاْ إِلَيۡهِ يُمَتِّعۡكُم مَّتَٰعًا حَسَنًا إِلَىٰٓ أَجَلࣲ مُّسَمࣰّى وَيُؤۡتِ\nT;0;11:3:0:كُلَّ ذِي فَضۡلࣲ فَضۡلَهُۥۖ وَإِن تَوَلَّوۡاْ فَإِنِّيٓ أَخَافُ عَلَيۡكُمۡ عَذَابَ يَوۡمࣲ\nT;0;11:3:2:كَبِيرٍ¦11:4:3:إِلَى ٱللَّهِ مَرۡجِعُكُمۡۖ وَهُوَ عَلَىٰ كُلِّ شَيۡءࣲ قَدِيرٌ¦11:5:1:أَلَآ إِنَّهُمۡ\nT;0;11:5:0:يَثۡنُونَ صُدُورَهُمۡ لِيَسۡتَخۡفُواْ مِنۡهُۚ أَلَا حِينَ يَسۡتَغۡشُونَ ثِيَابَهُمۡ\nT;0;11:5:2:يَعۡلَمُ مَا يُسِرُّونَ وَمَا يُعۡلِنُونَۚ إِنَّهُۥ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ',
  '12;23;0;89\nT;0;11:6:1:۞ وَمَا مِن دَآبَّةࣲ فِي ٱلۡأَرۡضِ إِلَّا عَلَى ٱللَّهِ رِزۡقُهَا وَيَعۡلَمُ\nT;0;11:6:2:مُسۡتَقَرَّهَا وَمُسۡتَوۡدَعَهَاۚ كُلࣱّ فِي كِتَٰبࣲ مُّبِينࣲ¦11:7:1:وَهُوَ\nT;0;11:7:0:ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ فِي سِتَّةِ أَيَّامࣲ وَكَانَ\nT;0;11:7:0:عَرۡشُهُۥ عَلَى ٱلۡمَآءِ لِيَبۡلُوَكُمۡ أَيُّكُمۡ أَحۡسَنُ عَمَلࣰاۗ وَلَئِن\nT;0;11:7:0:قُلۡتَ إِنَّكُم مَّبۡعُوثُونَ مِنۢ بَعۡدِ ٱلۡمَوۡتِ لَيَقُولَنَّ ٱلَّذِينَ كَفَرُوٓاْ\nT;0;11:7:2:إِنۡ هَٰذَآ إِلَّا سِحۡرࣱ مُّبِينࣱ¦11:8:1:وَلَئِنۡ أَخَّرۡنَا عَنۡهُمُ ٱلۡعَذَابَ إِلَىٰٓ\nT;0;11:8:0:أُمَّةࣲ مَّعۡدُودَةࣲ لَّيَقُولُنَّ مَا يَحۡبِسُهُۥٓۗ أَلَا يَوۡمَ يَأۡتِيهِمۡ لَيۡسَ\nT;0;11:8:2:مَصۡرُوفًا عَنۡهُمۡ وَحَاقَ بِهِم مَّا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ\nT;0;11:9:1:وَلَئِنۡ أَذَقۡنَا ٱلۡإِنسَٰنَ مِنَّا رَحۡمَةࣰ ثُمَّ نَزَعۡنَٰهَا مِنۡهُ إِنَّهُۥ\nT;0;11:9:2:لَيَـُٔوسࣱ كَفُورࣱ¦11:10:1:وَلَئِنۡ أَذَقۡنَٰهُ نَعۡمَآءَ بَعۡدَ ضَرَّآءَ\nT;0;11:10:2:مَسَّتۡهُ لَيَقُولَنَّ ذَهَبَ ٱلسَّيِّـَٔاتُ عَنِّيٓۚ إِنَّهُۥ لَفَرِحࣱ فَخُورٌ\nT;0;11:11:1:إِلَّا ٱلَّذِينَ صَبَرُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ أُوْلَٰٓئِكَ لَهُم\nT;0;11:11:2:مَّغۡفِرَةࣱ وَأَجۡرࣱ كَبِيرࣱ¦11:12:1:فَلَعَلَّكَ تَارِكُۢ بَعۡضَ مَا يُوحَىٰٓ إِلَيۡكَ\nT;0;11:12:0:وَضَآئِقُۢ بِهِۦ صَدۡرُكَ أَن يَقُولُواْ لَوۡلَآ أُنزِلَ عَلَيۡهِ كَنزٌ أَوۡ جَآءَ\nT;0;11:12:2:مَعَهُۥ مَلَكٌۚ إِنَّمَآ أَنتَ نَذِيرࣱۚ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءࣲ وَكِيلٌ',
  '12;23;0;\nT;0;11:13:1:أَمۡ يَقُولُونَ ٱفۡتَرَىٰهُۖ قُلۡ فَأۡتُواْ بِعَشۡرِ سُوَرࣲ مِّثۡلِهِۦ مُفۡتَرَيَٰتࣲ\nT;0;11:13:2:وَٱدۡعُواْ مَنِ ٱسۡتَطَعۡتُم مِّن دُونِ ٱللَّهِ إِن كُنتُمۡ صَٰدِقِينَ\nT;0;11:14:1:فَإِلَّمۡ يَسۡتَجِيبُواْ لَكُمۡ فَٱعۡلَمُوٓاْ أَنَّمَآ أُنزِلَ بِعِلۡمِ ٱللَّهِ وَأَن\nT;0;11:14:2:لَّآ إِلَٰهَ إِلَّا هُوَۖ فَهَلۡ أَنتُم مُّسۡلِمُونَ¦11:15:1:مَن كَانَ يُرِيدُ ٱلۡحَيَوٰةَ\nT;0;11:15:0:ٱلدُّنۡيَا وَزِينَتَهَا نُوَفِّ إِلَيۡهِمۡ أَعۡمَٰلَهُمۡ فِيهَا وَهُمۡ فِيهَا\nT;0;11:15:2:لَا يُبۡخَسُونَ¦11:16:1:أُوْلَٰٓئِكَ ٱلَّذِينَ لَيۡسَ لَهُمۡ فِي ٱلۡأٓخِرَةِ إِلَّا\nT;0;11:16:2:ٱلنَّارُۖ وَحَبِطَ مَا صَنَعُواْ فِيهَا وَبَٰطِلࣱ مَّا كَانُواْ يَعۡمَلُونَ\nT;0;11:17:1:أَفَمَن كَانَ عَلَىٰ بَيِّنَةࣲ مِّن رَّبِّهِۦ وَيَتۡلُوهُ شَاهِدࣱ مِّنۡهُ وَمِن قَبۡلِهِۦ\nT;0;11:17:0:كِتَٰبُ مُوسَىٰٓ إِمَامࣰا وَرَحۡمَةًۚ أُوْلَٰٓئِكَ يُؤۡمِنُونَ بِهِۦۚ وَمَن يَكۡفُرۡ\nT;0;11:17:0:بِهِۦ مِنَ ٱلۡأَحۡزَابِ فَٱلنَّارُ مَوۡعِدُهُۥۚ فَلَا تَكُ فِي مِرۡيَةࣲ مِّنۡهُۚ إِنَّهُ\nT;0;11:17:2:ٱلۡحَقُّ مِن رَّبِّكَ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يُؤۡمِنُونَ¦11:18:1:وَمَنۡ\nT;0;11:18:0:أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبًاۚ أُوْلَٰٓئِكَ يُعۡرَضُونَ عَلَىٰ\nT;0;11:18:0:رَبِّهِمۡ وَيَقُولُ ٱلۡأَشۡهَٰدُ هَٰٓؤُلَآءِ ٱلَّذِينَ كَذَبُواْ عَلَىٰ رَبِّهِمۡۚ\nT;0;11:18:2:أَلَا لَعۡنَةُ ٱللَّهِ عَلَى ٱلظَّٰلِمِينَ¦11:19:1:ٱلَّذِينَ يَصُدُّونَ عَن سَبِيلِ\nT;0;11:19:2:ٱللَّهِ وَيَبۡغُونَهَا عِوَجࣰا وَهُم بِٱلۡأٓخِرَةِ هُمۡ كَٰفِرُونَ',
  '12;23;0;90\nT;0;11:20:1:أُوْلَٰٓئِكَ لَمۡ يَكُونُواْ مُعۡجِزِينَ فِي ٱلۡأَرۡضِ وَمَا كَانَ لَهُم مِّن دُونِ\nT;0;11:20:0:ٱللَّهِ مِنۡ أَوۡلِيَآءَۘ يُضَٰعَفُ لَهُمُ ٱلۡعَذَابُۚ مَا كَانُواْ يَسۡتَطِيعُونَ\nT;0;11:20:2:ٱلسَّمۡعَ وَمَا كَانُواْ يُبۡصِرُونَ¦11:21:1:أُوْلَٰٓئِكَ ٱلَّذِينَ خَسِرُوٓاْ\nT;0;11:21:2:أَنفُسَهُمۡ وَضَلَّ عَنۡهُم مَّا كَانُواْ يَفۡتَرُونَ¦11:22:1:لَا جَرَمَ أَنَّهُمۡ\nT;0;11:22:2:فِي ٱلۡأٓخِرَةِ هُمُ ٱلۡأَخۡسَرُونَ¦11:23:1:إِنَّ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ\nT;0;11:23:0:ٱلصَّٰلِحَٰتِ وَأَخۡبَتُوٓاْ إِلَىٰ رَبِّهِمۡ أُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلۡجَنَّةِۖ\nT;0;11:23:2:هُمۡ فِيهَا خَٰلِدُونَ¦11:24:1:۞ مَثَلُ ٱلۡفَرِيقَيۡنِ كَٱلۡأَعۡمَىٰ وَٱلۡأَصَمِّ\nT;0;11:24:2:وَٱلۡبَصِيرِ وَٱلسَّمِيعِۚ هَلۡ يَسۡتَوِيَانِ مَثَلًاۚ أَفَلَا تَذَكَّرُونَ\nT;0;11:25:3:وَلَقَدۡ أَرۡسَلۡنَا نُوحًا إِلَىٰ قَوۡمِهِۦٓ إِنِّي لَكُمۡ نَذِيرࣱ مُّبِينٌ\nT;0;11:26:3:أَن لَّا تَعۡبُدُوٓاْ إِلَّا ٱللَّهَۖ إِنِّيٓ أَخَافُ عَلَيۡكُمۡ عَذَابَ يَوۡمٍ أَلِيمࣲ\nT;0;11:27:1:فَقَالَ ٱلۡمَلَأُ ٱلَّذِينَ كَفَرُواْ مِن قَوۡمِهِۦ مَا نَرَىٰكَ إِلَّا بَشَرࣰا مِّثۡلَنَا\nT;0;11:27:0:وَمَا نَرَىٰكَ ٱتَّبَعَكَ إِلَّا ٱلَّذِينَ هُمۡ أَرَاذِلُنَا بَادِيَ ٱلرَّأۡيِ\nT;0;11:27:2:وَمَا نَرَىٰ لَكُمۡ عَلَيۡنَا مِن فَضۡلِۭ بَلۡ نَظُنُّكُمۡ كَٰذِبِينَ\nT;0;11:28:1:قَالَ يَٰقَوۡمِ أَرَءَيۡتُمۡ إِن كُنتُ عَلَىٰ بَيِّنَةࣲ مِّن رَّبِّي وَءَاتَىٰنِي رَحۡمَةࣰ مِّنۡ\nT;0;11:28:2:عِندِهِۦ فَعُمِّيَتۡ عَلَيۡكُمۡ أَنُلۡزِمُكُمُوهَا وَأَنتُمۡ لَهَا كَٰرِهُونَ',
  '12;23;1;\nT;0;11:29:1:وَيَٰقَوۡمِ لَآ أَسۡـَٔلُكُمۡ عَلَيۡهِ مَالًاۖ إِنۡ أَجۡرِيَ إِلَّا عَلَى ٱللَّهِۚ وَمَآ أَنَا۠\nT;0;11:29:0:بِطَارِدِ ٱلَّذِينَ ءَامَنُوٓاْۚ إِنَّهُم مُّلَٰقُواْ رَبِّهِمۡ وَلَٰكِنِّيٓ أَرَىٰكُمۡ قَوۡمࣰا\nT;0;11:29:2:تَجۡهَلُونَ¦11:30:1:وَيَٰقَوۡمِ مَن يَنصُرُنِي مِنَ ٱللَّهِ إِن طَرَدتُّهُمۡۚ أَفَلَا\nT;0;11:30:2:تَذَكَّرُونَ¦11:31:1:وَلَآ أَقُولُ لَكُمۡ عِندِي خَزَآئِنُ ٱللَّهِ وَلَآ\nT;0;11:31:0:أَعۡلَمُ ٱلۡغَيۡبَ وَلَآ أَقُولُ إِنِّي مَلَكࣱ وَلَآ أَقُولُ لِلَّذِينَ تَزۡدَرِيٓ\nT;0;11:31:0:أَعۡيُنُكُمۡ لَن يُؤۡتِيَهُمُ ٱللَّهُ خَيۡرًاۖ ٱللَّهُ أَعۡلَمُ بِمَا فِيٓ أَنفُسِهِمۡ إِنِّيٓ\nT;0;11:31:2:إِذࣰا لَّمِنَ ٱلظَّٰلِمِينَ¦11:32:1:قَالُواْ يَٰنُوحُ قَدۡ جَٰدَلۡتَنَا فَأَكۡثَرۡتَ جِدَٰلَنَا\nT;0;11:32:2:فَأۡتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ¦11:33:1:قَالَ إِنَّمَا\nT;0;11:33:2:يَأۡتِيكُم بِهِ ٱللَّهُ إِن شَآءَ وَمَآ أَنتُم بِمُعۡجِزِينَ¦11:34:1:وَلَا يَنفَعُكُمۡ\nT;0;11:34:0:نُصۡحِيٓ إِنۡ أَرَدتُّ أَنۡ أَنصَحَ لَكُمۡ إِن كَانَ ٱللَّهُ يُرِيدُ أَن\nT;0;11:34:2:يُغۡوِيَكُمۡۚ هُوَ رَبُّكُمۡ وَإِلَيۡهِ تُرۡجَعُونَ¦11:35:1:أَمۡ يَقُولُونَ ٱفۡتَرَىٰهُۖ\nT;0;11:35:2:قُلۡ إِنِ ٱفۡتَرَيۡتُهُۥ فَعَلَيَّ إِجۡرَامِي وَأَنَا۠ بَرِيٓءࣱ مِّمَّا تُجۡرِمُونَ\nT;0;11:36:1:وَأُوحِيَ إِلَىٰ نُوحٍ أَنَّهُۥ لَن يُؤۡمِنَ مِن قَوۡمِكَ إِلَّا مَن قَدۡ ءَامَنَ\nT;0;11:36:2:فَلَا تَبۡتَئِسۡ بِمَا كَانُواْ يَفۡعَلُونَ¦11:37:1:وَٱصۡنَعِ ٱلۡفُلۡكَ بِأَعۡيُنِنَا\nT;0;11:37:2:وَوَحۡيِنَا وَلَا تُخَٰطِبۡنِي فِي ٱلَّذِينَ ظَلَمُوٓاْ إِنَّهُم مُّغۡرَقُونَ',
  '12;23;1;91\nT;0;11:38:1:وَيَصۡنَعُ ٱلۡفُلۡكَ وَكُلَّمَا مَرَّ عَلَيۡهِ مَلَأࣱ مِّن قَوۡمِهِۦ سَخِرُواْ مِنۡهُۚ\nT;0;11:38:2:قَالَ إِن تَسۡخَرُواْ مِنَّا فَإِنَّا نَسۡخَرُ مِنكُمۡ كَمَا تَسۡخَرُونَ\nT;0;11:39:1:فَسَوۡفَ تَعۡلَمُونَ مَن يَأۡتِيهِ عَذَابࣱ يُخۡزِيهِ وَيَحِلُّ عَلَيۡهِ عَذَابࣱ\nT;0;11:39:2:مُّقِيمٌ¦11:40:1:حَتَّىٰٓ إِذَا جَآءَ أَمۡرُنَا وَفَارَ ٱلتَّنُّورُ قُلۡنَا ٱحۡمِلۡ فِيهَا\nT;0;11:40:0:مِن كُلࣲّ زَوۡجَيۡنِ ٱثۡنَيۡنِ وَأَهۡلَكَ إِلَّا مَن سَبَقَ عَلَيۡهِ ٱلۡقَوۡلُ\nT;0;11:40:2:وَمَنۡ ءَامَنَۚ وَمَآ ءَامَنَ مَعَهُۥٓ إِلَّا قَلِيلࣱ¦11:41:1:۞ وَقَالَ ٱرۡكَبُواْ فِيهَا\nT;0;11:41:2:بِسۡمِ ٱللَّهِ مَجۡرٜىٰهَا وَمُرۡسَىٰهَآۚ إِنَّ رَبِّي لَغَفُورࣱ رَّحِيمࣱ\nT;0;11:42:1:وَهِيَ تَجۡرِي بِهِمۡ فِي مَوۡجࣲ كَٱلۡجِبَالِ وَنَادَىٰ نُوحٌ ٱبۡنَهُۥ\nT;0;11:42:2:وَكَانَ فِي مَعۡزِلࣲ يَٰبُنَيَّ ٱرۡكَب مَّعَنَا وَلَا تَكُن مَّعَ ٱلۡكَٰفِرِينَ\nT;0;11:43:1:قَالَ سَـَٔاوِيٓ إِلَىٰ جَبَلࣲ يَعۡصِمُنِي مِنَ ٱلۡمَآءِۚ قَالَ لَا عَاصِمَ ٱلۡيَوۡمَ\nT;0;11:43:0:مِنۡ أَمۡرِ ٱللَّهِ إِلَّا مَن رَّحِمَۚ وَحَالَ بَيۡنَهُمَا ٱلۡمَوۡجُ فَكَانَ مِنَ\nT;0;11:43:2:ٱلۡمُغۡرَقِينَ¦11:44:1:وَقِيلَ يَٰٓأَرۡضُ ٱبۡلَعِي مَآءَكِ وَيَٰسَمَآءُ أَقۡلِعِي\nT;0;11:44:0:وَغِيضَ ٱلۡمَآءُ وَقُضِيَ ٱلۡأَمۡرُ وَٱسۡتَوَتۡ عَلَى ٱلۡجُودِيِّۖ وَقِيلَ\nT;0;11:44:2:بُعۡدࣰا لِّلۡقَوۡمِ ٱلظَّٰلِمِينَ¦11:45:1:وَنَادَىٰ نُوحࣱ رَّبَّهُۥ فَقَالَ رَبِّ إِنَّ ٱبۡنِي\nT;0;11:45:2:مِنۡ أَهۡلِي وَإِنَّ وَعۡدَكَ ٱلۡحَقُّ وَأَنتَ أَحۡكَمُ ٱلۡحَٰكِمِينَ',
  '12;23;2;\nT;0;11:46:1:قَالَ يَٰنُوحُ إِنَّهُۥ لَيۡسَ مِنۡ أَهۡلِكَۖ إِنَّهُۥ عَمَلٌ غَيۡرُ صَٰلِحࣲۖ فَلَا تَسۡـَٔلۡنِ\nT;0;11:46:2:مَا لَيۡسَ لَكَ بِهِۦ عِلۡمٌۖ إِنِّيٓ أَعِظُكَ أَن تَكُونَ مِنَ ٱلۡجَٰهِلِينَ\nT;0;11:47:1:قَالَ رَبِّ إِنِّيٓ أَعُوذُ بِكَ أَنۡ أَسۡـَٔلَكَ مَا لَيۡسَ لِي بِهِۦ عِلۡمࣱۖ وَإِلَّا\nT;0;11:47:2:تَغۡفِرۡ لِي وَتَرۡحَمۡنِيٓ أَكُن مِّنَ ٱلۡخَٰسِرِينَ¦11:48:1:قِيلَ يَٰنُوحُ\nT;0;11:48:0:ٱهۡبِطۡ بِسَلَٰمࣲ مِّنَّا وَبَرَكَٰتٍ عَلَيۡكَ وَعَلَىٰٓ أُمَمࣲ مِّمَّن مَّعَكَۚ\nT;0;11:48:2:وَأُمَمࣱ سَنُمَتِّعُهُمۡ ثُمَّ يَمَسُّهُم مِّنَّا عَذَابٌ أَلِيمࣱ¦11:49:1:تِلۡكَ\nT;0;11:49:0:مِنۡ أَنۢبَآءِ ٱلۡغَيۡبِ نُوحِيهَآ إِلَيۡكَۖ مَا كُنتَ تَعۡلَمُهَآ أَنتَ\nT;0;11:49:2:وَلَا قَوۡمُكَ مِن قَبۡلِ هَٰذَاۖ فَٱصۡبِرۡۖ إِنَّ ٱلۡعَٰقِبَةَ لِلۡمُتَّقِينَ\nT;0;11:50:1:وَإِلَىٰ عَادٍ أَخَاهُمۡ هُودࣰاۚ قَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ\nT;0;11:50:2:إِلَٰهٍ غَيۡرُهُۥٓۖ إِنۡ أَنتُمۡ إِلَّا مُفۡتَرُونَ¦11:51:1:يَٰقَوۡمِ لَآ أَسۡـَٔلُكُمۡ عَلَيۡهِ\nT;0;11:51:2:أَجۡرًاۖ إِنۡ أَجۡرِيَ إِلَّا عَلَى ٱلَّذِي فَطَرَنِيٓۚ أَفَلَا تَعۡقِلُونَ\nT;0;11:52:1:وَيَٰقَوۡمِ ٱسۡتَغۡفِرُواْ رَبَّكُمۡ ثُمَّ تُوبُوٓاْ إِلَيۡهِ يُرۡسِلِ ٱلسَّمَآءَ\nT;0;11:52:0:عَلَيۡكُم مِّدۡرَارࣰا وَيَزِدۡكُمۡ قُوَّةً إِلَىٰ قُوَّتِكُمۡ وَلَا تَتَوَلَّوۡاْ\nT;0;11:52:2:مُجۡرِمِينَ¦11:53:1:قَالُواْ يَٰهُودُ مَا جِئۡتَنَا بِبَيِّنَةࣲ وَمَا نَحۡنُ\nT;0;11:53:2:بِتَارِكِيٓ ءَالِهَتِنَا عَن قَوۡلِكَ وَمَا نَحۡنُ لَكَ بِمُؤۡمِنِينَ',
  '12;23;2;92\nT;0;11:54:1:إِن نَّقُولُ إِلَّا ٱعۡتَرَىٰكَ بَعۡضُ ءَالِهَتِنَا بِسُوٓءࣲۗ قَالَ إِنِّيٓ أُشۡهِدُ ٱللَّهَ\nT;0;11:54:2:وَٱشۡهَدُوٓاْ أَنِّي بَرِيٓءࣱ مِّمَّا تُشۡرِكُونَ¦11:55:1:مِن دُونِهِۦۖ فَكِيدُونِي\nT;0;11:55:2:جَمِيعࣰا ثُمَّ لَا تُنظِرُونِ¦11:56:1:إِنِّي تَوَكَّلۡتُ عَلَى ٱللَّهِ رَبِّي وَرَبِّكُمۚ مَّا مِن\nT;0;11:56:2:دَآبَّةٍ إِلَّا هُوَ ءَاخِذُۢ بِنَاصِيَتِهَآۚ إِنَّ رَبِّي عَلَىٰ صِرَٰطࣲ مُّسۡتَقِيمࣲ\nT;0;11:57:1:فَإِن تَوَلَّوۡاْ فَقَدۡ أَبۡلَغۡتُكُم مَّآ أُرۡسِلۡتُ بِهِۦٓ إِلَيۡكُمۡۚ وَيَسۡتَخۡلِفُ رَبِّي\nT;0;11:57:2:قَوۡمًا غَيۡرَكُمۡ وَلَا تَضُرُّونَهُۥ شَيۡـًٔاۚ إِنَّ رَبِّي عَلَىٰ كُلِّ شَيۡءٍ حَفِيظࣱ\nT;0;11:58:1:وَلَمَّا جَآءَ أَمۡرُنَا نَجَّيۡنَا هُودࣰا وَٱلَّذِينَ ءَامَنُواْ مَعَهُۥ بِرَحۡمَةࣲ مِّنَّا\nT;0;11:58:2:وَنَجَّيۡنَٰهُم مِّنۡ عَذَابٍ غَلِيظࣲ¦11:59:1:وَتِلۡكَ عَادࣱۖ جَحَدُواْ بِـَٔايَٰتِ\nT;0;11:59:2:رَبِّهِمۡ وَعَصَوۡاْ رُسُلَهُۥ وَٱتَّبَعُوٓاْ أَمۡرَ كُلِّ جَبَّارٍ عَنِيدࣲ¦11:60:1:وَأُتۡبِعُواْ فِي\nT;0;11:60:0:هَٰذِهِ ٱلدُّنۡيَا لَعۡنَةࣰ وَيَوۡمَ ٱلۡقِيَٰمَةِۗ أَلَآ إِنَّ عَادࣰا كَفَرُواْ رَبَّهُمۡۗ أَلَا\nT;0;11:60:2:بُعۡدࣰا لِّعَادࣲ قَوۡمِ هُودࣲ¦11:61:1:۞ وَإِلَىٰ ثَمُودَ أَخَاهُمۡ صَٰلِحࣰاۚ قَالَ يَٰقَوۡمِ\nT;0;11:61:0:ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥۖ هُوَ أَنشَأَكُم مِّنَ ٱلۡأَرۡضِ\nT;0;11:61:2:وَٱسۡتَعۡمَرَكُمۡ فِيهَا فَٱسۡتَغۡفِرُوهُ ثُمَّ تُوبُوٓاْ إِلَيۡهِۚ إِنَّ رَبِّي قَرِيبࣱ مُّجِيبࣱ\nT;0;11:62:1:قَالُواْ يَٰصَٰلِحُ قَدۡ كُنتَ فِينَا مَرۡجُوࣰّا قَبۡلَ هَٰذَآۖ أَتَنۡهَىٰنَآ أَن نَّعۡبُدَ\nT;0;11:62:2:مَا يَعۡبُدُ ءَابَآؤُنَا وَإِنَّنَا لَفِي شَكࣲّ مِّمَّا تَدۡعُونَآ إِلَيۡهِ مُرِيبࣲ',
  '12;23;3;\nT;0;11:63:1:قَالَ يَٰقَوۡمِ أَرَءَيۡتُمۡ إِن كُنتُ عَلَىٰ بَيِّنَةࣲ مِّن رَّبِّي وَءَاتَىٰنِي\nT;0;11:63:0:مِنۡهُ رَحۡمَةࣰ فَمَن يَنصُرُنِي مِنَ ٱللَّهِ إِنۡ عَصَيۡتُهُۥۖ فَمَا تَزِيدُونَنِي\nT;0;11:63:2:غَيۡرَ تَخۡسِيرࣲ¦11:64:1:وَيَٰقَوۡمِ هَٰذِهِۦ نَاقَةُ ٱللَّهِ لَكُمۡ ءَايَةࣰۖ\nT;0;11:64:0:فَذَرُوهَا تَأۡكُلۡ فِيٓ أَرۡضِ ٱللَّهِۖ وَلَا تَمَسُّوهَا بِسُوٓءࣲ فَيَأۡخُذَكُمۡ\nT;0;11:64:2:عَذَابࣱ قَرِيبࣱ¦11:65:1:فَعَقَرُوهَا فَقَالَ تَمَتَّعُواْ فِي دَارِكُمۡ\nT;0;11:65:2:ثَلَٰثَةَ أَيَّامࣲۖ ذَٰلِكَ وَعۡدٌ غَيۡرُ مَكۡذُوبࣲ¦11:66:1:فَلَمَّا جَآءَ أَمۡرُنَا\nT;0;11:66:0:نَجَّيۡنَا صَٰلِحࣰا وَٱلَّذِينَ ءَامَنُواْ مَعَهُۥ بِرَحۡمَةࣲ مِّنَّا وَمِنۡ\nT;0;11:66:2:خِزۡيِ يَوۡمِئِذٍۚ إِنَّ رَبَّكَ هُوَ ٱلۡقَوِيُّ ٱلۡعَزِيزُ¦11:67:1:وَأَخَذَ ٱلَّذِينَ\nT;0;11:67:2:ظَلَمُواْ ٱلصَّيۡحَةُ فَأَصۡبَحُواْ فِي دِيَٰرِهِمۡ جَٰثِمِينَ\nT;0;11:68:1:كَأَن لَّمۡ يَغۡنَوۡاْ فِيهَآۗ أَلَآ إِنَّ ثَمُودَاْ كَفَرُواْ رَبَّهُمۡۗ أَلَا\nT;0;11:68:2:بُعۡدࣰا لِّثَمُودَ¦11:69:1:وَلَقَدۡ جَآءَتۡ رُسُلُنَآ إِبۡرَٰهِيمَ بِٱلۡبُشۡرَىٰ قَالُواْ\nT;0;11:69:2:سَلَٰمࣰاۖ قَالَ سَلَٰمࣱۖ فَمَا لَبِثَ أَن جَآءَ بِعِجۡلٍ حَنِيذࣲ¦11:70:1:فَلَمَّا رَءَآ\nT;0;11:70:0:أَيۡدِيَهُمۡ لَا تَصِلُ إِلَيۡهِ نَكِرَهُمۡ وَأَوۡجَسَ مِنۡهُمۡ خِيفَةࣰۚ\nT;0;11:70:2:قَالُواْ لَا تَخَفۡ إِنَّآ أُرۡسِلۡنَآ إِلَىٰ قَوۡمِ لُوطࣲ¦11:71:1:وَٱمۡرَأَتُهُۥ قَآئِمَةࣱ\nT;0;11:71:2:فَضَحِكَتۡ فَبَشَّرۡنَٰهَا بِإِسۡحَٰقَ وَمِن وَرَآءِ إِسۡحَٰقَ يَعۡقُوبَ',
  '12;23;3;\nT;0;11:72:1:قَالَتۡ يَٰوَيۡلَتَىٰٓ ءَأَلِدُ وَأَنَا۠ عَجُوزࣱ وَهَٰذَا بَعۡلِي شَيۡخًاۖ إِنَّ هَٰذَا\nT;0;11:72:2:لَشَيۡءٌ عَجِيبࣱ¦11:73:1:قَالُوٓاْ أَتَعۡجَبِينَ مِنۡ أَمۡرِ ٱللَّهِۖ رَحۡمَتُ ٱللَّهِ\nT;0;11:73:2:وَبَرَكَٰتُهُۥ عَلَيۡكُمۡ أَهۡلَ ٱلۡبَيۡتِۚ إِنَّهُۥ حَمِيدࣱ مَّجِيدࣱ¦11:74:1:فَلَمَّا ذَهَبَ\nT;0;11:74:2:عَنۡ إِبۡرَٰهِيمَ ٱلرَّوۡعُ وَجَآءَتۡهُ ٱلۡبُشۡرَىٰ يُجَٰدِلُنَا فِي قَوۡمِ لُوطٍ\nT;0;11:75:3:إِنَّ إِبۡرَٰهِيمَ لَحَلِيمٌ أَوَّٰهࣱ مُّنِيبࣱ¦11:76:1:يَٰٓإِبۡرَٰهِيمُ أَعۡرِضۡ عَنۡ هَٰذَآۖ إِنَّهُۥ\nT;0;11:76:2:قَدۡ جَآءَ أَمۡرُ رَبِّكَۖ وَإِنَّهُمۡ ءَاتِيهِمۡ عَذَابٌ غَيۡرُ مَرۡدُودࣲ¦11:77:1:وَلَمَّا\nT;0;11:77:0:جَآءَتۡ رُسُلُنَا لُوطࣰا سِيٓءَ بِهِمۡ وَضَاقَ بِهِمۡ ذَرۡعࣰا وَقَالَ هَٰذَا\nT;0;11:77:2:يَوۡمٌ عَصِيبࣱ¦11:78:1:وَجَآءَهُۥ قَوۡمُهُۥ يُهۡرَعُونَ إِلَيۡهِ وَمِن قَبۡلُ كَانُواْ\nT;0;11:78:0:يَعۡمَلُونَ ٱلسَّيِّـَٔاتِۚ قَالَ يَٰقَوۡمِ هَٰٓؤُلَآءِ بَنَاتِي هُنَّ أَطۡهَرُ لَكُمۡۖ\nT;0;11:78:2:فَٱتَّقُواْ ٱللَّهَ وَلَا تُخۡزُونِ فِي ضَيۡفِيٓۖ أَلَيۡسَ مِنكُمۡ رَجُلࣱ رَّشِيدࣱ\nT;0;11:79:3:قَالُواْ لَقَدۡ عَلِمۡتَ مَا لَنَا فِي بَنَاتِكَ مِنۡ حَقࣲّ وَإِنَّكَ لَتَعۡلَمُ مَا نُرِيدُ\nT;0;11:80:3:قَالَ لَوۡ أَنَّ لِي بِكُمۡ قُوَّةً أَوۡ ءَاوِيٓ إِلَىٰ رُكۡنࣲ شَدِيدࣲ¦11:81:1:قَالُواْ\nT;0;11:81:0:يَٰلُوطُ إِنَّا رُسُلُ رَبِّكَ لَن يَصِلُوٓاْ إِلَيۡكَۖ فَأَسۡرِ بِأَهۡلِكَ بِقِطۡعࣲ\nT;0;11:81:0:مِّنَ ٱلَّيۡلِ وَلَا يَلۡتَفِتۡ مِنكُمۡ أَحَدٌ إِلَّا ٱمۡرَأَتَكَۖ إِنَّهُۥ مُصِيبُهَا\nT;0;11:81:2:مَآ أَصَابَهُمۡۚ إِنَّ مَوۡعِدَهُمُ ٱلصُّبۡحُۚ أَلَيۡسَ ٱلصُّبۡحُ بِقَرِيبࣲ',
  '12;23;3;93\nT;0;11:82:1:فَلَمَّا جَآءَ أَمۡرُنَا جَعَلۡنَا عَٰلِيَهَا سَافِلَهَا وَأَمۡطَرۡنَا عَلَيۡهَا\nT;0;11:82:2:حِجَارَةࣰ مِّن سِجِّيلࣲ مَّنضُودࣲ¦11:83:1:مُّسَوَّمَةً عِندَ رَبِّكَۖ\nT;0;11:83:2:وَمَا هِيَ مِنَ ٱلظَّٰلِمِينَ بِبَعِيدࣲ¦11:84:1:۞ وَإِلَىٰ مَدۡيَنَ أَخَاهُمۡ\nT;0;11:84:0:شُعَيۡبࣰاۚ قَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥۖ\nT;0;11:84:0:وَلَا تَنقُصُواْ ٱلۡمِكۡيَالَ وَٱلۡمِيزَانَۖ إِنِّيٓ أَرَىٰكُم بِخَيۡرࣲ\nT;0;11:84:2:وَإِنِّيٓ أَخَافُ عَلَيۡكُمۡ عَذَابَ يَوۡمࣲ مُّحِيطࣲ¦11:85:1:وَيَٰقَوۡمِ\nT;0;11:85:0:أَوۡفُواْ ٱلۡمِكۡيَالَ وَٱلۡمِيزَانَ بِٱلۡقِسۡطِۖ وَلَا تَبۡخَسُواْ ٱلنَّاسَ\nT;0;11:85:2:أَشۡيَآءَهُمۡ وَلَا تَعۡثَوۡاْ فِي ٱلۡأَرۡضِ مُفۡسِدِينَ¦11:86:1:بَقِيَّتُ\nT;0;11:86:0:ٱللَّهِ خَيۡرࣱ لَّكُمۡ إِن كُنتُم مُّؤۡمِنِينَۚ وَمَآ أَنَا۠ عَلَيۡكُم\nT;0;11:86:2:بِحَفِيظࣲ¦11:87:1:قَالُواْ يَٰشُعَيۡبُ أَصَلَوٰتُكَ تَأۡمُرُكَ أَن نَّتۡرُكَ\nT;0;11:87:0:مَا يَعۡبُدُ ءَابَآؤُنَآ أَوۡ أَن نَّفۡعَلَ فِيٓ أَمۡوَٰلِنَا مَا نَشَٰٓؤُاْۖ إِنَّكَ\nT;0;11:87:2:لَأَنتَ ٱلۡحَلِيمُ ٱلرَّشِيدُ¦11:88:1:قَالَ يَٰقَوۡمِ أَرَءَيۡتُمۡ إِن كُنتُ\nT;0;11:88:0:عَلَىٰ بَيِّنَةࣲ مِّن رَّبِّي وَرَزَقَنِي مِنۡهُ رِزۡقًا حَسَنࣰاۚ وَمَآ أُرِيدُ أَنۡ\nT;0;11:88:0:أُخَالِفَكُمۡ إِلَىٰ مَآ أَنۡهَىٰكُمۡ عَنۡهُۚ إِنۡ أُرِيدُ إِلَّا ٱلۡإِصۡلَٰحَ\nT;0;11:88:2:مَا ٱسۡتَطَعۡتُۚ وَمَا تَوۡفِيقِيٓ إِلَّا بِٱللَّهِۚ عَلَيۡهِ تَوَكَّلۡتُ وَإِلَيۡهِ أُنِيبُ',
  '12;24;0;\nT;0;11:89:1:وَيَٰقَوۡمِ لَا يَجۡرِمَنَّكُمۡ شِقَاقِيٓ أَن يُصِيبَكُم مِّثۡلُ مَآ أَصَابَ\nT;0;11:89:0:قَوۡمَ نُوحٍ أَوۡ قَوۡمَ هُودٍ أَوۡ قَوۡمَ صَٰلِحࣲۚ وَمَا قَوۡمُ لُوطࣲ مِّنكُم\nT;0;11:89:2:بِبَعِيدࣲ¦11:90:1:وَٱسۡتَغۡفِرُواْ رَبَّكُمۡ ثُمَّ تُوبُوٓاْ إِلَيۡهِۚ إِنَّ رَبِّي\nT;0;11:90:2:رَحِيمࣱ وَدُودࣱ¦11:91:1:قَالُواْ يَٰشُعَيۡبُ مَا نَفۡقَهُ كَثِيرࣰا مِّمَّا تَقُولُ\nT;0;11:91:0:وَإِنَّا لَنَرَىٰكَ فِينَا ضَعِيفࣰاۖ وَلَوۡلَا رَهۡطُكَ لَرَجَمۡنَٰكَۖ وَمَآ أَنتَ\nT;0;11:91:2:عَلَيۡنَا بِعَزِيزࣲ¦11:92:1:قَالَ يَٰقَوۡمِ أَرَهۡطِيٓ أَعَزُّ عَلَيۡكُم مِّنَ ٱللَّهِ\nT;0;11:92:0:وَٱتَّخَذۡتُمُوهُ وَرَآءَكُمۡ ظِهۡرِيًّاۖ إِنَّ رَبِّي بِمَا تَعۡمَلُونَ\nT;0;11:92:2:مُحِيطࣱ¦11:93:1:وَيَٰقَوۡمِ ٱعۡمَلُواْ عَلَىٰ مَكَانَتِكُمۡ إِنِّي عَٰمِلࣱۖ\nT;0;11:93:0:سَوۡفَ تَعۡلَمُونَ مَن يَأۡتِيهِ عَذَابࣱ يُخۡزِيهِ وَمَنۡ هُوَ كَٰذِبࣱۖ\nT;0;11:93:2:وَٱرۡتَقِبُوٓاْ إِنِّي مَعَكُمۡ رَقِيبࣱ¦11:94:1:وَلَمَّا جَآءَ أَمۡرُنَا نَجَّيۡنَا\nT;0;11:94:0:شُعَيۡبࣰا وَٱلَّذِينَ ءَامَنُواْ مَعَهُۥ بِرَحۡمَةࣲ مِّنَّا وَأَخَذَتِ\nT;0;11:94:2:ٱلَّذِينَ ظَلَمُواْ ٱلصَّيۡحَةُ فَأَصۡبَحُواْ فِي دِيَٰرِهِمۡ جَٰثِمِينَ\nT;0;11:95:3:كَأَن لَّمۡ يَغۡنَوۡاْ فِيهَآۗ أَلَا بُعۡدࣰا لِّمَدۡيَنَ كَمَا بَعِدَتۡ ثَمُودُ\nT;0;11:96:3:وَلَقَدۡ أَرۡسَلۡنَا مُوسَىٰ بِـَٔايَٰتِنَا وَسُلۡطَٰنࣲ مُّبِينٍ¦11:97:1:إِلَىٰ فِرۡعَوۡنَ\nT;0;11:97:2:وَمَلَإِيْهِۦ فَٱتَّبَعُوٓاْ أَمۡرَ فِرۡعَوۡنَۖ وَمَآ أَمۡرُ فِرۡعَوۡنَ بِرَشِيدࣲ',
  '12;24;0;94\nT;0;11:98:1:يَقۡدُمُ قَوۡمَهُۥ يَوۡمَ ٱلۡقِيَٰمَةِ فَأَوۡرَدَهُمُ ٱلنَّارَۖ وَبِئۡسَ ٱلۡوِرۡدُ\nT;0;11:98:2:ٱلۡمَوۡرُودُ¦11:99:1:وَأُتۡبِعُواْ فِي هَٰذِهِۦ لَعۡنَةࣰ وَيَوۡمَ ٱلۡقِيَٰمَةِۚ بِئۡسَ\nT;0;11:99:2:ٱلرِّفۡدُ ٱلۡمَرۡفُودُ¦11:100:1:ذَٰلِكَ مِنۡ أَنۢبَآءِ ٱلۡقُرَىٰ نَقُصُّهُۥ عَلَيۡكَۖ\nT;0;11:100:2:مِنۡهَا قَآئِمࣱ وَحَصِيدࣱ¦11:101:1:وَمَا ظَلَمۡنَٰهُمۡ وَلَٰكِن ظَلَمُوٓاْ\nT;0;11:101:0:أَنفُسَهُمۡۖ فَمَآ أَغۡنَتۡ عَنۡهُمۡ ءَالِهَتُهُمُ ٱلَّتِي يَدۡعُونَ مِن دُونِ\nT;0;11:101:2:ٱللَّهِ مِن شَيۡءࣲ لَّمَّا جَآءَ أَمۡرُ رَبِّكَۖ وَمَا زَادُوهُمۡ غَيۡرَ تَتۡبِيبࣲ\nT;0;11:102:1:وَكَذَٰلِكَ أَخۡذُ رَبِّكَ إِذَآ أَخَذَ ٱلۡقُرَىٰ وَهِيَ ظَٰلِمَةٌۚ إِنَّ أَخۡذَهُۥٓ\nT;0;11:102:2:أَلِيمࣱ شَدِيدٌ¦11:103:1:إِنَّ فِي ذَٰلِكَ لَأٓيَةࣰ لِّمَنۡ خَافَ عَذَابَ ٱلۡأٓخِرَةِۚ\nT;0;11:103:2:ذَٰلِكَ يَوۡمࣱ مَّجۡمُوعࣱ لَّهُ ٱلنَّاسُ وَذَٰلِكَ يَوۡمࣱ مَّشۡهُودࣱ\nT;0;11:104:3:وَمَا نُؤَخِّرُهُۥٓ إِلَّا لِأَجَلࣲ مَّعۡدُودࣲ¦11:105:1:يَوۡمَ يَأۡتِ لَا تَكَلَّمُ نَفۡسٌ\nT;0;11:105:2:إِلَّا بِإِذۡنِهِۦۚ فَمِنۡهُمۡ شَقِيࣱّ وَسَعِيدࣱ¦11:106:1:فَأَمَّا ٱلَّذِينَ شَقُواْ فَفِي\nT;0;11:106:2:ٱلنَّارِ لَهُمۡ فِيهَا زَفِيرࣱ وَشَهِيقٌ¦11:107:1:خَٰلِدِينَ فِيهَا مَا دَامَتِ ٱلسَّمَٰوَٰتُ\nT;0;11:107:2:وَٱلۡأَرۡضُ إِلَّا مَا شَآءَ رَبُّكَۚ إِنَّ رَبَّكَ فَعَّالࣱ لِّمَا يُرِيدُ\nT;0;11:108:1:۞ وَأَمَّا ٱلَّذِينَ سُعِدُواْ فَفِي ٱلۡجَنَّةِ خَٰلِدِينَ فِيهَا مَا دَامَتِ\nT;0;11:108:2:ٱلسَّمَٰوَٰتُ وَٱلۡأَرۡضُ إِلَّا مَا شَآءَ رَبُّكَۖ عَطَآءً غَيۡرَ مَجۡذُوذࣲ',
  '12;24;1;\nT;0;11:109:1:فَلَا تَكُ فِي مِرۡيَةࣲ مِّمَّا يَعۡبُدُ هَٰٓؤُلَآءِۚ مَا يَعۡبُدُونَ إِلَّا كَمَا يَعۡبُدُ\nT;0;11:109:2:ءَابَآؤُهُم مِّن قَبۡلُۚ وَإِنَّا لَمُوَفُّوهُمۡ نَصِيبَهُمۡ غَيۡرَ مَنقُوصࣲ\nT;0;11:110:1:وَلَقَدۡ ءَاتَيۡنَا مُوسَى ٱلۡكِتَٰبَ فَٱخۡتُلِفَ فِيهِۚ وَلَوۡلَا كَلِمَةࣱ\nT;0;11:110:2:سَبَقَتۡ مِن رَّبِّكَ لَقُضِيَ بَيۡنَهُمۡۚ وَإِنَّهُمۡ لَفِي شَكࣲّ مِّنۡهُ مُرِيبࣲ\nT;0;11:111:1:وَإِنَّ كُلࣰّا لَّمَّا لَيُوَفِّيَنَّهُمۡ رَبُّكَ أَعۡمَٰلَهُمۡۚ إِنَّهُۥ بِمَا يَعۡمَلُونَ\nT;0;11:111:2:خَبِيرࣱ¦11:112:1:فَٱسۡتَقِمۡ كَمَآ أُمِرۡتَ وَمَن تَابَ مَعَكَ وَلَا تَطۡغَوۡاْۚ\nT;0;11:112:2:إِنَّهُۥ بِمَا تَعۡمَلُونَ بَصِيرࣱ¦11:113:1:وَلَا تَرۡكَنُوٓاْ إِلَى ٱلَّذِينَ ظَلَمُواْ\nT;0;11:113:0:فَتَمَسَّكُمُ ٱلنَّارُ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِنۡ أَوۡلِيَآءَ ثُمَّ\nT;0;11:113:2:لَا تُنصَرُونَ¦11:114:1:وَأَقِمِ ٱلصَّلَوٰةَ طَرَفَيِ ٱلنَّهَارِ وَزُلَفࣰا مِّنَ\nT;0;11:114:0:ٱلَّيۡلِۚ إِنَّ ٱلۡحَسَنَٰتِ يُذۡهِبۡنَ ٱلسَّيِّـَٔاتِۚ ذَٰلِكَ ذِكۡرَىٰ\nT;0;11:114:2:لِلذَّٰكِرِينَ¦11:115:3:وَٱصۡبِرۡ فَإِنَّ ٱللَّهَ لَا يُضِيعُ أَجۡرَ ٱلۡمُحۡسِنِينَ\nT;0;11:116:1:فَلَوۡلَا كَانَ مِنَ ٱلۡقُرُونِ مِن قَبۡلِكُمۡ أُوْلُواْ بَقِيَّةࣲ يَنۡهَوۡنَ\nT;0;11:116:0:عَنِ ٱلۡفَسَادِ فِي ٱلۡأَرۡضِ إِلَّا قَلِيلࣰا مِّمَّنۡ أَنجَيۡنَا مِنۡهُمۡۗ وَٱتَّبَعَ\nT;0;11:116:2:ٱلَّذِينَ ظَلَمُواْ مَآ أُتۡرِفُواْ فِيهِ وَكَانُواْ مُجۡرِمِينَ¦11:117:1:وَمَا\nT;0;11:117:2:كَانَ رَبُّكَ لِيُهۡلِكَ ٱلۡقُرَىٰ بِظُلۡمࣲ وَأَهۡلُهَا مُصۡلِحُونَ',
  '12;24;1;\nT;0;11:118:3:وَلَوۡ شَآءَ رَبُّكَ لَجَعَلَ ٱلنَّاسَ أُمَّةࣰ وَٰحِدَةࣰۖ وَلَا يَزَالُونَ مُخۡتَلِفِينَ\nT;0;11:119:1:إِلَّا مَن رَّحِمَ رَبُّكَۚ وَلِذَٰلِكَ خَلَقَهُمۡۗ وَتَمَّتۡ كَلِمَةُ رَبِّكَ\nT;0;11:119:2:لَأَمۡلَأَنَّ جَهَنَّمَ مِنَ ٱلۡجِنَّةِ وَٱلنَّاسِ أَجۡمَعِينَ¦11:120:1:وَكُلࣰّا نَّقُصُّ\nT;0;11:120:0:عَلَيۡكَ مِنۡ أَنۢبَآءِ ٱلرُّسُلِ مَا نُثَبِّتُ بِهِۦ فُؤَادَكَۚ وَجَآءَكَ فِي هَٰذِهِ\nT;0;11:120:2:ٱلۡحَقُّ وَمَوۡعِظَةࣱ وَذِكۡرَىٰ لِلۡمُؤۡمِنِينَ¦11:121:1:وَقُل لِّلَّذِينَ لَا يُؤۡمِنُونَ\nT;0;11:121:2:ٱعۡمَلُواْ عَلَىٰ مَكَانَتِكُمۡ إِنَّا عَٰمِلُونَ¦11:122:3:وَٱنتَظِرُوٓاْ إِنَّا مُنتَظِرُونَ\nT;0;11:123:1:وَلِلَّهِ غَيۡبُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَإِلَيۡهِ يُرۡجَعُ ٱلۡأَمۡرُ كُلُّهُۥ\nT;2;11:123:2:فَٱعۡبُدۡهُ وَتَوَكَّلۡ عَلَيۡهِۚ وَمَا رَبُّكَ بِغَٰفِلٍ عَمَّا تَعۡمَلُونَ\nH;12\nB;12\nT;0;12:1:3:الٓرۚ تِلۡكَ ءَايَٰتُ ٱلۡكِتَٰبِ ٱلۡمُبِينِ¦12:2:1:إِنَّآ أَنزَلۡنَٰهُ قُرۡءَٰنًا\nT;0;12:2:2:عَرَبِيࣰّا لَّعَلَّكُمۡ تَعۡقِلُونَ¦12:3:1:نَحۡنُ نَقُصُّ عَلَيۡكَ أَحۡسَنَ\nT;0;12:3:0:ٱلۡقَصَصِ بِمَآ أَوۡحَيۡنَآ إِلَيۡكَ هَٰذَا ٱلۡقُرۡءَانَ وَإِن كُنتَ مِن قَبۡلِهِۦ\nT;0;12:3:2:لَمِنَ ٱلۡغَٰفِلِينَ¦12:4:1:إِذۡ قَالَ يُوسُفُ لِأَبِيهِ يَٰٓأَبَتِ إِنِّي رَأَيۡتُ\nT;0;12:4:2:أَحَدَ عَشَرَ كَوۡكَبࣰا وَٱلشَّمۡسَ وَٱلۡقَمَرَ رَأَيۡتُهُمۡ لِي سَٰجِدِينَ',
  '12;24;1;95\nT;0;12:5:1:قَالَ يَٰبُنَيَّ لَا تَقۡصُصۡ رُءۡيَاكَ عَلَىٰٓ إِخۡوَتِكَ فَيَكِيدُواْ لَكَ كَيۡدًاۖ\nT;0;12:5:2:إِنَّ ٱلشَّيۡطَٰنَ لِلۡإِنسَٰنِ عَدُوࣱّ مُّبِينࣱ¦12:6:1:وَكَذَٰلِكَ يَجۡتَبِيكَ\nT;0;12:6:0:رَبُّكَ وَيُعَلِّمُكَ مِن تَأۡوِيلِ ٱلۡأَحَادِيثِ وَيُتِمُّ نِعۡمَتَهُۥ عَلَيۡكَ\nT;0;12:6:0:وَعَلَىٰٓ ءَالِ يَعۡقُوبَ كَمَآ أَتَمَّهَا عَلَىٰٓ أَبَوَيۡكَ مِن قَبۡلُ إِبۡرَٰهِيمَ\nT;0;12:6:2:وَإِسۡحَٰقَۚ إِنَّ رَبَّكَ عَلِيمٌ حَكِيمࣱ¦12:7:1:۞ لَّقَدۡ كَانَ فِي يُوسُفَ\nT;0;12:7:2:وَإِخۡوَتِهِۦٓ ءَايَٰتࣱ لِّلسَّآئِلِينَ¦12:8:1:إِذۡ قَالُواْ لَيُوسُفُ وَأَخُوهُ أَحَبُّ\nT;0;12:8:2:إِلَىٰٓ أَبِينَا مِنَّا وَنَحۡنُ عُصۡبَةٌ إِنَّ أَبَانَا لَفِي ضَلَٰلࣲ مُّبِينٍ\nT;0;12:9:1:ٱقۡتُلُواْ يُوسُفَ أَوِ ٱطۡرَحُوهُ أَرۡضࣰا يَخۡلُ لَكُمۡ وَجۡهُ أَبِيكُمۡ\nT;0;12:9:2:وَتَكُونُواْ مِنۢ بَعۡدِهِۦ قَوۡمࣰا صَٰلِحِينَ¦12:10:1:قَالَ قَآئِلࣱ مِّنۡهُمۡ\nT;0;12:10:0:لَا تَقۡتُلُواْ يُوسُفَ وَأَلۡقُوهُ فِي غَيَٰبَتِ ٱلۡجُبِّ يَلۡتَقِطۡهُ بَعۡضُ\nT;0;12:10:2:ٱلسَّيَّارَةِ إِن كُنتُمۡ فَٰعِلِينَ¦12:11:1:قَالُواْ يَٰٓأَبَانَا مَا لَكَ لَا تَأۡمَ۬نَّا عَلَىٰ\nT;0;12:11:2:يُوسُفَ وَإِنَّا لَهُۥ لَنَٰصِحُونَ¦12:12:1:أَرۡسِلۡهُ مَعَنَا غَدࣰا يَرۡتَعۡ وَيَلۡعَبۡ\nT;0;12:12:2:وَإِنَّا لَهُۥ لَحَٰفِظُونَ¦12:13:1:قَالَ إِنِّي لَيَحۡزُنُنِيٓ أَن تَذۡهَبُواْ بِهِۦ وَأَخَافُ\nT;0;12:13:2:أَن يَأۡكُلَهُ ٱلذِّئۡبُ وَأَنتُمۡ عَنۡهُ غَٰفِلُونَ¦12:14:1:قَالُواْ لَئِنۡ\nT;0;12:14:2:أَكَلَهُ ٱلذِّئۡبُ وَنَحۡنُ عُصۡبَةٌ إِنَّآ إِذࣰا لَّخَٰسِرُونَ',
  '12;24;2;\nT;0;12:15:1:فَلَمَّا ذَهَبُواْ بِهِۦ وَأَجۡمَعُوٓاْ أَن يَجۡعَلُوهُ فِي غَيَٰبَتِ ٱلۡجُبِّۚ وَأَوۡحَيۡنَآ\nT;0;12:15:2:إِلَيۡهِ لَتُنَبِّئَنَّهُم بِأَمۡرِهِمۡ هَٰذَا وَهُمۡ لَا يَشۡعُرُونَ¦12:16:1:وَجَآءُوٓ\nT;0;12:16:2:أَبَاهُمۡ عِشَآءࣰ يَبۡكُونَ¦12:17:1:قَالُواْ يَٰٓأَبَانَآ إِنَّا ذَهَبۡنَا نَسۡتَبِقُ\nT;0;12:17:0:وَتَرَكۡنَا يُوسُفَ عِندَ مَتَٰعِنَا فَأَكَلَهُ ٱلذِّئۡبُۖ وَمَآ أَنتَ\nT;0;12:17:2:بِمُؤۡمِنࣲ لَّنَا وَلَوۡ كُنَّا صَٰدِقِينَ¦12:18:1:وَجَآءُو عَلَىٰ قَمِيصِهِۦ\nT;0;12:18:0:بِدَمࣲ كَذِبࣲۚ قَالَ بَلۡ سَوَّلَتۡ لَكُمۡ أَنفُسُكُمۡ أَمۡرࣰاۖ فَصَبۡرࣱ جَمِيلࣱۖ\nT;0;12:18:2:وَٱللَّهُ ٱلۡمُسۡتَعَانُ عَلَىٰ مَا تَصِفُونَ¦12:19:1:وَجَآءَتۡ سَيَّارَةࣱ\nT;0;12:19:0:فَأَرۡسَلُواْ وَارِدَهُمۡ فَأَدۡلَىٰ دَلۡوَهُۥۖ قَالَ يَٰبُشۡرَىٰ هَٰذَا غُلَٰمࣱۚ وَأَسَرُّوهُ\nT;0;12:19:2:بِضَٰعَةࣰۚ وَٱللَّهُ عَلِيمُۢ بِمَا يَعۡمَلُونَ¦12:20:1:وَشَرَوۡهُ بِثَمَنِۭ بَخۡسࣲ\nT;0;12:20:2:دَرَٰهِمَ مَعۡدُودَةࣲ وَكَانُواْ فِيهِ مِنَ ٱلزَّٰهِدِينَ¦12:21:1:وَقَالَ\nT;0;12:21:0:ٱلَّذِي ٱشۡتَرَىٰهُ مِن مِّصۡرَ لِٱمۡرَأَتِهِۦٓ أَكۡرِمِي مَثۡوَىٰهُ عَسَىٰٓ\nT;0;12:21:0:أَن يَنفَعَنَآ أَوۡ نَتَّخِذَهُۥ وَلَدࣰاۚ وَكَذَٰلِكَ مَكَّنَّا لِيُوسُفَ فِي\nT;0;12:21:0:ٱلۡأَرۡضِ وَلِنُعَلِّمَهُۥ مِن تَأۡوِيلِ ٱلۡأَحَادِيثِۚ وَٱللَّهُ غَالِبٌ عَلَىٰٓ\nT;0;12:21:2:أَمۡرِهِۦ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَعۡلَمُونَ¦12:22:1:وَلَمَّا بَلَغَ أَشُدَّهُۥٓ\nT;0;12:22:2:ءَاتَيۡنَٰهُ حُكۡمࣰا وَعِلۡمࣰاۚ وَكَذَٰلِكَ نَجۡزِي ٱلۡمُحۡسِنِينَ',
  '12;24;2;96\nT;0;12:23:1:وَرَٰوَدَتۡهُ ٱلَّتِي هُوَ فِي بَيۡتِهَا عَن نَّفۡسِهِۦ وَغَلَّقَتِ ٱلۡأَبۡوَٰبَ\nT;0;12:23:0:وَقَالَتۡ هَيۡتَ لَكَۚ قَالَ مَعَاذَ ٱللَّهِۖ إِنَّهُۥ رَبِّيٓ أَحۡسَنَ مَثۡوَايَۖ\nT;0;12:23:2:إِنَّهُۥ لَا يُفۡلِحُ ٱلظَّٰلِمُونَ¦12:24:1:وَلَقَدۡ هَمَّتۡ بِهِۦۖ وَهَمَّ بِهَا\nT;0;12:24:0:لَوۡلَآ أَن رَّءَا بُرۡهَٰنَ رَبِّهِۦۚ كَذَٰلِكَ لِنَصۡرِفَ عَنۡهُ ٱلسُّوٓءَ\nT;0;12:24:2:وَٱلۡفَحۡشَآءَۚ إِنَّهُۥ مِنۡ عِبَادِنَا ٱلۡمُخۡلَصِينَ¦12:25:1:وَٱسۡتَبَقَا\nT;0;12:25:0:ٱلۡبَابَ وَقَدَّتۡ قَمِيصَهُۥ مِن دُبُرࣲ وَأَلۡفَيَا سَيِّدَهَا لَدَا ٱلۡبَابِۚ\nT;0;12:25:0:قَالَتۡ مَا جَزَآءُ مَنۡ أَرَادَ بِأَهۡلِكَ سُوٓءًا إِلَّآ أَن يُسۡجَنَ أَوۡ عَذَابٌ\nT;0;12:25:2:أَلِيمࣱ¦12:26:1:قَالَ هِيَ رَٰوَدَتۡنِي عَن نَّفۡسِيۚ وَشَهِدَ شَاهِدࣱ مِّنۡ\nT;0;12:26:0:أَهۡلِهَآ إِن كَانَ قَمِيصُهُۥ قُدَّ مِن قُبُلࣲ فَصَدَقَتۡ وَهُوَ مِنَ\nT;0;12:26:2:ٱلۡكَٰذِبِينَ¦12:27:1:وَإِن كَانَ قَمِيصُهُۥ قُدَّ مِن دُبُرࣲ فَكَذَبَتۡ وَهُوَ\nT;0;12:27:2:مِنَ ٱلصَّٰدِقِينَ¦12:28:1:فَلَمَّا رَءَا قَمِيصَهُۥ قُدَّ مِن دُبُرࣲ قَالَ إِنَّهُۥ\nT;0;12:28:2:مِن كَيۡدِكُنَّۖ إِنَّ كَيۡدَكُنَّ عَظِيمࣱ¦12:29:1:يُوسُفُ أَعۡرِضۡ عَنۡ\nT;0;12:29:2:هَٰذَاۚ وَٱسۡتَغۡفِرِي لِذَنۢبِكِۖ إِنَّكِ كُنتِ مِنَ ٱلۡخَاطِـِٔينَ\nT;0;12:30:1:۞ وَقَالَ نِسۡوَةࣱ فِي ٱلۡمَدِينَةِ ٱمۡرَأَتُ ٱلۡعَزِيزِ تُرَٰوِدُ فَتَىٰهَا\nT;0;12:30:2:عَن نَّفۡسِهِۦۖ قَدۡ شَغَفَهَا حُبًّاۖ إِنَّا لَنَرَىٰهَا فِي ضَلَٰلࣲ مُّبِينࣲ',
  '12;24;3;\nT;0;12:31:1:فَلَمَّا سَمِعَتۡ بِمَكۡرِهِنَّ أَرۡسَلَتۡ إِلَيۡهِنَّ وَأَعۡتَدَتۡ لَهُنَّ مُتَّكَـࣰٔا\nT;0;12:31:0:وَءَاتَتۡ كُلَّ وَٰحِدَةࣲ مِّنۡهُنَّ سِكِّينࣰا وَقَالَتِ ٱخۡرُجۡ عَلَيۡهِنَّۖ فَلَمَّا رَأَيۡنَهُۥٓ\nT;0;12:31:0:أَكۡبَرۡنَهُۥ وَقَطَّعۡنَ أَيۡدِيَهُنَّ وَقُلۡنَ حَٰشَ لِلَّهِ مَا هَٰذَا بَشَرًا إِنۡ هَٰذَآ\nT;0;12:31:2:إِلَّا مَلَكࣱ كَرِيمࣱ¦12:32:1:قَالَتۡ فَذَٰلِكُنَّ ٱلَّذِي لُمۡتُنَّنِي فِيهِۖ وَلَقَدۡ رَٰوَدتُّهُۥ\nT;0;12:32:0:عَن نَّفۡسِهِۦ فَٱسۡتَعۡصَمَۖ وَلَئِن لَّمۡ يَفۡعَلۡ مَآ ءَامُرُهُۥ لَيُسۡجَنَنَّ\nT;0;12:32:2:وَلَيَكُونࣰا مِّنَ ٱلصَّٰغِرِينَ¦12:33:1:قَالَ رَبِّ ٱلسِّجۡنُ أَحَبُّ إِلَيَّ مِمَّا يَدۡعُونَنِيٓ\nT;0;12:33:2:إِلَيۡهِۖ وَإِلَّا تَصۡرِفۡ عَنِّي كَيۡدَهُنَّ أَصۡبُ إِلَيۡهِنَّ وَأَكُن مِّنَ ٱلۡجَٰهِلِينَ\nT;0;12:34:1:فَٱسۡتَجَابَ لَهُۥ رَبُّهُۥ فَصَرَفَ عَنۡهُ كَيۡدَهُنَّۚ إِنَّهُۥ هُوَ ٱلسَّمِيعُ\nT;0;12:34:2:ٱلۡعَلِيمُ¦12:35:1:ثُمَّ بَدَا لَهُم مِّنۢ بَعۡدِ مَا رَأَوُاْ ٱلۡأٓيَٰتِ لَيَسۡجُنُنَّهُۥ\nT;0;12:35:2:حَتَّىٰ حِينࣲ¦12:36:1:وَدَخَلَ مَعَهُ ٱلسِّجۡنَ فَتَيَانِۖ قَالَ أَحَدُهُمَآ إِنِّيٓ\nT;0;12:36:0:أَرَىٰنِيٓ أَعۡصِرُ خَمۡرࣰاۖ وَقَالَ ٱلۡأٓخَرُ إِنِّيٓ أَرَىٰنِيٓ أَحۡمِلُ فَوۡقَ رَأۡسِي\nT;0;12:36:0:خُبۡزࣰا تَأۡكُلُ ٱلطَّيۡرُ مِنۡهُۖ نَبِّئۡنَا بِتَأۡوِيلِهِۦٓۖ إِنَّا نَرَىٰكَ مِنَ\nT;0;12:36:2:ٱلۡمُحۡسِنِينَ¦12:37:1:قَالَ لَا يَأۡتِيكُمَا طَعَامࣱ تُرۡزَقَانِهِۦٓ إِلَّا نَبَّأۡتُكُمَا\nT;0;12:37:0:بِتَأۡوِيلِهِۦ قَبۡلَ أَن يَأۡتِيَكُمَاۚ ذَٰلِكُمَا مِمَّا عَلَّمَنِي رَبِّيٓۚ إِنِّي تَرَكۡتُ\nT;0;12:37:2:مِلَّةَ قَوۡمࣲ لَّا يُؤۡمِنُونَ بِٱللَّهِ وَهُم بِٱلۡأٓخِرَةِ هُمۡ كَٰفِرُونَ',
  '12;24;3;\nT;0;12:38:1:وَٱتَّبَعۡتُ مِلَّةَ ءَابَآءِيٓ إِبۡرَٰهِيمَ وَإِسۡحَٰقَ وَيَعۡقُوبَۚ مَا كَانَ\nT;0;12:38:0:لَنَآ أَن نُّشۡرِكَ بِٱللَّهِ مِن شَيۡءࣲۚ ذَٰلِكَ مِن فَضۡلِ ٱللَّهِ عَلَيۡنَا وَعَلَى\nT;0;12:38:2:ٱلنَّاسِ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَشۡكُرُونَ¦12:39:1:يَٰصَٰحِبَيِ\nT;0;12:39:2:ٱلسِّجۡنِ ءَأَرۡبَابࣱ مُّتَفَرِّقُونَ خَيۡرٌ أَمِ ٱللَّهُ ٱلۡوَٰحِدُ ٱلۡقَهَّارُ\nT;0;12:40:1:مَا تَعۡبُدُونَ مِن دُونِهِۦٓ إِلَّآ أَسۡمَآءࣰ سَمَّيۡتُمُوهَآ أَنتُمۡ\nT;0;12:40:0:وَءَابَآؤُكُم مَّآ أَنزَلَ ٱللَّهُ بِهَا مِن سُلۡطَٰنٍۚ إِنِ ٱلۡحُكۡمُ إِلَّا لِلَّهِ\nT;0;12:40:0:أَمَرَ أَلَّا تَعۡبُدُوٓاْ إِلَّآ إِيَّاهُۚ ذَٰلِكَ ٱلدِّينُ ٱلۡقَيِّمُ وَلَٰكِنَّ أَكۡثَرَ\nT;0;12:40:2:ٱلنَّاسِ لَا يَعۡلَمُونَ¦12:41:1:يَٰصَٰحِبَيِ ٱلسِّجۡنِ أَمَّآ أَحَدُكُمَا\nT;0;12:41:0:فَيَسۡقِي رَبَّهُۥ خَمۡرࣰاۖ وَأَمَّا ٱلۡأٓخَرُ فَيُصۡلَبُ فَتَأۡكُلُ ٱلطَّيۡرُ\nT;0;12:41:2:مِن رَّأۡسِهِۦۚ قُضِيَ ٱلۡأَمۡرُ ٱلَّذِي فِيهِ تَسۡتَفۡتِيَانِ¦12:42:1:وَقَالَ\nT;0;12:42:0:لِلَّذِي ظَنَّ أَنَّهُۥ نَاجࣲ مِّنۡهُمَا ٱذۡكُرۡنِي عِندَ رَبِّكَ فَأَنسَىٰهُ\nT;0;12:42:2:ٱلشَّيۡطَٰنُ ذِكۡرَ رَبِّهِۦ فَلَبِثَ فِي ٱلسِّجۡنِ بِضۡعَ سِنِينَ\nT;0;12:43:1:وَقَالَ ٱلۡمَلِكُ إِنِّيٓ أَرَىٰ سَبۡعَ بَقَرَٰتࣲ سِمَانࣲ يَأۡكُلُهُنَّ\nT;0;12:43:0:سَبۡعٌ عِجَافࣱ وَسَبۡعَ سُنۢبُلَٰتٍ خُضۡرࣲ وَأُخَرَ يَابِسَٰتࣲۖ يَٰٓأَيُّهَا\nT;0;12:43:2:ٱلۡمَلَأُ أَفۡتُونِي فِي رُءۡيَٰيَ إِن كُنتُمۡ لِلرُّءۡيَا تَعۡبُرُونَ',
  '12;24;3;\nT;0;12:44:3:قَالُوٓاْ أَضۡغَٰثُ أَحۡلَٰمࣲۖ وَمَا نَحۡنُ بِتَأۡوِيلِ ٱلۡأَحۡلَٰمِ بِعَٰلِمِينَ\nT;0;12:45:1:وَقَالَ ٱلَّذِي نَجَا مِنۡهُمَا وَٱدَّكَرَ بَعۡدَ أُمَّةٍ أَنَا۠ أُنَبِّئُكُم بِتَأۡوِيلِهِۦ\nT;0;12:45:2:فَأَرۡسِلُونِ¦12:46:1:يُوسُفُ أَيُّهَا ٱلصِّدِّيقُ أَفۡتِنَا فِي سَبۡعِ بَقَرَٰتࣲ\nT;0;12:46:0:سِمَانࣲ يَأۡكُلُهُنَّ سَبۡعٌ عِجَافࣱ وَسَبۡعِ سُنۢبُلَٰتٍ خُضۡرࣲ\nT;0;12:46:2:وَأُخَرَ يَابِسَٰتࣲ لَّعَلِّيٓ أَرۡجِعُ إِلَى ٱلنَّاسِ لَعَلَّهُمۡ يَعۡلَمُونَ¦12:47:1:قَالَ\nT;0;12:47:0:تَزۡرَعُونَ سَبۡعَ سِنِينَ دَأَبࣰا فَمَا حَصَدتُّمۡ فَذَرُوهُ فِي سُنۢبُلِهِۦٓ إِلَّا\nT;0;12:47:2:قَلِيلࣰا مِّمَّا تَأۡكُلُونَ¦12:48:1:ثُمَّ يَأۡتِي مِنۢ بَعۡدِ ذَٰلِكَ سَبۡعࣱ شِدَادࣱ يَأۡكُلۡنَ\nT;0;12:48:2:مَا قَدَّمۡتُمۡ لَهُنَّ إِلَّا قَلِيلࣰا مِّمَّا تُحۡصِنُونَ¦12:49:1:ثُمَّ يَأۡتِي مِنۢ بَعۡدِ ذَٰلِكَ\nT;0;12:49:2:عَامࣱ فِيهِ يُغَاثُ ٱلنَّاسُ وَفِيهِ يَعۡصِرُونَ¦12:50:1:وَقَالَ ٱلۡمَلِكُ ٱئۡتُونِي\nT;0;12:50:0:بِهِۦۖ فَلَمَّا جَآءَهُ ٱلرَّسُولُ قَالَ ٱرۡجِعۡ إِلَىٰ رَبِّكَ فَسۡـَٔلۡهُ مَا بَالُ\nT;0;12:50:2:ٱلنِّسۡوَةِ ٱلَّٰتِي قَطَّعۡنَ أَيۡدِيَهُنَّۚ إِنَّ رَبِّي بِكَيۡدِهِنَّ عَلِيمࣱ\nT;0;12:51:1:قَالَ مَا خَطۡبُكُنَّ إِذۡ رَٰوَدتُّنَّ يُوسُفَ عَن نَّفۡسِهِۦۚ قُلۡنَ حَٰشَ\nT;0;12:51:0:لِلَّهِ مَا عَلِمۡنَا عَلَيۡهِ مِن سُوٓءࣲۚ قَالَتِ ٱمۡرَأَتُ ٱلۡعَزِيزِ ٱلۡـَٰٔنَ حَصۡحَصَ\nT;0;12:51:2:ٱلۡحَقُّ أَنَا۠ رَٰوَدتُّهُۥ عَن نَّفۡسِهِۦ وَإِنَّهُۥ لَمِنَ ٱلصَّٰدِقِينَ¦12:52:1:ذَٰلِكَ\nT;0;12:52:2:لِيَعۡلَمَ أَنِّي لَمۡ أَخُنۡهُ بِٱلۡغَيۡبِ وَأَنَّ ٱللَّهَ لَا يَهۡدِي كَيۡدَ ٱلۡخَآئِنِينَ',
  '13;25;0;97\nT;0;12:53:1:۞ وَمَآ أُبَرِّئُ نَفۡسِيٓۚ إِنَّ ٱلنَّفۡسَ لَأَمَّارَةُۢ بِٱلسُّوٓءِ إِلَّا مَا رَحِمَ رَبِّيٓۚ\nT;0;12:53:2:إِنَّ رَبِّي غَفُورࣱ رَّحِيمࣱ¦12:54:1:وَقَالَ ٱلۡمَلِكُ ٱئۡتُونِي بِهِۦٓ أَسۡتَخۡلِصۡهُ\nT;0;12:54:2:لِنَفۡسِيۖ فَلَمَّا كَلَّمَهُۥ قَالَ إِنَّكَ ٱلۡيَوۡمَ لَدَيۡنَا مَكِينٌ أَمِينࣱ\nT;0;12:55:3:قَالَ ٱجۡعَلۡنِي عَلَىٰ خَزَآئِنِ ٱلۡأَرۡضِۖ إِنِّي حَفِيظٌ عَلِيمࣱ¦12:56:1:وَكَذَٰلِكَ\nT;0;12:56:0:مَكَّنَّا لِيُوسُفَ فِي ٱلۡأَرۡضِ يَتَبَوَّأُ مِنۡهَا حَيۡثُ يَشَآءُۚ نُصِيبُ\nT;0;12:56:2:بِرَحۡمَتِنَا مَن نَّشَآءُۖ وَلَا نُضِيعُ أَجۡرَ ٱلۡمُحۡسِنِينَ¦12:57:1:وَلَأَجۡرُ\nT;0;12:57:2:ٱلۡأٓخِرَةِ خَيۡرࣱ لِّلَّذِينَ ءَامَنُواْ وَكَانُواْ يَتَّقُونَ¦12:58:1:وَجَآءَ\nT;0;12:58:2:إِخۡوَةُ يُوسُفَ فَدَخَلُواْ عَلَيۡهِ فَعَرَفَهُمۡ وَهُمۡ لَهُۥ مُنكِرُونَ\nT;0;12:59:1:وَلَمَّا جَهَّزَهُم بِجَهَازِهِمۡ قَالَ ٱئۡتُونِي بِأَخࣲ لَّكُم مِّنۡ أَبِيكُمۡۚ أَلَا\nT;0;12:59:2:تَرَوۡنَ أَنِّيٓ أُوفِي ٱلۡكَيۡلَ وَأَنَا۠ خَيۡرُ ٱلۡمُنزِلِينَ¦12:60:1:فَإِن لَّمۡ تَأۡتُونِي\nT;0;12:60:2:بِهِۦ فَلَا كَيۡلَ لَكُمۡ عِندِي وَلَا تَقۡرَبُونِ¦12:61:1:قَالُواْ سَنُرَٰوِدُ عَنۡهُ أَبَاهُ\nT;0;12:61:2:وَإِنَّا لَفَٰعِلُونَ¦12:62:1:وَقَالَ لِفِتۡيَٰنِهِ ٱجۡعَلُواْ بِضَٰعَتَهُمۡ فِي رِحَالِهِمۡ\nT;0;12:62:2:لَعَلَّهُمۡ يَعۡرِفُونَهَآ إِذَا ٱنقَلَبُوٓاْ إِلَىٰٓ أَهۡلِهِمۡ لَعَلَّهُمۡ يَرۡجِعُونَ\nT;0;12:63:1:فَلَمَّا رَجَعُوٓاْ إِلَىٰٓ أَبِيهِمۡ قَالُواْ يَٰٓأَبَانَا مُنِعَ مِنَّا ٱلۡكَيۡلُ\nT;0;12:63:2:فَأَرۡسِلۡ مَعَنَآ أَخَانَا نَكۡتَلۡ وَإِنَّا لَهُۥ لَحَٰفِظُونَ',
  '13;25;0;\nT;0;12:64:1:قَالَ هَلۡ ءَامَنُكُمۡ عَلَيۡهِ إِلَّا كَمَآ أَمِنتُكُمۡ عَلَىٰٓ أَخِيهِ مِن\nT;0;12:64:2:قَبۡلُ فَٱللَّهُ خَيۡرٌ حَٰفِظࣰاۖ وَهُوَ أَرۡحَمُ ٱلرَّٰحِمِينَ¦12:65:1:وَلَمَّا فَتَحُواْ\nT;0;12:65:0:مَتَٰعَهُمۡ وَجَدُواْ بِضَٰعَتَهُمۡ رُدَّتۡ إِلَيۡهِمۡۖ قَالُواْ يَٰٓأَبَانَا\nT;0;12:65:0:مَا نَبۡغِيۖ هَٰذِهِۦ بِضَٰعَتُنَا رُدَّتۡ إِلَيۡنَاۖ وَنَمِيرُ أَهۡلَنَا وَنَحۡفَظُ\nT;0;12:65:2:أَخَانَا وَنَزۡدَادُ كَيۡلَ بَعِيرࣲۖ ذَٰلِكَ كَيۡلࣱ يَسِيرࣱ¦12:66:1:قَالَ\nT;0;12:66:0:لَنۡ أُرۡسِلَهُۥ مَعَكُمۡ حَتَّىٰ تُؤۡتُونِ مَوۡثِقࣰا مِّنَ ٱللَّهِ لَتَأۡتُنَّنِي\nT;0;12:66:0:بِهِۦٓ إِلَّآ أَن يُحَاطَ بِكُمۡۖ فَلَمَّآ ءَاتَوۡهُ مَوۡثِقَهُمۡ قَالَ ٱللَّهُ عَلَىٰ مَا\nT;0;12:66:2:نَقُولُ وَكِيلࣱ¦12:67:1:وَقَالَ يَٰبَنِيَّ لَا تَدۡخُلُواْ مِنۢ بَابࣲ وَٰحِدࣲ\nT;0;12:67:0:وَٱدۡخُلُواْ مِنۡ أَبۡوَٰبࣲ مُّتَفَرِّقَةࣲۖ وَمَآ أُغۡنِي عَنكُم مِّنَ ٱللَّهِ مِن\nT;0;12:67:0:شَيۡءٍۖ إِنِ ٱلۡحُكۡمُ إِلَّا لِلَّهِۖ عَلَيۡهِ تَوَكَّلۡتُۖ وَعَلَيۡهِ فَلۡيَتَوَكَّلِ\nT;0;12:67:2:ٱلۡمُتَوَكِّلُونَ¦12:68:1:وَلَمَّا دَخَلُواْ مِنۡ حَيۡثُ أَمَرَهُمۡ أَبُوهُم مَّا كَانَ\nT;0;12:68:0:يُغۡنِي عَنۡهُم مِّنَ ٱللَّهِ مِن شَيۡءٍ إِلَّا حَاجَةࣰ فِي نَفۡسِ يَعۡقُوبَ\nT;0;12:68:0:قَضَىٰهَاۚ وَإِنَّهُۥ لَذُو عِلۡمࣲ لِّمَا عَلَّمۡنَٰهُ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ\nT;0;12:68:2:لَا يَعۡلَمُونَ¦12:69:1:وَلَمَّا دَخَلُواْ عَلَىٰ يُوسُفَ ءَاوَىٰٓ إِلَيۡهِ أَخَاهُۖ\nT;0;12:69:2:قَالَ إِنِّيٓ أَنَا۠ أَخُوكَ فَلَا تَبۡتَئِسۡ بِمَا كَانُواْ يَعۡمَلُونَ',
  '13;25;0;98\nT;0;12:70:1:فَلَمَّا جَهَّزَهُم بِجَهَازِهِمۡ جَعَلَ ٱلسِّقَايَةَ فِي رَحۡلِ أَخِيهِ\nT;0;12:70:2:ثُمَّ أَذَّنَ مُؤَذِّنٌ أَيَّتُهَا ٱلۡعِيرُ إِنَّكُمۡ لَسَٰرِقُونَ¦12:71:1:قَالُواْ\nT;0;12:71:2:وَأَقۡبَلُواْ عَلَيۡهِم مَّاذَا تَفۡقِدُونَ¦12:72:1:قَالُواْ نَفۡقِدُ صُوَاعَ ٱلۡمَلِكِ\nT;0;12:72:2:وَلِمَن جَآءَ بِهِۦ حِمۡلُ بَعِيرࣲ وَأَنَا۠ بِهِۦ زَعِيمࣱ¦12:73:1:قَالُواْ تَٱللَّهِ\nT;0;12:73:2:لَقَدۡ عَلِمۡتُم مَّا جِئۡنَا لِنُفۡسِدَ فِي ٱلۡأَرۡضِ وَمَا كُنَّا سَٰرِقِينَ\nT;0;12:74:3:قَالُواْ فَمَا جَزَٰٓؤُهُۥٓ إِن كُنتُمۡ كَٰذِبِينَ¦12:75:1:قَالُواْ جَزَٰٓؤُهُۥ\nT;0;12:75:2:مَن وُجِدَ فِي رَحۡلِهِۦ فَهُوَ جَزَٰٓؤُهُۥۚ كَذَٰلِكَ نَجۡزِي ٱلظَّٰلِمِينَ\nT;0;12:76:1:فَبَدَأَ بِأَوۡعِيَتِهِمۡ قَبۡلَ وِعَآءِ أَخِيهِ ثُمَّ ٱسۡتَخۡرَجَهَا مِن\nT;0;12:76:0:وِعَآءِ أَخِيهِۚ كَذَٰلِكَ كِدۡنَا لِيُوسُفَۖ مَا كَانَ لِيَأۡخُذَ أَخَاهُ\nT;0;12:76:0:فِي دِينِ ٱلۡمَلِكِ إِلَّآ أَن يَشَآءَ ٱللَّهُۚ نَرۡفَعُ دَرَجَٰتࣲ مَّن نَّشَآءُۗ\nT;0;12:76:2:وَفَوۡقَ كُلِّ ذِي عِلۡمٍ عَلِيمࣱ¦12:77:1:۞ قَالُوٓاْ إِن يَسۡرِقۡ\nT;0;12:77:0:فَقَدۡ سَرَقَ أَخࣱ لَّهُۥ مِن قَبۡلُۚ فَأَسَرَّهَا يُوسُفُ فِي نَفۡسِهِۦ\nT;0;12:77:0:وَلَمۡ يُبۡدِهَا لَهُمۡۚ قَالَ أَنتُمۡ شَرࣱّ مَّكَانࣰاۖ وَٱللَّهُ أَعۡلَمُ بِمَا\nT;0;12:77:2:تَصِفُونَ¦12:78:1:قَالُواْ يَٰٓأَيُّهَا ٱلۡعَزِيزُ إِنَّ لَهُۥٓ أَبࣰا شَيۡخࣰا كَبِيرࣰا\nT;0;12:78:2:فَخُذۡ أَحَدَنَا مَكَانَهُۥٓۖ إِنَّا نَرَىٰكَ مِنَ ٱلۡمُحۡسِنِينَ',
  '13;25;1;\nT;0;12:79:1:قَالَ مَعَاذَ ٱللَّهِ أَن نَّأۡخُذَ إِلَّا مَن وَجَدۡنَا مَتَٰعَنَا عِندَهُۥٓ إِنَّآ\nT;0;12:79:2:إِذࣰا لَّظَٰلِمُونَ¦12:80:1:فَلَمَّا ٱسۡتَيۡـَٔسُواْ مِنۡهُ خَلَصُواْ نَجِيࣰّاۖ\nT;0;12:80:0:قَالَ كَبِيرُهُمۡ أَلَمۡ تَعۡلَمُوٓاْ أَنَّ أَبَاكُمۡ قَدۡ أَخَذَ عَلَيۡكُم\nT;0;12:80:0:مَّوۡثِقࣰا مِّنَ ٱللَّهِ وَمِن قَبۡلُ مَا فَرَّطتُمۡ فِي يُوسُفَۖ فَلَنۡ أَبۡرَحَ\nT;0;12:80:2:ٱلۡأَرۡضَ حَتَّىٰ يَأۡذَنَ لِيٓ أَبِيٓ أَوۡ يَحۡكُمَ ٱللَّهُ لِيۖ وَهُوَ خَيۡرُ ٱلۡحَٰكِمِينَ\nT;0;12:81:1:ٱرۡجِعُوٓاْ إِلَىٰٓ أَبِيكُمۡ فَقُولُواْ يَٰٓأَبَانَآ إِنَّ ٱبۡنَكَ سَرَقَ\nT;0;12:81:2:وَمَا شَهِدۡنَآ إِلَّا بِمَا عَلِمۡنَا وَمَا كُنَّا لِلۡغَيۡبِ حَٰفِظِينَ\nT;0;12:82:1:وَسۡـَٔلِ ٱلۡقَرۡيَةَ ٱلَّتِي كُنَّا فِيهَا وَٱلۡعِيرَ ٱلَّتِيٓ أَقۡبَلۡنَا فِيهَاۖ\nT;0;12:82:2:وَإِنَّا لَصَٰدِقُونَ¦12:83:1:قَالَ بَلۡ سَوَّلَتۡ لَكُمۡ أَنفُسُكُمۡ أَمۡرࣰاۖ\nT;0;12:83:0:فَصَبۡرࣱ جَمِيلٌۖ عَسَى ٱللَّهُ أَن يَأۡتِيَنِي بِهِمۡ جَمِيعًاۚ إِنَّهُۥ هُوَ\nT;0;12:83:2:ٱلۡعَلِيمُ ٱلۡحَكِيمُ¦12:84:1:وَتَوَلَّىٰ عَنۡهُمۡ وَقَالَ يَٰٓأَسَفَىٰ عَلَىٰ\nT;0;12:84:2:يُوسُفَ وَٱبۡيَضَّتۡ عَيۡنَاهُ مِنَ ٱلۡحُزۡنِ فَهُوَ كَظِيمࣱ\nT;0;12:85:1:قَالُواْ تَٱللَّهِ تَفۡتَؤُاْ تَذۡكُرُ يُوسُفَ حَتَّىٰ تَكُونَ حَرَضًا\nT;0;12:85:2:أَوۡ تَكُونَ مِنَ ٱلۡهَٰلِكِينَ¦12:86:1:قَالَ إِنَّمَآ أَشۡكُواْ بَثِّي\nT;0;12:86:2:وَحُزۡنِيٓ إِلَى ٱللَّهِ وَأَعۡلَمُ مِنَ ٱللَّهِ مَا لَا تَعۡلَمُونَ',
  '13;25;1;\nT;0;12:87:1:يَٰبَنِيَّ ٱذۡهَبُواْ فَتَحَسَّسُواْ مِن يُوسُفَ وَأَخِيهِ وَلَا تَاْيۡـَٔسُواْ\nT;0;12:87:0:مِن رَّوۡحِ ٱللَّهِۖ إِنَّهُۥ لَا يَاْيۡـَٔسُ مِن رَّوۡحِ ٱللَّهِ إِلَّا ٱلۡقَوۡمُ\nT;0;12:87:2:ٱلۡكَٰفِرُونَ¦12:88:1:فَلَمَّا دَخَلُواْ عَلَيۡهِ قَالُواْ يَٰٓأَيُّهَا ٱلۡعَزِيزُ\nT;0;12:88:0:مَسَّنَا وَأَهۡلَنَا ٱلضُّرُّ وَجِئۡنَا بِبِضَٰعَةࣲ مُّزۡجَىٰةࣲ فَأَوۡفِ لَنَا\nT;0;12:88:2:ٱلۡكَيۡلَ وَتَصَدَّقۡ عَلَيۡنَآۖ إِنَّ ٱللَّهَ يَجۡزِي ٱلۡمُتَصَدِّقِينَ\nT;0;12:89:1:قَالَ هَلۡ عَلِمۡتُم مَّا فَعَلۡتُم بِيُوسُفَ وَأَخِيهِ إِذۡ أَنتُمۡ\nT;0;12:89:2:جَٰهِلُونَ¦12:90:1:قَالُوٓاْ أَءِنَّكَ لَأَنتَ يُوسُفُۖ قَالَ أَنَا۠ يُوسُفُ\nT;0;12:90:0:وَهَٰذَآ أَخِيۖ قَدۡ مَنَّ ٱللَّهُ عَلَيۡنَآۖ إِنَّهُۥ مَن يَتَّقِ وَيَصۡبِرۡ فَإِنَّ\nT;0;12:90:2:ٱللَّهَ لَا يُضِيعُ أَجۡرَ ٱلۡمُحۡسِنِينَ¦12:91:1:قَالُواْ تَٱللَّهِ لَقَدۡ\nT;0;12:91:2:ءَاثَرَكَ ٱللَّهُ عَلَيۡنَا وَإِن كُنَّا لَخَٰطِـِٔينَ¦12:92:1:قَالَ لَا تَثۡرِيبَ\nT;0;12:92:2:عَلَيۡكُمُ ٱلۡيَوۡمَۖ يَغۡفِرُ ٱللَّهُ لَكُمۡۖ وَهُوَ أَرۡحَمُ ٱلرَّٰحِمِينَ\nT;0;12:93:1:ٱذۡهَبُواْ بِقَمِيصِي هَٰذَا فَأَلۡقُوهُ عَلَىٰ وَجۡهِ أَبِي يَأۡتِ\nT;0;12:93:2:بَصِيرࣰا وَأۡتُونِي بِأَهۡلِكُمۡ أَجۡمَعِينَ¦12:94:1:وَلَمَّا فَصَلَتِ\nT;0;12:94:0:ٱلۡعِيرُ قَالَ أَبُوهُمۡ إِنِّي لَأَجِدُ رِيحَ يُوسُفَۖ لَوۡلَآ أَن\nT;0;12:94:2:تُفَنِّدُونِ¦12:95:3:قَالُواْ تَٱللَّهِ إِنَّكَ لَفِي ضَلَٰلِكَ ٱلۡقَدِيمِ',
  '13;25;1;99\nT;0;12:96:1:فَلَمَّآ أَن جَآءَ ٱلۡبَشِيرُ أَلۡقَىٰهُ عَلَىٰ وَجۡهِهِۦ فَٱرۡتَدَّ بَصِيرࣰاۖ قَالَ\nT;0;12:96:2:أَلَمۡ أَقُل لَّكُمۡ إِنِّيٓ أَعۡلَمُ مِنَ ٱللَّهِ مَا لَا تَعۡلَمُونَ¦12:97:1:قَالُواْ\nT;0;12:97:2:يَٰٓأَبَانَا ٱسۡتَغۡفِرۡ لَنَا ذُنُوبَنَآ إِنَّا كُنَّا خَٰطِـِٔينَ¦12:98:1:قَالَ سَوۡفَ\nT;0;12:98:2:أَسۡتَغۡفِرُ لَكُمۡ رَبِّيٓۖ إِنَّهُۥ هُوَ ٱلۡغَفُورُ ٱلرَّحِيمُ¦12:99:1:فَلَمَّا\nT;0;12:99:0:دَخَلُواْ عَلَىٰ يُوسُفَ ءَاوَىٰٓ إِلَيۡهِ أَبَوَيۡهِ وَقَالَ ٱدۡخُلُواْ مِصۡرَ\nT;0;12:99:2:إِن شَآءَ ٱللَّهُ ءَامِنِينَ¦12:100:1:وَرَفَعَ أَبَوَيۡهِ عَلَى ٱلۡعَرۡشِ وَخَرُّواْ\nT;0;12:100:0:لَهُۥ سُجَّدࣰاۖ وَقَالَ يَٰٓأَبَتِ هَٰذَا تَأۡوِيلُ رُءۡيَٰيَ مِن قَبۡلُ قَدۡ جَعَلَهَا\nT;0;12:100:0:رَبِّي حَقࣰّاۖ وَقَدۡ أَحۡسَنَ بِيٓ إِذۡ أَخۡرَجَنِي مِنَ ٱلسِّجۡنِ وَجَآءَ بِكُم\nT;0;12:100:0:مِّنَ ٱلۡبَدۡوِ مِنۢ بَعۡدِ أَن نَّزَغَ ٱلشَّيۡطَٰنُ بَيۡنِي وَبَيۡنَ إِخۡوَتِيٓۚ إِنَّ\nT;0;12:100:2:رَبِّي لَطِيفࣱ لِّمَا يَشَآءُۚ إِنَّهُۥ هُوَ ٱلۡعَلِيمُ ٱلۡحَكِيمُ¦12:101:1:۞ رَبِّ\nT;0;12:101:0:قَدۡ ءَاتَيۡتَنِي مِنَ ٱلۡمُلۡكِ وَعَلَّمۡتَنِي مِن تَأۡوِيلِ ٱلۡأَحَادِيثِۚ\nT;0;12:101:0:فَاطِرَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ أَنتَ وَلِيِّۦ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِۖ\nT;0;12:101:2:تَوَفَّنِي مُسۡلِمࣰا وَأَلۡحِقۡنِي بِٱلصَّٰلِحِينَ¦12:102:1:ذَٰلِكَ مِنۡ أَنۢبَآءِ\nT;0;12:102:0:ٱلۡغَيۡبِ نُوحِيهِ إِلَيۡكَۖ وَمَا كُنتَ لَدَيۡهِمۡ إِذۡ أَجۡمَعُوٓاْ أَمۡرَهُمۡ\nT;0;12:102:2:وَهُمۡ يَمۡكُرُونَ¦12:103:3:وَمَآ أَكۡثَرُ ٱلنَّاسِ وَلَوۡ حَرَصۡتَ بِمُؤۡمِنِينَ',
  '13;25;2;\nT;0;12:104:3:وَمَا تَسۡـَٔلُهُمۡ عَلَيۡهِ مِنۡ أَجۡرٍۚ إِنۡ هُوَ إِلَّا ذِكۡرࣱ لِّلۡعَٰلَمِينَ\nT;0;12:105:1:وَكَأَيِّن مِّنۡ ءَايَةࣲ فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ يَمُرُّونَ عَلَيۡهَا\nT;0;12:105:2:وَهُمۡ عَنۡهَا مُعۡرِضُونَ¦12:106:1:وَمَا يُؤۡمِنُ أَكۡثَرُهُم بِٱللَّهِ إِلَّا\nT;0;12:106:2:وَهُم مُّشۡرِكُونَ¦12:107:1:أَفَأَمِنُوٓاْ أَن تَأۡتِيَهُمۡ غَٰشِيَةࣱ مِّنۡ عَذَابِ\nT;0;12:107:2:ٱللَّهِ أَوۡ تَأۡتِيَهُمُ ٱلسَّاعَةُ بَغۡتَةࣰ وَهُمۡ لَا يَشۡعُرُونَ¦12:108:1:قُلۡ\nT;0;12:108:0:هَٰذِهِۦ سَبِيلِيٓ أَدۡعُوٓاْ إِلَى ٱللَّهِۚ عَلَىٰ بَصِيرَةٍ أَنَا۠ وَمَنِ ٱتَّبَعَنِيۖ\nT;0;12:108:2:وَسُبۡحَٰنَ ٱللَّهِ وَمَآ أَنَا۠ مِنَ ٱلۡمُشۡرِكِينَ¦12:109:1:وَمَآ أَرۡسَلۡنَا مِن\nT;0;12:109:0:قَبۡلِكَ إِلَّا رِجَالࣰا نُّوحِيٓ إِلَيۡهِم مِّنۡ أَهۡلِ ٱلۡقُرَىٰٓۗ أَفَلَمۡ يَسِيرُواْ\nT;0;12:109:0:فِي ٱلۡأَرۡضِ فَيَنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ مِن\nT;0;12:109:2:قَبۡلِهِمۡۗ وَلَدَارُ ٱلۡأٓخِرَةِ خَيۡرࣱ لِّلَّذِينَ ٱتَّقَوۡاْۚ أَفَلَا تَعۡقِلُونَ\nT;0;12:110:1:حَتَّىٰٓ إِذَا ٱسۡتَيۡـَٔسَ ٱلرُّسُلُ وَظَنُّوٓاْ أَنَّهُمۡ قَدۡ كُذِبُواْ\nT;0;12:110:0:جَآءَهُمۡ نَصۡرُنَا فَنُجِّيَ مَن نَّشَآءُۖ وَلَا يُرَدُّ بَأۡسُنَا عَنِ ٱلۡقَوۡمِ\nT;0;12:110:2:ٱلۡمُجۡرِمِينَ¦12:111:1:لَقَدۡ كَانَ فِي قَصَصِهِمۡ عِبۡرَةࣱ لِّأُوْلِي ٱلۡأَلۡبَٰبِۗ\nT;0;12:111:0:مَا كَانَ حَدِيثࣰا يُفۡتَرَىٰ وَلَٰكِن تَصۡدِيقَ ٱلَّذِي بَيۡنَ يَدَيۡهِ\nT;2;12:111:2:وَتَفۡصِيلَ كُلِّ شَيۡءࣲ وَهُدࣰى وَرَحۡمَةࣰ لِّقَوۡمࣲ يُؤۡمِنُونَ',
  '13;25;2;100\nH;13\nB;13\nT;0;13:1:1:الٓمٓرۚ تِلۡكَ ءَايَٰتُ ٱلۡكِتَٰبِۗ وَٱلَّذِيٓ أُنزِلَ إِلَيۡكَ مِن رَّبِّكَ ٱلۡحَقُّ\nT;0;13:1:2:وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يُؤۡمِنُونَ¦13:2:1:ٱللَّهُ ٱلَّذِي رَفَعَ ٱلسَّمَٰوَٰتِ\nT;0;13:2:0:بِغَيۡرِ عَمَدࣲ تَرَوۡنَهَاۖ ثُمَّ ٱسۡتَوَىٰ عَلَى ٱلۡعَرۡشِۖ وَسَخَّرَ ٱلشَّمۡسَ وَٱلۡقَمَرَۖ\nT;0;13:2:0:كُلࣱّ يَجۡرِي لِأَجَلࣲ مُّسَمࣰّىۚ يُدَبِّرُ ٱلۡأَمۡرَ يُفَصِّلُ ٱلۡأٓيَٰتِ لَعَلَّكُم\nT;0;13:2:2:بِلِقَآءِ رَبِّكُمۡ تُوقِنُونَ¦13:3:1:وَهُوَ ٱلَّذِي مَدَّ ٱلۡأَرۡضَ وَجَعَلَ فِيهَا رَوَٰسِيَ\nT;0;13:3:0:وَأَنۡهَٰرࣰاۖ وَمِن كُلِّ ٱلثَّمَرَٰتِ جَعَلَ فِيهَا زَوۡجَيۡنِ ٱثۡنَيۡنِۖ يُغۡشِي ٱلَّيۡلَ\nT;0;13:3:2:ٱلنَّهَارَۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتࣲ لِّقَوۡمࣲ يَتَفَكَّرُونَ¦13:4:1:وَفِي ٱلۡأَرۡضِ\nT;0;13:4:0:قِطَعࣱ مُّتَجَٰوِرَٰتࣱ وَجَنَّٰتࣱ مِّنۡ أَعۡنَٰبࣲ وَزَرۡعࣱ وَنَخِيلࣱ صِنۡوَانࣱ\nT;0;13:4:0:وَغَيۡرُ صِنۡوَانࣲ يُسۡقَىٰ بِمَآءࣲ وَٰحِدࣲ وَنُفَضِّلُ بَعۡضَهَا عَلَىٰ بَعۡضࣲ\nT;0;13:4:2:فِي ٱلۡأُكُلِۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتࣲ لِّقَوۡمࣲ يَعۡقِلُونَ¦13:5:1:۞ وَإِن تَعۡجَبۡ\nT;0;13:5:0:فَعَجَبࣱ قَوۡلُهُمۡ أَءِذَا كُنَّا تُرَٰبًا أَءِنَّا لَفِي خَلۡقࣲ جَدِيدٍۗ\nT;0;13:5:0:أُوْلَٰٓئِكَ ٱلَّذِينَ كَفَرُواْ بِرَبِّهِمۡۖ وَأُوْلَٰٓئِكَ ٱلۡأَغۡلَٰلُ فِيٓ\nT;0;13:5:2:أَعۡنَاقِهِمۡۖ وَأُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ فِيهَا خَٰلِدُونَ',
  '13;25;3;\nT;0;13:6:1:وَيَسۡتَعۡجِلُونَكَ بِٱلسَّيِّئَةِ قَبۡلَ ٱلۡحَسَنَةِ وَقَدۡ خَلَتۡ مِن\nT;0;13:6:0:قَبۡلِهِمُ ٱلۡمَثُلَٰتُۗ وَإِنَّ رَبَّكَ لَذُو مَغۡفِرَةࣲ لِّلنَّاسِ عَلَىٰ ظُلۡمِهِمۡۖ\nT;0;13:6:2:وَإِنَّ رَبَّكَ لَشَدِيدُ ٱلۡعِقَابِ¦13:7:1:وَيَقُولُ ٱلَّذِينَ كَفَرُواْ لَوۡلَآ\nT;0;13:7:0:أُنزِلَ عَلَيۡهِ ءَايَةࣱ مِّن رَّبِّهِۦٓۗ إِنَّمَآ أَنتَ مُنذِرࣱۖ وَلِكُلِّ قَوۡمٍ\nT;0;13:7:2:هَادٍ¦13:8:1:ٱللَّهُ يَعۡلَمُ مَا تَحۡمِلُ كُلُّ أُنثَىٰ وَمَا تَغِيضُ ٱلۡأَرۡحَامُ\nT;0;13:8:2:وَمَا تَزۡدَادُۚ وَكُلُّ شَيۡءٍ عِندَهُۥ بِمِقۡدَارٍ¦13:9:1:عَٰلِمُ ٱلۡغَيۡبِ\nT;0;13:9:2:وَٱلشَّهَٰدَةِ ٱلۡكَبِيرُ ٱلۡمُتَعَالِ¦13:10:1:سَوَآءࣱ مِّنكُم مَّنۡ\nT;0;13:10:0:أَسَرَّ ٱلۡقَوۡلَ وَمَن جَهَرَ بِهِۦ وَمَنۡ هُوَ مُسۡتَخۡفِۭ بِٱلَّيۡلِ وَسَارِبُۢ\nT;0;13:10:2:بِٱلنَّهَارِ¦13:11:1:لَهُۥ مُعَقِّبَٰتࣱ مِّنۢ بَيۡنِ يَدَيۡهِ وَمِنۡ خَلۡفِهِۦ\nT;0;13:11:0:يَحۡفَظُونَهُۥ مِنۡ أَمۡرِ ٱللَّهِۗ إِنَّ ٱللَّهَ لَا يُغَيِّرُ مَا بِقَوۡمٍ حَتَّىٰ يُغَيِّرُواْ\nT;0;13:11:0:مَا بِأَنفُسِهِمۡۗ وَإِذَآ أَرَادَ ٱللَّهُ بِقَوۡمࣲ سُوٓءࣰا فَلَا مَرَدَّ لَهُۥۚ وَمَا\nT;0;13:11:2:لَهُم مِّن دُونِهِۦ مِن وَالٍ¦13:12:1:هُوَ ٱلَّذِي يُرِيكُمُ ٱلۡبَرۡقَ خَوۡفࣰا\nT;0;13:12:2:وَطَمَعࣰا وَيُنشِئُ ٱلسَّحَابَ ٱلثِّقَالَ¦13:13:1:وَيُسَبِّحُ ٱلرَّعۡدُ بِحَمۡدِهِۦ\nT;0;13:13:0:وَٱلۡمَلَٰٓئِكَةُ مِنۡ خِيفَتِهِۦ وَيُرۡسِلُ ٱلصَّوَٰعِقَ فَيُصِيبُ بِهَا\nT;0;13:13:2:مَن يَشَآءُ وَهُمۡ يُجَٰدِلُونَ فِي ٱللَّهِ وَهُوَ شَدِيدُ ٱلۡمِحَالِ',
  '13;25;3;\nT;0;13:14:1:لَهُۥ دَعۡوَةُ ٱلۡحَقِّۚ وَٱلَّذِينَ يَدۡعُونَ مِن دُونِهِۦ لَا يَسۡتَجِيبُونَ لَهُم بِشَيۡءٍ إِلَّا\nT;0;13:14:0:كَبَٰسِطِ كَفَّيۡهِ إِلَى ٱلۡمَآءِ لِيَبۡلُغَ فَاهُ وَمَا هُوَ بِبَٰلِغِهِۦۚ وَمَا دُعَآءُ ٱلۡكَٰفِرِينَ\nT;0;13:14:2:إِلَّا فِي ضَلَٰلࣲ¦13:15:1:وَلِلَّهِۤ يَسۡجُدُۤ مَن فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ طَوۡعࣰا\nT;0;13:15:2:وَكَرۡهࣰا وَظِلَٰلُهُم بِٱلۡغُدُوِّ وَٱلۡأٓصَالِ۩¦13:16:1:قُلۡ مَن رَّبُّ ٱلسَّمَٰوَٰتِ\nT;0;13:16:0:وَٱلۡأَرۡضِ قُلِ ٱللَّهُۚ قُلۡ أَفَٱتَّخَذۡتُم مِّن دُونِهِۦٓ أَوۡلِيَآءَ لَا يَمۡلِكُونَ\nT;0;13:16:0:لِأَنفُسِهِمۡ نَفۡعࣰا وَلَا ضَرࣰّاۚ قُلۡ هَلۡ يَسۡتَوِي ٱلۡأَعۡمَىٰ وَٱلۡبَصِيرُ أَمۡ هَلۡ\nT;0;13:16:0:تَسۡتَوِي ٱلظُّلُمَٰتُ وَٱلنُّورُۗ أَمۡ جَعَلُواْ لِلَّهِ شُرَكَآءَ خَلَقُواْ كَخَلۡقِهِۦ فَتَشَٰبَهَ\nT;0;13:16:2:ٱلۡخَلۡقُ عَلَيۡهِمۡۚ قُلِ ٱللَّهُ خَٰلِقُ كُلِّ شَيۡءࣲ وَهُوَ ٱلۡوَٰحِدُ ٱلۡقَهَّٰرُ¦13:17:1:أَنزَلَ\nT;0;13:17:0:مِنَ ٱلسَّمَآءِ مَآءࣰ فَسَالَتۡ أَوۡدِيَةُۢ بِقَدَرِهَا فَٱحۡتَمَلَ ٱلسَّيۡلُ زَبَدࣰا رَّابِيࣰاۖ\nT;0;13:17:0:وَمِمَّا يُوقِدُونَ عَلَيۡهِ فِي ٱلنَّارِ ٱبۡتِغَآءَ حِلۡيَةٍ أَوۡ مَتَٰعࣲ زَبَدࣱ مِّثۡلُهُۥۚ\nT;0;13:17:0:كَذَٰلِكَ يَضۡرِبُ ٱللَّهُ ٱلۡحَقَّ وَٱلۡبَٰطِلَۚ فَأَمَّا ٱلزَّبَدُ فَيَذۡهَبُ جُفَآءࣰۖ\nT;0;13:17:0:وَأَمَّا مَا يَنفَعُ ٱلنَّاسَ فَيَمۡكُثُ فِي ٱلۡأَرۡضِۚ كَذَٰلِكَ يَضۡرِبُ ٱللَّهُ\nT;0;13:17:2:ٱلۡأَمۡثَالَ¦13:18:1:لِلَّذِينَ ٱسۡتَجَابُواْ لِرَبِّهِمُ ٱلۡحُسۡنَىٰۚ وَٱلَّذِينَ لَمۡ يَسۡتَجِيبُواْ\nT;0;13:18:0:لَهُۥ لَوۡ أَنَّ لَهُم مَّا فِي ٱلۡأَرۡضِ جَمِيعࣰا وَمِثۡلَهُۥ مَعَهُۥ لَٱفۡتَدَوۡاْ بِهِۦٓۚ\nT;0;13:18:2:أُوْلَٰٓئِكَ لَهُمۡ سُوٓءُ ٱلۡحِسَابِ وَمَأۡوَىٰهُمۡ جَهَنَّمُۖ وَبِئۡسَ ٱلۡمِهَادُ',
  '13;26;0;101\nT;0;13:19:1:۞ أَفَمَن يَعۡلَمُ أَنَّمَآ أُنزِلَ إِلَيۡكَ مِن رَّبِّكَ ٱلۡحَقُّ كَمَنۡ هُوَ أَعۡمَىٰٓۚ إِنَّمَا يَتَذَكَّرُ\nT;0;13:19:2:أُوْلُواْ ٱلۡأَلۡبَٰبِ¦13:20:3:ٱلَّذِينَ يُوفُونَ بِعَهۡدِ ٱللَّهِ وَلَا يَنقُضُونَ ٱلۡمِيثَٰقَ\nT;0;13:21:1:وَٱلَّذِينَ يَصِلُونَ مَآ أَمَرَ ٱللَّهُ بِهِۦٓ أَن يُوصَلَ وَيَخۡشَوۡنَ رَبَّهُمۡ\nT;0;13:21:2:وَيَخَافُونَ سُوٓءَ ٱلۡحِسَابِ¦13:22:1:وَٱلَّذِينَ صَبَرُواْ ٱبۡتِغَآءَ وَجۡهِ رَبِّهِمۡ\nT;0;13:22:0:وَأَقَامُواْ ٱلصَّلَوٰةَ وَأَنفَقُواْ مِمَّا رَزَقۡنَٰهُمۡ سِرࣰّا وَعَلَانِيَةࣰ وَيَدۡرَءُونَ\nT;0;13:22:2:بِٱلۡحَسَنَةِ ٱلسَّيِّئَةَ أُوْلَٰٓئِكَ لَهُمۡ عُقۡبَى ٱلدَّارِ¦13:23:1:جَنَّٰتُ عَدۡنࣲ يَدۡخُلُونَهَا\nT;0;13:23:0:وَمَن صَلَحَ مِنۡ ءَابَآئِهِمۡ وَأَزۡوَٰجِهِمۡ وَذُرِّيَّٰتِهِمۡۖ وَٱلۡمَلَٰٓئِكَةُ يَدۡخُلُونَ\nT;0;13:23:2:عَلَيۡهِم مِّن كُلِّ بَابࣲ¦13:24:3:سَلَٰمٌ عَلَيۡكُم بِمَا صَبَرۡتُمۡۚ فَنِعۡمَ عُقۡبَى ٱلدَّارِ\nT;0;13:25:1:وَٱلَّذِينَ يَنقُضُونَ عَهۡدَ ٱللَّهِ مِنۢ بَعۡدِ مِيثَٰقِهِۦ وَيَقۡطَعُونَ\nT;0;13:25:0:مَآ أَمَرَ ٱللَّهُ بِهِۦٓ أَن يُوصَلَ وَيُفۡسِدُونَ فِي ٱلۡأَرۡضِ أُوْلَٰٓئِكَ لَهُمُ\nT;0;13:25:2:ٱللَّعۡنَةُ وَلَهُمۡ سُوٓءُ ٱلدَّارِ¦13:26:1:ٱللَّهُ يَبۡسُطُ ٱلرِّزۡقَ لِمَن يَشَآءُ\nT;0;13:26:0:وَيَقۡدِرُۚ وَفَرِحُواْ بِٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَمَا ٱلۡحَيَوٰةُ ٱلدُّنۡيَا فِي ٱلۡأٓخِرَةِ إِلَّا\nT;0;13:26:2:مَتَٰعࣱ¦13:27:1:وَيَقُولُ ٱلَّذِينَ كَفَرُواْ لَوۡلَآ أُنزِلَ عَلَيۡهِ ءَايَةࣱ مِّن رَّبِّهِۦۚ قُلۡ\nT;0;13:27:2:إِنَّ ٱللَّهَ يُضِلُّ مَن يَشَآءُ وَيَهۡدِيٓ إِلَيۡهِ مَنۡ أَنَابَ¦13:28:1:ٱلَّذِينَ ءَامَنُواْ\nT;0;13:28:2:وَتَطۡمَئِنُّ قُلُوبُهُم بِذِكۡرِ ٱللَّهِۗ أَلَا بِذِكۡرِ ٱللَّهِ تَطۡمَئِنُّ ٱلۡقُلُوبُ',
  '13;26;0;\nT;0;13:29:3:ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ طُوبَىٰ لَهُمۡ وَحُسۡنُ مَـَٔابࣲ\nT;0;13:30:1:كَذَٰلِكَ أَرۡسَلۡنَٰكَ فِيٓ أُمَّةࣲ قَدۡ خَلَتۡ مِن قَبۡلِهَآ أُمَمࣱ لِّتَتۡلُوَاْ\nT;0;13:30:0:عَلَيۡهِمُ ٱلَّذِيٓ أَوۡحَيۡنَآ إِلَيۡكَ وَهُمۡ يَكۡفُرُونَ بِٱلرَّحۡمَٰنِۚ قُلۡ هُوَ رَبِّي\nT;0;13:30:2:لَآ إِلَٰهَ إِلَّا هُوَ عَلَيۡهِ تَوَكَّلۡتُ وَإِلَيۡهِ مَتَابِ¦13:31:1:وَلَوۡ أَنَّ قُرۡءَانࣰا\nT;0;13:31:0:سُيِّرَتۡ بِهِ ٱلۡجِبَالُ أَوۡ قُطِّعَتۡ بِهِ ٱلۡأَرۡضُ أَوۡ كُلِّمَ بِهِ ٱلۡمَوۡتَىٰۗ\nT;0;13:31:0:بَل لِّلَّهِ ٱلۡأَمۡرُ جَمِيعًاۗ أَفَلَمۡ يَاْيۡـَٔسِ ٱلَّذِينَ ءَامَنُوٓاْ أَن لَّوۡ يَشَآءُ\nT;0;13:31:0:ٱللَّهُ لَهَدَى ٱلنَّاسَ جَمِيعࣰاۗ وَلَا يَزَالُ ٱلَّذِينَ كَفَرُواْ تُصِيبُهُم\nT;0;13:31:0:بِمَا صَنَعُواْ قَارِعَةٌ أَوۡ تَحُلُّ قَرِيبࣰا مِّن دَارِهِمۡ حَتَّىٰ يَأۡتِيَ وَعۡدُ\nT;0;13:31:2:ٱللَّهِۚ إِنَّ ٱللَّهَ لَا يُخۡلِفُ ٱلۡمِيعَادَ¦13:32:1:وَلَقَدِ ٱسۡتُهۡزِئَ بِرُسُلࣲ مِّن\nT;0;13:32:0:قَبۡلِكَ فَأَمۡلَيۡتُ لِلَّذِينَ كَفَرُواْ ثُمَّ أَخَذۡتُهُمۡۖ فَكَيۡفَ كَانَ\nT;0;13:32:2:عِقَابِ¦13:33:1:أَفَمَنۡ هُوَ قَآئِمٌ عَلَىٰ كُلِّ نَفۡسِۭ بِمَا كَسَبَتۡۗ وَجَعَلُواْ\nT;0;13:33:0:لِلَّهِ شُرَكَآءَ قُلۡ سَمُّوهُمۡۚ أَمۡ تُنَبِّـُٔونَهُۥ بِمَا لَا يَعۡلَمُ فِي ٱلۡأَرۡضِ أَم\nT;0;13:33:0:بِظَٰهِرࣲ مِّنَ ٱلۡقَوۡلِۗ بَلۡ زُيِّنَ لِلَّذِينَ كَفَرُواْ مَكۡرُهُمۡ وَصُدُّواْ عَنِ\nT;0;13:33:2:ٱلسَّبِيلِۗ وَمَن يُضۡلِلِ ٱللَّهُ فَمَا لَهُۥ مِنۡ هَادࣲ¦13:34:1:لَّهُمۡ عَذَابࣱ فِي ٱلۡحَيَوٰةِ\nT;0;13:34:2:ٱلدُّنۡيَاۖ وَلَعَذَابُ ٱلۡأٓخِرَةِ أَشَقُّۖ وَمَا لَهُم مِّنَ ٱللَّهِ مِن وَاقࣲ',
  '13;26;1;102\nT;0;13:35:1:۞ مَّثَلُ ٱلۡجَنَّةِ ٱلَّتِي وُعِدَ ٱلۡمُتَّقُونَۖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُۖ\nT;0;13:35:0:أُكُلُهَا دَآئِمࣱ وَظِلُّهَاۚ تِلۡكَ عُقۡبَى ٱلَّذِينَ ٱتَّقَواْۚ وَّعُقۡبَى\nT;0;13:35:2:ٱلۡكَٰفِرِينَ ٱلنَّارُ¦13:36:1:وَٱلَّذِينَ ءَاتَيۡنَٰهُمُ ٱلۡكِتَٰبَ يَفۡرَحُونَ\nT;0;13:36:0:بِمَآ أُنزِلَ إِلَيۡكَۖ وَمِنَ ٱلۡأَحۡزَابِ مَن يُنكِرُ بَعۡضَهُۥۚ قُلۡ إِنَّمَآ\nT;0;13:36:2:أُمِرۡتُ أَنۡ أَعۡبُدَ ٱللَّهَ وَلَآ أُشۡرِكَ بِهِۦٓۚ إِلَيۡهِ أَدۡعُواْ وَإِلَيۡهِ مَـَٔابِ\nT;0;13:37:1:وَكَذَٰلِكَ أَنزَلۡنَٰهُ حُكۡمًا عَرَبِيࣰّاۚ وَلَئِنِ ٱتَّبَعۡتَ أَهۡوَآءَهُم بَعۡدَ\nT;0;13:37:2:مَا جَآءَكَ مِنَ ٱلۡعِلۡمِ مَا لَكَ مِنَ ٱللَّهِ مِن وَلِيࣲّ وَلَا وَاقࣲ¦13:38:1:وَلَقَدۡ\nT;0;13:38:0:أَرۡسَلۡنَا رُسُلࣰا مِّن قَبۡلِكَ وَجَعَلۡنَا لَهُمۡ أَزۡوَٰجࣰا وَذُرِّيَّةࣰۚ وَمَا كَانَ\nT;0;13:38:2:لِرَسُولٍ أَن يَأۡتِيَ بِـَٔايَةٍ إِلَّا بِإِذۡنِ ٱللَّهِۗ لِكُلِّ أَجَلࣲ كِتَابࣱ\nT;0;13:39:3:يَمۡحُواْ ٱللَّهُ مَا يَشَآءُ وَيُثۡبِتُۖ وَعِندَهُۥٓ أُمُّ ٱلۡكِتَٰبِ¦13:40:1:وَإِن مَّا\nT;0;13:40:0:نُرِيَنَّكَ بَعۡضَ ٱلَّذِي نَعِدُهُمۡ أَوۡ نَتَوَفَّيَنَّكَ فَإِنَّمَا عَلَيۡكَ ٱلۡبَلَٰغُ\nT;0;13:40:2:وَعَلَيۡنَا ٱلۡحِسَابُ¦13:41:1:أَوَلَمۡ يَرَوۡاْ أَنَّا نَأۡتِي ٱلۡأَرۡضَ نَنقُصُهَا\nT;0;13:41:0:مِنۡ أَطۡرَافِهَاۚ وَٱللَّهُ يَحۡكُمُ لَا مُعَقِّبَ لِحُكۡمِهِۦۚ وَهُوَ سَرِيعُ\nT;0;13:41:2:ٱلۡحِسَابِ¦13:42:1:وَقَدۡ مَكَرَ ٱلَّذِينَ مِن قَبۡلِهِمۡ فَلِلَّهِ ٱلۡمَكۡرُ جَمِيعࣰاۖ\nT;0;13:42:2:يَعۡلَمُ مَا تَكۡسِبُ كُلُّ نَفۡسࣲۗ وَسَيَعۡلَمُ ٱلۡكُفَّٰرُ لِمَنۡ عُقۡبَى ٱلدَّارِ',
  '13;26;1;\nT;0;13:43:1:وَيَقُولُ ٱلَّذِينَ كَفَرُواْ لَسۡتَ مُرۡسَلࣰاۚ قُلۡ كَفَىٰ بِٱللَّهِ شَهِيدَۢا\nT;2;13:43:2:بَيۡنِي وَبَيۡنَكُمۡ وَمَنۡ عِندَهُۥ عِلۡمُ ٱلۡكِتَٰبِ\nH;14\nB;14\nT;0;14:1:1:الٓرۚ كِتَٰبٌ أَنزَلۡنَٰهُ إِلَيۡكَ لِتُخۡرِجَ ٱلنَّاسَ مِنَ ٱلظُّلُمَٰتِ\nT;0;14:1:2:إِلَى ٱلنُّورِ بِإِذۡنِ رَبِّهِمۡ إِلَىٰ صِرَٰطِ ٱلۡعَزِيزِ ٱلۡحَمِيدِ\nT;0;14:2:1:ٱللَّهِ ٱلَّذِي لَهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۗ وَوَيۡلࣱ\nT;0;14:2:2:لِّلۡكَٰفِرِينَ مِنۡ عَذَابࣲ شَدِيدٍ¦14:3:1:ٱلَّذِينَ يَسۡتَحِبُّونَ\nT;0;14:3:0:ٱلۡحَيَوٰةَ ٱلدُّنۡيَا عَلَى ٱلۡأٓخِرَةِ وَيَصُدُّونَ عَن سَبِيلِ\nT;0;14:3:2:ٱللَّهِ وَيَبۡغُونَهَا عِوَجًاۚ أُوْلَٰٓئِكَ فِي ضَلَٰلِۭ بَعِيدࣲ¦14:4:1:وَمَآ\nT;0;14:4:0:أَرۡسَلۡنَا مِن رَّسُولٍ إِلَّا بِلِسَانِ قَوۡمِهِۦ لِيُبَيِّنَ لَهُمۡۖ\nT;0;14:4:0:فَيُضِلُّ ٱللَّهُ مَن يَشَآءُ وَيَهۡدِي مَن يَشَآءُۚ وَهُوَ ٱلۡعَزِيزُ\nT;0;14:4:2:ٱلۡحَكِيمُ¦14:5:1:وَلَقَدۡ أَرۡسَلۡنَا مُوسَىٰ بِـَٔايَٰتِنَآ أَنۡ أَخۡرِجۡ\nT;0;14:5:0:قَوۡمَكَ مِنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِ وَذَكِّرۡهُم بِأَيَّىٰمِ\nT;0;14:5:2:ٱللَّهِۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتࣲ لِّكُلِّ صَبَّارࣲ شَكُورࣲ',
  '13;26;1;103\nT;0;14:6:1:وَإِذۡ قَالَ مُوسَىٰ لِقَوۡمِهِ ٱذۡكُرُواْ نِعۡمَةَ ٱللَّهِ عَلَيۡكُمۡ\nT;0;14:6:0:إِذۡ أَنجَىٰكُم مِّنۡ ءَالِ فِرۡعَوۡنَ يَسُومُونَكُمۡ سُوٓءَ ٱلۡعَذَابِ\nT;0;14:6:0:وَيُذَبِّحُونَ أَبۡنَآءَكُمۡ وَيَسۡتَحۡيُونَ نِسَآءَكُمۡۚ وَفِي\nT;0;14:6:2:ذَٰلِكُم بَلَآءࣱ مِّن رَّبِّكُمۡ عَظِيمࣱ¦14:7:1:وَإِذۡ تَأَذَّنَ رَبُّكُمۡ\nT;0;14:7:0:لَئِن شَكَرۡتُمۡ لَأَزِيدَنَّكُمۡۖ وَلَئِن كَفَرۡتُمۡ إِنَّ عَذَابِي\nT;0;14:7:2:لَشَدِيدࣱ¦14:8:1:وَقَالَ مُوسَىٰٓ إِن تَكۡفُرُوٓاْ أَنتُمۡ وَمَن فِي\nT;0;14:8:2:ٱلۡأَرۡضِ جَمِيعࣰا فَإِنَّ ٱللَّهَ لَغَنِيٌّ حَمِيدٌ¦14:9:1:أَلَمۡ يَأۡتِكُمۡ نَبَؤُاْ\nT;0;14:9:0:ٱلَّذِينَ مِن قَبۡلِكُمۡ قَوۡمِ نُوحࣲ وَعَادࣲ وَثَمُودَ وَٱلَّذِينَ\nT;0;14:9:0:مِنۢ بَعۡدِهِمۡ لَا يَعۡلَمُهُمۡ إِلَّا ٱللَّهُۚ جَآءَتۡهُمۡ رُسُلُهُم\nT;0;14:9:0:بِٱلۡبَيِّنَٰتِ فَرَدُّوٓاْ أَيۡدِيَهُمۡ فِيٓ أَفۡوَٰهِهِمۡ وَقَالُوٓاْ إِنَّا كَفَرۡنَا\nT;0;14:9:2:بِمَآ أُرۡسِلۡتُم بِهِۦ وَإِنَّا لَفِي شَكࣲّ مِّمَّا تَدۡعُونَنَآ إِلَيۡهِ مُرِيبࣲ\nT;0;14:10:1:۞ قَالَتۡ رُسُلُهُمۡ أَفِي ٱللَّهِ شَكࣱّ فَاطِرِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ\nT;0;14:10:0:يَدۡعُوكُمۡ لِيَغۡفِرَ لَكُم مِّن ذُنُوبِكُمۡ وَيُؤَخِّرَكُمۡ إِلَىٰٓ أَجَلࣲ\nT;0;14:10:0:مُّسَمࣰّىۚ قَالُوٓاْ إِنۡ أَنتُمۡ إِلَّا بَشَرࣱ مِّثۡلُنَا تُرِيدُونَ أَن تَصُدُّونَا\nT;0;14:10:2:عَمَّا كَانَ يَعۡبُدُ ءَابَآؤُنَا فَأۡتُونَا بِسُلۡطَٰنࣲ مُّبِينࣲ',
  '13;26;2;\nT;0;14:11:1:قَالَتۡ لَهُمۡ رُسُلُهُمۡ إِن نَّحۡنُ إِلَّا بَشَرࣱ مِّثۡلُكُمۡ وَلَٰكِنَّ ٱللَّهَ\nT;0;14:11:0:يَمُنُّ عَلَىٰ مَن يَشَآءُ مِنۡ عِبَادِهِۦۖ وَمَا كَانَ لَنَآ أَن نَّأۡتِيَكُم\nT;0;14:11:2:بِسُلۡطَٰنٍ إِلَّا بِإِذۡنِ ٱللَّهِۚ وَعَلَى ٱللَّهِ فَلۡيَتَوَكَّلِ ٱلۡمُؤۡمِنُونَ\nT;0;14:12:1:وَمَا لَنَآ أَلَّا نَتَوَكَّلَ عَلَى ٱللَّهِ وَقَدۡ هَدَىٰنَا سُبُلَنَاۚ وَلَنَصۡبِرَنَّ\nT;0;14:12:2:عَلَىٰ مَآ ءَاذَيۡتُمُونَاۚ وَعَلَى ٱللَّهِ فَلۡيَتَوَكَّلِ ٱلۡمُتَوَكِّلُونَ\nT;0;14:13:1:وَقَالَ ٱلَّذِينَ كَفَرُواْ لِرُسُلِهِمۡ لَنُخۡرِجَنَّكُم مِّنۡ أَرۡضِنَآ\nT;0;14:13:0:أَوۡ لَتَعُودُنَّ فِي مِلَّتِنَاۖ فَأَوۡحَىٰٓ إِلَيۡهِمۡ رَبُّهُمۡ لَنُهۡلِكَنَّ\nT;0;14:13:2:ٱلظَّٰلِمِينَ¦14:14:1:وَلَنُسۡكِنَنَّكُمُ ٱلۡأَرۡضَ مِنۢ بَعۡدِهِمۡۚ\nT;0;14:14:2:ذَٰلِكَ لِمَنۡ خَافَ مَقَامِي وَخَافَ وَعِيدِ¦14:15:1:وَٱسۡتَفۡتَحُواْ\nT;0;14:15:2:وَخَابَ كُلُّ جَبَّارٍ عَنِيدࣲ¦14:16:1:مِّن وَرَآئِهِۦ جَهَنَّمُ وَيُسۡقَىٰ\nT;0;14:16:2:مِن مَّآءࣲ صَدِيدࣲ¦14:17:1:يَتَجَرَّعُهُۥ وَلَا يَكَادُ يُسِيغُهُۥ وَيَأۡتِيهِ\nT;0;14:17:0:ٱلۡمَوۡتُ مِن كُلِّ مَكَانࣲ وَمَا هُوَ بِمَيِّتࣲۖ وَمِن وَرَآئِهِۦ\nT;0;14:17:2:عَذَابٌ غَلِيظࣱ¦14:18:1:مَّثَلُ ٱلَّذِينَ كَفَرُواْ بِرَبِّهِمۡۖ أَعۡمَٰلُهُمۡ\nT;0;14:18:0:كَرَمَادٍ ٱشۡتَدَّتۡ بِهِ ٱلرِّيحُ فِي يَوۡمٍ عَاصِفࣲۖ لَّا يَقۡدِرُونَ\nT;0;14:18:2:مِمَّا كَسَبُواْ عَلَىٰ شَيۡءࣲۚ ذَٰلِكَ هُوَ ٱلضَّلَٰلُ ٱلۡبَعِيدُ',
  '13;26;2;\nT;0;14:19:1:أَلَمۡ تَرَ أَنَّ ٱللَّهَ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ بِٱلۡحَقِّۚ إِن يَشَأۡ\nT;0;14:19:2:يُذۡهِبۡكُمۡ وَيَأۡتِ بِخَلۡقࣲ جَدِيدࣲ¦14:20:3:وَمَا ذَٰلِكَ عَلَى ٱللَّهِ بِعَزِيزࣲ\nT;0;14:21:1:وَبَرَزُواْ لِلَّهِ جَمِيعࣰا فَقَالَ ٱلضُّعَفَٰٓؤُاْ لِلَّذِينَ ٱسۡتَكۡبَرُوٓاْ\nT;0;14:21:0:إِنَّا كُنَّا لَكُمۡ تَبَعࣰا فَهَلۡ أَنتُم مُّغۡنُونَ عَنَّا مِنۡ عَذَابِ ٱللَّهِ\nT;0;14:21:0:مِن شَيۡءࣲۚ قَالُواْ لَوۡ هَدَىٰنَا ٱللَّهُ لَهَدَيۡنَٰكُمۡۖ سَوَآءٌ عَلَيۡنَآ\nT;0;14:21:2:أَجَزِعۡنَآ أَمۡ صَبَرۡنَا مَا لَنَا مِن مَّحِيصࣲ¦14:22:1:وَقَالَ ٱلشَّيۡطَٰنُ لَمَّا\nT;0;14:22:0:قُضِيَ ٱلۡأَمۡرُ إِنَّ ٱللَّهَ وَعَدَكُمۡ وَعۡدَ ٱلۡحَقِّ وَوَعَدتُّكُمۡ\nT;0;14:22:0:فَأَخۡلَفۡتُكُمۡۖ وَمَا كَانَ لِيَ عَلَيۡكُم مِّن سُلۡطَٰنٍ إِلَّآ\nT;0;14:22:0:أَن دَعَوۡتُكُمۡ فَٱسۡتَجَبۡتُمۡ لِيۖ فَلَا تَلُومُونِي وَلُومُوٓاْ أَنفُسَكُمۖ\nT;0;14:22:0:مَّآ أَنَا۠ بِمُصۡرِخِكُمۡ وَمَآ أَنتُم بِمُصۡرِخِيَّ إِنِّي كَفَرۡتُ\nT;0;14:22:0:بِمَآ أَشۡرَكۡتُمُونِ مِن قَبۡلُۗ إِنَّ ٱلظَّٰلِمِينَ لَهُمۡ عَذَابٌ\nT;0;14:22:2:أَلِيمࣱ¦14:23:1:وَأُدۡخِلَ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ جَنَّٰتࣲ\nT;0;14:23:0:تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَا بِإِذۡنِ رَبِّهِمۡۖ تَحِيَّتُهُمۡ\nT;0;14:23:2:فِيهَا سَلَٰمٌ¦14:24:1:أَلَمۡ تَرَ كَيۡفَ ضَرَبَ ٱللَّهُ مَثَلࣰا كَلِمَةࣰ طَيِّبَةࣰ\nT;0;14:24:2:كَشَجَرَةࣲ طَيِّبَةٍ أَصۡلُهَا ثَابِتࣱ وَفَرۡعُهَا فِي ٱلسَّمَآءِ',
  '13;26;2;104\nT;0;14:25:1:تُؤۡتِيٓ أُكُلَهَا كُلَّ حِينِۭ بِإِذۡنِ رَبِّهَاۗ وَيَضۡرِبُ ٱللَّهُ ٱلۡأَمۡثَالَ\nT;0;14:25:2:لِلنَّاسِ لَعَلَّهُمۡ يَتَذَكَّرُونَ¦14:26:1:وَمَثَلُ كَلِمَةٍ خَبِيثَةࣲ\nT;0;14:26:0:كَشَجَرَةٍ خَبِيثَةٍ ٱجۡتُثَّتۡ مِن فَوۡقِ ٱلۡأَرۡضِ مَا لَهَا مِن\nT;0;14:26:2:قَرَارࣲ¦14:27:1:يُثَبِّتُ ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ بِٱلۡقَوۡلِ ٱلثَّابِتِ فِي ٱلۡحَيَوٰةِ\nT;0;14:27:0:ٱلدُّنۡيَا وَفِي ٱلۡأٓخِرَةِۖ وَيُضِلُّ ٱللَّهُ ٱلظَّٰلِمِينَۚ وَيَفۡعَلُ ٱللَّهُ\nT;0;14:27:2:مَا يَشَآءُ¦14:28:1:۞ أَلَمۡ تَرَ إِلَى ٱلَّذِينَ بَدَّلُواْ نِعۡمَتَ ٱللَّهِ كُفۡرࣰا\nT;0;14:28:2:وَأَحَلُّواْ قَوۡمَهُمۡ دَارَ ٱلۡبَوَارِ¦14:29:1:جَهَنَّمَ يَصۡلَوۡنَهَاۖ وَبِئۡسَ\nT;0;14:29:2:ٱلۡقَرَارُ¦14:30:1:وَجَعَلُواْ لِلَّهِ أَندَادࣰا لِّيُضِلُّواْ عَن سَبِيلِهِۦۗ قُلۡ\nT;0;14:30:2:تَمَتَّعُواْ فَإِنَّ مَصِيرَكُمۡ إِلَى ٱلنَّارِ¦14:31:1:قُل لِّعِبَادِيَ ٱلَّذِينَ\nT;0;14:31:0:ءَامَنُواْ يُقِيمُواْ ٱلصَّلَوٰةَ وَيُنفِقُواْ مِمَّا رَزَقۡنَٰهُمۡ سِرࣰّا وَعَلَانِيَةࣰ\nT;0;14:31:2:مِّن قَبۡلِ أَن يَأۡتِيَ يَوۡمࣱ لَّا بَيۡعࣱ فِيهِ وَلَا خِلَٰلٌ¦14:32:1:ٱللَّهُ ٱلَّذِي\nT;0;14:32:0:خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ وَأَنزَلَ مِنَ ٱلسَّمَآءِ مَآءࣰ فَأَخۡرَجَ\nT;0;14:32:0:بِهِۦ مِنَ ٱلثَّمَرَٰتِ رِزۡقࣰا لَّكُمۡۖ وَسَخَّرَ لَكُمُ ٱلۡفُلۡكَ لِتَجۡرِيَ\nT;0;14:32:2:فِي ٱلۡبَحۡرِ بِأَمۡرِهِۦۖ وَسَخَّرَ لَكُمُ ٱلۡأَنۡهَٰرَ¦14:33:1:وَسَخَّرَ لَكُمُ\nT;0;14:33:2:ٱلشَّمۡسَ وَٱلۡقَمَرَ دَآئِبَيۡنِۖ وَسَخَّرَ لَكُمُ ٱلَّيۡلَ وَٱلنَّهَارَ',
  '13;26;3;\nT;0;14:34:1:وَءَاتَىٰكُم مِّن كُلِّ مَا سَأَلۡتُمُوهُۚ وَإِن تَعُدُّواْ نِعۡمَتَ ٱللَّهِ\nT;0;14:34:2:لَا تُحۡصُوهَآۗ إِنَّ ٱلۡإِنسَٰنَ لَظَلُومࣱ كَفَّارࣱ¦14:35:1:وَإِذۡ قَالَ إِبۡرَٰهِيمُ\nT;0;14:35:0:رَبِّ ٱجۡعَلۡ هَٰذَا ٱلۡبَلَدَ ءَامِنࣰا وَٱجۡنُبۡنِي وَبَنِيَّ أَن نَّعۡبُدَ\nT;0;14:35:2:ٱلۡأَصۡنَامَ¦14:36:1:رَبِّ إِنَّهُنَّ أَضۡلَلۡنَ كَثِيرࣰا مِّنَ ٱلنَّاسِۖ فَمَن\nT;0;14:36:2:تَبِعَنِي فَإِنَّهُۥ مِنِّيۖ وَمَنۡ عَصَانِي فَإِنَّكَ غَفُورࣱ رَّحِيمࣱ¦14:37:1:رَّبَّنَآ\nT;0;14:37:0:إِنِّيٓ أَسۡكَنتُ مِن ذُرِّيَّتِي بِوَادٍ غَيۡرِ ذِي زَرۡعٍ عِندَ بَيۡتِكَ\nT;0;14:37:0:ٱلۡمُحَرَّمِ رَبَّنَا لِيُقِيمُواْ ٱلصَّلَوٰةَ فَٱجۡعَلۡ أَفۡـِٔدَةࣰ مِّنَ ٱلنَّاسِ\nT;0;14:37:2:تَهۡوِيٓ إِلَيۡهِمۡ وَٱرۡزُقۡهُم مِّنَ ٱلثَّمَرَٰتِ لَعَلَّهُمۡ يَشۡكُرُونَ\nT;0;14:38:1:رَبَّنَآ إِنَّكَ تَعۡلَمُ مَا نُخۡفِي وَمَا نُعۡلِنُۗ وَمَا يَخۡفَىٰ عَلَى ٱللَّهِ\nT;0;14:38:2:مِن شَيۡءࣲ فِي ٱلۡأَرۡضِ وَلَا فِي ٱلسَّمَآءِ¦14:39:1:ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِي\nT;0;14:39:0:وَهَبَ لِي عَلَى ٱلۡكِبَرِ إِسۡمَٰعِيلَ وَإِسۡحَٰقَۚ إِنَّ رَبِّي لَسَمِيعُ\nT;0;14:39:2:ٱلدُّعَآءِ¦14:40:1:رَبِّ ٱجۡعَلۡنِي مُقِيمَ ٱلصَّلَوٰةِ وَمِن ذُرِّيَّتِيۚ رَبَّنَا\nT;0;14:40:2:وَتَقَبَّلۡ دُعَآءِ¦14:41:1:رَبَّنَا ٱغۡفِرۡ لِي وَلِوَٰلِدَيَّ وَلِلۡمُؤۡمِنِينَ\nT;0;14:41:2:يَوۡمَ يَقُومُ ٱلۡحِسَابُ¦14:42:1:وَلَا تَحۡسَبَنَّ ٱللَّهَ غَٰفِلًا عَمَّا يَعۡمَلُ\nT;0;14:42:2:ٱلظَّٰلِمُونَۚ إِنَّمَا يُؤَخِّرُهُمۡ لِيَوۡمࣲ تَشۡخَصُ فِيهِ ٱلۡأَبۡصَٰرُ',
  '13;26;3;\nT;0;14:43:1:مُهۡطِعِينَ مُقۡنِعِي رُءُوسِهِمۡ لَا يَرۡتَدُّ إِلَيۡهِمۡ طَرۡفُهُمۡۖ\nT;0;14:43:2:وَأَفۡـِٔدَتُهُمۡ هَوَآءࣱ¦14:44:1:وَأَنذِرِ ٱلنَّاسَ يَوۡمَ يَأۡتِيهِمُ ٱلۡعَذَابُ\nT;0;14:44:0:فَيَقُولُ ٱلَّذِينَ ظَلَمُواْ رَبَّنَآ أَخِّرۡنَآ إِلَىٰٓ أَجَلࣲ قَرِيبࣲ نُّجِبۡ\nT;0;14:44:0:دَعۡوَتَكَ وَنَتَّبِعِ ٱلرُّسُلَۗ أَوَلَمۡ تَكُونُوٓاْ أَقۡسَمۡتُم مِّن قَبۡلُ\nT;0;14:44:2:مَا لَكُم مِّن زَوَالࣲ¦14:45:1:وَسَكَنتُمۡ فِي مَسَٰكِنِ ٱلَّذِينَ ظَلَمُوٓاْ\nT;0;14:45:0:أَنفُسَهُمۡ وَتَبَيَّنَ لَكُمۡ كَيۡفَ فَعَلۡنَا بِهِمۡ وَضَرَبۡنَا لَكُمُ\nT;0;14:45:2:ٱلۡأَمۡثَالَ¦14:46:1:وَقَدۡ مَكَرُواْ مَكۡرَهُمۡ وَعِندَ ٱللَّهِ مَكۡرُهُمۡ\nT;0;14:46:2:وَإِن كَانَ مَكۡرُهُمۡ لِتَزُولَ مِنۡهُ ٱلۡجِبَالُ¦14:47:1:فَلَا\nT;0;14:47:0:تَحۡسَبَنَّ ٱللَّهَ مُخۡلِفَ وَعۡدِهِۦ رُسُلَهُۥٓۚ إِنَّ ٱللَّهَ عَزِيزࣱ\nT;0;14:47:2:ذُو ٱنتِقَامࣲ¦14:48:1:يَوۡمَ تُبَدَّلُ ٱلۡأَرۡضُ غَيۡرَ ٱلۡأَرۡضِ وَٱلسَّمَٰوَٰتُۖ\nT;0;14:48:2:وَبَرَزُواْ لِلَّهِ ٱلۡوَٰحِدِ ٱلۡقَهَّارِ¦14:49:1:وَتَرَى ٱلۡمُجۡرِمِينَ يَوۡمَئِذࣲ\nT;0;14:49:2:مُّقَرَّنِينَ فِي ٱلۡأَصۡفَادِ¦14:50:1:سَرَابِيلُهُم مِّن قَطِرَانࣲ وَتَغۡشَىٰ\nT;0;14:50:2:وُجُوهَهُمُ ٱلنَّارُ¦14:51:1:لِيَجۡزِيَ ٱللَّهُ كُلَّ نَفۡسࣲ مَّا كَسَبَتۡۚ\nT;0;14:51:2:إِنَّ ٱللَّهَ سَرِيعُ ٱلۡحِسَابِ¦14:52:1:هَٰذَا بَلَٰغࣱ لِّلنَّاسِ وَلِيُنذَرُواْ بِهِۦ\nT;2;14:52:2:وَلِيَعۡلَمُوٓاْ أَنَّمَا هُوَ إِلَٰهࣱ وَٰحِدࣱ وَلِيَذَّكَّرَ أُوْلُواْ ٱلۡأَلۡبَٰبِ',
  '14;27;0;105\nH;15\nB;15\nT;0;15:1:3:الٓرۚ تِلۡكَ ءَايَٰتُ ٱلۡكِتَٰبِ وَقُرۡءَانࣲ مُّبِينࣲ¦15:2:1:رُّبَمَا يَوَدُّ\nT;0;15:2:2:ٱلَّذِينَ كَفَرُواْ لَوۡ كَانُواْ مُسۡلِمِينَ¦15:3:1:ذَرۡهُمۡ يَأۡكُلُواْ\nT;0;15:3:2:وَيَتَمَتَّعُواْ وَيُلۡهِهِمُ ٱلۡأَمَلُۖ فَسَوۡفَ يَعۡلَمُونَ¦15:4:1:وَمَآ أَهۡلَكۡنَا\nT;0;15:4:2:مِن قَرۡيَةٍ إِلَّا وَلَهَا كِتَابࣱ مَّعۡلُومࣱ¦15:5:1:مَّا تَسۡبِقُ مِنۡ أُمَّةٍ\nT;0;15:5:2:أَجَلَهَا وَمَا يَسۡتَـٔۡخِرُونَ¦15:6:1:وَقَالُواْ يَٰٓأَيُّهَا ٱلَّذِي نُزِّلَ عَلَيۡهِ\nT;0;15:6:2:ٱلذِّكۡرُ إِنَّكَ لَمَجۡنُونࣱ¦15:7:1:لَّوۡمَا تَأۡتِينَا بِٱلۡمَلَٰٓئِكَةِ إِن كُنتَ\nT;0;15:7:2:مِنَ ٱلصَّٰدِقِينَ¦15:8:1:مَا نُنَزِّلُ ٱلۡمَلَٰٓئِكَةَ إِلَّا بِٱلۡحَقِّ وَمَا كَانُوٓاْ\nT;0;15:8:2:إِذࣰا مُّنظَرِينَ¦15:9:3:إِنَّا نَحۡنُ نَزَّلۡنَا ٱلذِّكۡرَ وَإِنَّا لَهُۥ لَحَٰفِظُونَ\nT;0;15:10:3:وَلَقَدۡ أَرۡسَلۡنَا مِن قَبۡلِكَ فِي شِيَعِ ٱلۡأَوَّلِينَ¦15:11:1:وَمَا يَأۡتِيهِم\nT;0;15:11:2:مِّن رَّسُولٍ إِلَّا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ¦15:12:1:كَذَٰلِكَ نَسۡلُكُهُۥ\nT;0;15:12:2:فِي قُلُوبِ ٱلۡمُجۡرِمِينَ¦15:13:3:لَا يُؤۡمِنُونَ بِهِۦ وَقَدۡ خَلَتۡ سُنَّةُ ٱلۡأَوَّلِينَ\nT;0;15:14:3:وَلَوۡ فَتَحۡنَا عَلَيۡهِم بَابࣰا مِّنَ ٱلسَّمَآءِ فَظَلُّواْ فِيهِ يَعۡرُجُونَ\nT;0;15:15:3:لَقَالُوٓاْ إِنَّمَا سُكِّرَتۡ أَبۡصَٰرُنَا بَلۡ نَحۡنُ قَوۡمࣱ مَّسۡحُورُونَ',
  '14;27;0;\nT;0;15:16:3:وَلَقَدۡ جَعَلۡنَا فِي ٱلسَّمَآءِ بُرُوجࣰا وَزَيَّنَّٰهَا لِلنَّٰظِرِينَ\nT;0;15:17:3:وَحَفِظۡنَٰهَا مِن كُلِّ شَيۡطَٰنࣲ رَّجِيمٍ¦15:18:1:إِلَّا مَنِ ٱسۡتَرَقَ ٱلسَّمۡعَ\nT;0;15:18:2:فَأَتۡبَعَهُۥ شِهَابࣱ مُّبِينࣱ¦15:19:1:وَٱلۡأَرۡضَ مَدَدۡنَٰهَا وَأَلۡقَيۡنَا فِيهَا\nT;0;15:19:2:رَوَٰسِيَ وَأَنۢبَتۡنَا فِيهَا مِن كُلِّ شَيۡءࣲ مَّوۡزُونࣲ¦15:20:1:وَجَعَلۡنَا لَكُمۡ\nT;0;15:20:2:فِيهَا مَعَٰيِشَ وَمَن لَّسۡتُمۡ لَهُۥ بِرَٰزِقِينَ¦15:21:1:وَإِن مِّن شَيۡءٍ إِلَّا\nT;0;15:21:2:عِندَنَا خَزَآئِنُهُۥ وَمَا نُنَزِّلُهُۥٓ إِلَّا بِقَدَرࣲ مَّعۡلُومࣲ¦15:22:1:وَأَرۡسَلۡنَا\nT;0;15:22:0:ٱلرِّيَٰحَ لَوَٰقِحَ فَأَنزَلۡنَا مِنَ ٱلسَّمَآءِ مَآءࣰ فَأَسۡقَيۡنَٰكُمُوهُ وَمَآ أَنتُمۡ\nT;0;15:22:2:لَهُۥ بِخَٰزِنِينَ¦15:23:3:وَإِنَّا لَنَحۡنُ نُحۡيِۦ وَنُمِيتُ وَنَحۡنُ ٱلۡوَٰرِثُونَ\nT;0;15:24:3:وَلَقَدۡ عَلِمۡنَا ٱلۡمُسۡتَقۡدِمِينَ مِنكُمۡ وَلَقَدۡ عَلِمۡنَا ٱلۡمُسۡتَـٔۡخِرِينَ\nT;0;15:25:3:وَإِنَّ رَبَّكَ هُوَ يَحۡشُرُهُمۡۚ إِنَّهُۥ حَكِيمٌ عَلِيمࣱ¦15:26:1:وَلَقَدۡ خَلَقۡنَا\nT;0;15:26:2:ٱلۡإِنسَٰنَ مِن صَلۡصَٰلࣲ مِّنۡ حَمَإࣲ مَّسۡنُونࣲ¦15:27:1:وَٱلۡجَآنَّ خَلَقۡنَٰهُ مِن\nT;0;15:27:2:قَبۡلُ مِن نَّارِ ٱلسَّمُومِ¦15:28:1:وَإِذۡ قَالَ رَبُّكَ لِلۡمَلَٰٓئِكَةِ إِنِّي خَٰلِقُۢ بَشَرࣰا\nT;0;15:28:2:مِّن صَلۡصَٰلࣲ مِّنۡ حَمَإࣲ مَّسۡنُونࣲ¦15:29:1:فَإِذَا سَوَّيۡتُهُۥ وَنَفَخۡتُ فِيهِ\nT;0;15:29:2:مِن رُّوحِي فَقَعُواْ لَهُۥ سَٰجِدِينَ¦15:30:1:فَسَجَدَ ٱلۡمَلَٰٓئِكَةُ كُلُّهُمۡ\nT;0;15:30:2:أَجۡمَعُونَ¦15:31:3:إِلَّآ إِبۡلِيسَ أَبَىٰٓ أَن يَكُونَ مَعَ ٱلسَّٰجِدِينَ',
  '14;27;0;106\nT;0;15:32:3:قَالَ يَٰٓإِبۡلِيسُ مَا لَكَ أَلَّا تَكُونَ مَعَ ٱلسَّٰجِدِينَ¦15:33:1:قَالَ لَمۡ أَكُن\nT;0;15:33:2:لِّأَسۡجُدَ لِبَشَرٍ خَلَقۡتَهُۥ مِن صَلۡصَٰلࣲ مِّنۡ حَمَإࣲ مَّسۡنُونࣲ\nT;0;15:34:3:قَالَ فَٱخۡرُجۡ مِنۡهَا فَإِنَّكَ رَجِيمࣱ¦15:35:1:وَإِنَّ عَلَيۡكَ ٱللَّعۡنَةَ إِلَىٰ يَوۡمِ\nT;0;15:35:2:ٱلدِّينِ¦15:36:3:قَالَ رَبِّ فَأَنظِرۡنِيٓ إِلَىٰ يَوۡمِ يُبۡعَثُونَ¦15:37:1:قَالَ فَإِنَّكَ\nT;0;15:37:2:مِنَ ٱلۡمُنظَرِينَ¦15:38:3:إِلَىٰ يَوۡمِ ٱلۡوَقۡتِ ٱلۡمَعۡلُومِ¦15:39:1:قَالَ رَبِّ بِمَآ\nT;0;15:39:2:أَغۡوَيۡتَنِي لَأُزَيِّنَنَّ لَهُمۡ فِي ٱلۡأَرۡضِ وَلَأُغۡوِيَنَّهُمۡ أَجۡمَعِينَ\nT;0;15:40:3:إِلَّا عِبَادَكَ مِنۡهُمُ ٱلۡمُخۡلَصِينَ¦15:41:1:قَالَ هَٰذَا صِرَٰطٌ عَلَيَّ\nT;0;15:41:2:مُسۡتَقِيمٌ¦15:42:1:إِنَّ عِبَادِي لَيۡسَ لَكَ عَلَيۡهِمۡ سُلۡطَٰنٌ إِلَّا مَنِ\nT;0;15:42:2:ٱتَّبَعَكَ مِنَ ٱلۡغَاوِينَ¦15:43:3:وَإِنَّ جَهَنَّمَ لَمَوۡعِدُهُمۡ أَجۡمَعِينَ\nT;0;15:44:3:لَهَا سَبۡعَةُ أَبۡوَٰبࣲ لِّكُلِّ بَابࣲ مِّنۡهُمۡ جُزۡءࣱ مَّقۡسُومٌ¦15:45:1:إِنَّ\nT;0;15:45:2:ٱلۡمُتَّقِينَ فِي جَنَّٰتࣲ وَعُيُونٍ¦15:46:3:ٱدۡخُلُوهَا بِسَلَٰمٍ ءَامِنِينَ\nT;0;15:47:3:وَنَزَعۡنَا مَا فِي صُدُورِهِم مِّنۡ غِلٍّ إِخۡوَٰنًا عَلَىٰ سُرُرࣲ مُّتَقَٰبِلِينَ\nT;0;15:48:3:لَا يَمَسُّهُمۡ فِيهَا نَصَبࣱ وَمَا هُم مِّنۡهَا بِمُخۡرَجِينَ\nT;0;15:49:3:۞ نَبِّئۡ عِبَادِيٓ أَنِّيٓ أَنَا ٱلۡغَفُورُ ٱلرَّحِيمُ¦15:50:1:وَأَنَّ عَذَابِي\nT;0;15:50:2:هُوَ ٱلۡعَذَابُ ٱلۡأَلِيمُ¦15:51:3:وَنَبِّئۡهُمۡ عَن ضَيۡفِ إِبۡرَٰهِيمَ',
  '14;27;1;\nT;0;15:52:3:إِذۡ دَخَلُواْ عَلَيۡهِ فَقَالُواْ سَلَٰمࣰا قَالَ إِنَّا مِنكُمۡ وَجِلُونَ¦15:53:1:قَالُواْ\nT;0;15:53:2:لَا تَوۡجَلۡ إِنَّا نُبَشِّرُكَ بِغُلَٰمٍ عَلِيمࣲ¦15:54:1:قَالَ أَبَشَّرۡتُمُونِي عَلَىٰٓ أَن\nT;0;15:54:2:مَّسَّنِيَ ٱلۡكِبَرُ فَبِمَ تُبَشِّرُونَ¦15:55:1:قَالُواْ بَشَّرۡنَٰكَ بِٱلۡحَقِّ\nT;0;15:55:2:فَلَا تَكُن مِّنَ ٱلۡقَٰنِطِينَ¦15:56:1:قَالَ وَمَن يَقۡنَطُ مِن رَّحۡمَةِ\nT;0;15:56:2:رَبِّهِۦٓ إِلَّا ٱلضَّآلُّونَ¦15:57:3:قَالَ فَمَا خَطۡبُكُمۡ أَيُّهَا ٱلۡمُرۡسَلُونَ\nT;0;15:58:3:قَالُوٓاْ إِنَّآ أُرۡسِلۡنَآ إِلَىٰ قَوۡمࣲ مُّجۡرِمِينَ¦15:59:1:إِلَّآ ءَالَ لُوطٍ\nT;0;15:59:2:إِنَّا لَمُنَجُّوهُمۡ أَجۡمَعِينَ¦15:60:1:إِلَّا ٱمۡرَأَتَهُۥ قَدَّرۡنَآ إِنَّهَا لَمِنَ\nT;0;15:60:2:ٱلۡغَٰبِرِينَ¦15:61:3:فَلَمَّا جَآءَ ءَالَ لُوطٍ ٱلۡمُرۡسَلُونَ¦15:62:1:قَالَ\nT;0;15:62:2:إِنَّكُمۡ قَوۡمࣱ مُّنكَرُونَ¦15:63:1:قَالُواْ بَلۡ جِئۡنَٰكَ بِمَا كَانُواْ فِيهِ\nT;0;15:63:2:يَمۡتَرُونَ¦15:64:3:وَأَتَيۡنَٰكَ بِٱلۡحَقِّ وَإِنَّا لَصَٰدِقُونَ¦15:65:1:فَأَسۡرِ\nT;0;15:65:0:بِأَهۡلِكَ بِقِطۡعࣲ مِّنَ ٱلَّيۡلِ وَٱتَّبِعۡ أَدۡبَٰرَهُمۡ وَلَا يَلۡتَفِتۡ مِنكُمۡ أَحَدࣱ\nT;0;15:65:2:وَٱمۡضُواْ حَيۡثُ تُؤۡمَرُونَ¦15:66:1:وَقَضَيۡنَآ إِلَيۡهِ ذَٰلِكَ ٱلۡأَمۡرَ أَنَّ\nT;0;15:66:2:دَابِرَ هَٰٓؤُلَآءِ مَقۡطُوعࣱ مُّصۡبِحِينَ¦15:67:1:وَجَآءَ أَهۡلُ ٱلۡمَدِينَةِ\nT;0;15:67:2:يَسۡتَبۡشِرُونَ¦15:68:3:قَالَ إِنَّ هَٰٓؤُلَآءِ ضَيۡفِي فَلَا تَفۡضَحُونِ\nT;0;15:69:3:وَٱتَّقُواْ ٱللَّهَ وَلَا تُخۡزُونِ¦15:70:3:قَالُوٓاْ أَوَلَمۡ نَنۡهَكَ عَنِ ٱلۡعَٰلَمِينَ',
  '14;27;1;\nT;0;15:71:3:قَالَ هَٰٓؤُلَآءِ بَنَاتِيٓ إِن كُنتُمۡ فَٰعِلِينَ¦15:72:1:لَعَمۡرُكَ إِنَّهُمۡ لَفِي سَكۡرَتِهِمۡ\nT;0;15:72:2:يَعۡمَهُونَ¦15:73:3:فَأَخَذَتۡهُمُ ٱلصَّيۡحَةُ مُشۡرِقِينَ¦15:74:1:فَجَعَلۡنَا عَٰلِيَهَا\nT;0;15:74:2:سَافِلَهَا وَأَمۡطَرۡنَا عَلَيۡهِمۡ حِجَارَةࣰ مِّن سِجِّيلٍ¦15:75:1:إِنَّ فِي ذَٰلِكَ\nT;0;15:75:2:لَأٓيَٰتࣲ لِّلۡمُتَوَسِّمِينَ¦15:76:3:وَإِنَّهَا لَبِسَبِيلࣲ مُّقِيمٍ¦15:77:1:إِنَّ فِي ذَٰلِكَ\nT;0;15:77:2:لَأٓيَةࣰ لِّلۡمُؤۡمِنِينَ¦15:78:3:وَإِن كَانَ أَصۡحَٰبُ ٱلۡأَيۡكَةِ لَظَٰلِمِينَ\nT;0;15:79:3:فَٱنتَقَمۡنَا مِنۡهُمۡ وَإِنَّهُمَا لَبِإِمَامࣲ مُّبِينࣲ¦15:80:1:وَلَقَدۡ كَذَّبَ أَصۡحَٰبُ\nT;0;15:80:2:ٱلۡحِجۡرِ ٱلۡمُرۡسَلِينَ¦15:81:3:وَءَاتَيۡنَٰهُمۡ ءَايَٰتِنَا فَكَانُواْ عَنۡهَا مُعۡرِضِينَ\nT;0;15:82:3:وَكَانُواْ يَنۡحِتُونَ مِنَ ٱلۡجِبَالِ بُيُوتًا ءَامِنِينَ¦15:83:1:فَأَخَذَتۡهُمُ\nT;0;15:83:2:ٱلصَّيۡحَةُ مُصۡبِحِينَ¦15:84:3:فَمَآ أَغۡنَىٰ عَنۡهُم مَّا كَانُواْ يَكۡسِبُونَ\nT;0;15:85:1:وَمَا خَلَقۡنَا ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ وَمَا بَيۡنَهُمَآ إِلَّا بِٱلۡحَقِّۗ وَإِنَّ\nT;0;15:85:2:ٱلسَّاعَةَ لَأٓتِيَةࣱۖ فَٱصۡفَحِ ٱلصَّفۡحَ ٱلۡجَمِيلَ¦15:86:1:إِنَّ رَبَّكَ هُوَ\nT;0;15:86:2:ٱلۡخَلَّٰقُ ٱلۡعَلِيمُ¦15:87:1:وَلَقَدۡ ءَاتَيۡنَٰكَ سَبۡعࣰا مِّنَ ٱلۡمَثَانِي\nT;0;15:87:2:وَٱلۡقُرۡءَانَ ٱلۡعَظِيمَ¦15:88:1:لَا تَمُدَّنَّ عَيۡنَيۡكَ إِلَىٰ مَا مَتَّعۡنَا بِهِۦٓ أَزۡوَٰجࣰا\nT;0;15:88:2:مِّنۡهُمۡ وَلَا تَحۡزَنۡ عَلَيۡهِمۡ وَٱخۡفِضۡ جَنَاحَكَ لِلۡمُؤۡمِنِينَ¦15:89:1:وَقُلۡ\nT;0;15:89:2:إِنِّيٓ أَنَا ٱلنَّذِيرُ ٱلۡمُبِينُ¦15:90:3:كَمَآ أَنزَلۡنَا عَلَى ٱلۡمُقۡتَسِمِينَ',
  '14;27;1;107\nT;0;15:91:3:ٱلَّذِينَ جَعَلُواْ ٱلۡقُرۡءَانَ عِضِينَ¦15:92:1:فَوَرَبِّكَ لَنَسۡـَٔلَنَّهُمۡ\nT;0;15:92:2:أَجۡمَعِينَ¦15:93:3:عَمَّا كَانُواْ يَعۡمَلُونَ¦15:94:1:فَٱصۡدَعۡ بِمَا تُؤۡمَرُ وَأَعۡرِضۡ\nT;0;15:94:2:عَنِ ٱلۡمُشۡرِكِينَ¦15:95:3:إِنَّا كَفَيۡنَٰكَ ٱلۡمُسۡتَهۡزِءِينَ¦15:96:1:ٱلَّذِينَ\nT;0;15:96:2:يَجۡعَلُونَ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَۚ فَسَوۡفَ يَعۡلَمُونَ¦15:97:1:وَلَقَدۡ نَعۡلَمُ\nT;0;15:97:2:أَنَّكَ يَضِيقُ صَدۡرُكَ بِمَا يَقُولُونَ¦15:98:1:فَسَبِّحۡ بِحَمۡدِ رَبِّكَ وَكُن\nT;2;15:98:2:مِّنَ ٱلسَّٰجِدِينَ¦15:99:3:وَٱعۡبُدۡ رَبَّكَ حَتَّىٰ يَأۡتِيَكَ ٱلۡيَقِينُ\nH;16\nB;16\nT;0;16:1:3:أَتَىٰٓ أَمۡرُ ٱللَّهِ فَلَا تَسۡتَعۡجِلُوهُۚ سُبۡحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا يُشۡرِكُونَ\nT;0;16:2:1:يُنَزِّلُ ٱلۡمَلَٰٓئِكَةَ بِٱلرُّوحِ مِنۡ أَمۡرِهِۦ عَلَىٰ مَن يَشَآءُ مِنۡ\nT;0;16:2:2:عِبَادِهِۦٓ أَنۡ أَنذِرُوٓاْ أَنَّهُۥ لَآ إِلَٰهَ إِلَّآ أَنَا۠ فَٱتَّقُونِ¦16:3:1:خَلَقَ\nT;0;16:3:2:ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ بِٱلۡحَقِّۚ تَعَٰلَىٰ عَمَّا يُشۡرِكُونَ¦16:4:1:خَلَقَ\nT;0;16:4:2:ٱلۡإِنسَٰنَ مِن نُّطۡفَةࣲ فَإِذَا هُوَ خَصِيمࣱ مُّبِينࣱ¦16:5:1:وَٱلۡأَنۡعَٰمَ\nT;0;16:5:2:خَلَقَهَاۖ لَكُمۡ فِيهَا دِفۡءࣱ وَمَنَٰفِعُ وَمِنۡهَا تَأۡكُلُونَ\nT;0;16:6:3:وَلَكُمۡ فِيهَا جَمَالٌ حِينَ تُرِيحُونَ وَحِينَ تَسۡرَحُونَ',
  '14;27;2;\nT;0;16:7:1:وَتَحۡمِلُ أَثۡقَالَكُمۡ إِلَىٰ بَلَدࣲ لَّمۡ تَكُونُواْ بَٰلِغِيهِ إِلَّا بِشِقِّ\nT;0;16:7:2:ٱلۡأَنفُسِۚ إِنَّ رَبَّكُمۡ لَرَءُوفࣱ رَّحِيمࣱ¦16:8:1:وَٱلۡخَيۡلَ وَٱلۡبِغَالَ\nT;0;16:8:2:وَٱلۡحَمِيرَ لِتَرۡكَبُوهَا وَزِينَةࣰۚ وَيَخۡلُقُ مَا لَا تَعۡلَمُونَ\nT;0;16:9:1:وَعَلَى ٱللَّهِ قَصۡدُ ٱلسَّبِيلِ وَمِنۡهَا جَآئِرࣱۚ وَلَوۡ شَآءَ لَهَدَىٰكُمۡ\nT;0;16:9:2:أَجۡمَعِينَ¦16:10:1:هُوَ ٱلَّذِيٓ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءࣰۖ لَّكُم\nT;0;16:10:2:مِّنۡهُ شَرَابࣱ وَمِنۡهُ شَجَرࣱ فِيهِ تُسِيمُونَ¦16:11:1:يُنۢبِتُ لَكُم\nT;0;16:11:0:بِهِ ٱلزَّرۡعَ وَٱلزَّيۡتُونَ وَٱلنَّخِيلَ وَٱلۡأَعۡنَٰبَ وَمِن كُلِّ\nT;0;16:11:2:ٱلثَّمَرَٰتِۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةࣰ لِّقَوۡمࣲ يَتَفَكَّرُونَ\nT;0;16:12:1:وَسَخَّرَ لَكُمُ ٱلَّيۡلَ وَٱلنَّهَارَ وَٱلشَّمۡسَ وَٱلۡقَمَرَۖ\nT;0;16:12:0:وَٱلنُّجُومُ مُسَخَّرَٰتُۢ بِأَمۡرِهِۦٓۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتࣲ لِّقَوۡمࣲ\nT;0;16:12:2:يَعۡقِلُونَ¦16:13:1:وَمَا ذَرَأَ لَكُمۡ فِي ٱلۡأَرۡضِ مُخۡتَلِفًا\nT;0;16:13:2:أَلۡوَٰنُهُۥٓۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةࣰ لِّقَوۡمࣲ يَذَّكَّرُونَ\nT;0;16:14:1:وَهُوَ ٱلَّذِي سَخَّرَ ٱلۡبَحۡرَ لِتَأۡكُلُواْ مِنۡهُ لَحۡمࣰا طَرِيࣰّا\nT;0;16:14:0:وَتَسۡتَخۡرِجُواْ مِنۡهُ حِلۡيَةࣰ تَلۡبَسُونَهَاۖ وَتَرَى ٱلۡفُلۡكَ مَوَاخِرَ\nT;0;16:14:2:فِيهِ وَلِتَبۡتَغُواْ مِن فَضۡلِهِۦ وَلَعَلَّكُمۡ تَشۡكُرُونَ',
  '14;27;2;\nT;0;16:15:1:وَأَلۡقَىٰ فِي ٱلۡأَرۡضِ رَوَٰسِيَ أَن تَمِيدَ بِكُمۡ وَأَنۡهَٰرࣰا وَسُبُلࣰا\nT;0;16:15:2:لَّعَلَّكُمۡ تَهۡتَدُونَ¦16:16:3:وَعَلَٰمَٰتࣲۚ وَبِٱلنَّجۡمِ هُمۡ يَهۡتَدُونَ\nT;0;16:17:3:أَفَمَن يَخۡلُقُ كَمَن لَّا يَخۡلُقُۚ أَفَلَا تَذَكَّرُونَ¦16:18:1:وَإِن\nT;0;16:18:2:تَعُدُّواْ نِعۡمَةَ ٱللَّهِ لَا تُحۡصُوهَآۗ إِنَّ ٱللَّهَ لَغَفُورࣱ رَّحِيمࣱ\nT;0;16:19:3:وَٱللَّهُ يَعۡلَمُ مَا تُسِرُّونَ وَمَا تُعۡلِنُونَ¦16:20:1:وَٱلَّذِينَ يَدۡعُونَ\nT;0;16:20:2:مِن دُونِ ٱللَّهِ لَا يَخۡلُقُونَ شَيۡـࣰٔا وَهُمۡ يُخۡلَقُونَ¦16:21:1:أَمۡوَٰتٌ\nT;0;16:21:2:غَيۡرُ أَحۡيَآءࣲۖ وَمَا يَشۡعُرُونَ أَيَّانَ يُبۡعَثُونَ¦16:22:1:إِلَٰهُكُمۡ إِلَٰهࣱ\nT;0;16:22:0:وَٰحِدࣱۚ فَٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ قُلُوبُهُم مُّنكِرَةࣱ وَهُم\nT;0;16:22:2:مُّسۡتَكۡبِرُونَ¦16:23:1:لَا جَرَمَ أَنَّ ٱللَّهَ يَعۡلَمُ مَا يُسِرُّونَ وَمَا\nT;0;16:23:2:يُعۡلِنُونَۚ إِنَّهُۥ لَا يُحِبُّ ٱلۡمُسۡتَكۡبِرِينَ¦16:24:1:وَإِذَا قِيلَ لَهُم\nT;0;16:24:2:مَّاذَآ أَنزَلَ رَبُّكُمۡ قَالُوٓاْ أَسَٰطِيرُ ٱلۡأَوَّلِينَ¦16:25:1:لِيَحۡمِلُوٓاْ\nT;0;16:25:0:أَوۡزَارَهُمۡ كَامِلَةࣰ يَوۡمَ ٱلۡقِيَٰمَةِ وَمِنۡ أَوۡزَارِ ٱلَّذِينَ يُضِلُّونَهُم\nT;0;16:25:2:بِغَيۡرِ عِلۡمٍۗ أَلَا سَآءَ مَا يَزِرُونَ¦16:26:1:قَدۡ مَكَرَ ٱلَّذِينَ مِن قَبۡلِهِمۡ\nT;0;16:26:0:فَأَتَى ٱللَّهُ بُنۡيَٰنَهُم مِّنَ ٱلۡقَوَاعِدِ فَخَرَّ عَلَيۡهِمُ ٱلسَّقۡفُ\nT;0;16:26:2:مِن فَوۡقِهِمۡ وَأَتَىٰهُمُ ٱلۡعَذَابُ مِنۡ حَيۡثُ لَا يَشۡعُرُونَ',
  '14;27;2;108\nT;0;16:27:1:ثُمَّ يَوۡمَ ٱلۡقِيَٰمَةِ يُخۡزِيهِمۡ وَيَقُولُ أَيۡنَ شُرَكَآءِيَ ٱلَّذِينَ\nT;0;16:27:0:كُنتُمۡ تُشَٰٓقُّونَ فِيهِمۡۚ قَالَ ٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ إِنَّ ٱلۡخِزۡيَ\nT;0;16:27:2:ٱلۡيَوۡمَ وَٱلسُّوٓءَ عَلَى ٱلۡكَٰفِرِينَ¦16:28:1:ٱلَّذِينَ تَتَوَفَّىٰهُمُ ٱلۡمَلَٰٓئِكَةُ\nT;0;16:28:0:ظَالِمِيٓ أَنفُسِهِمۡۖ فَأَلۡقَوُاْ ٱلسَّلَمَ مَا كُنَّا نَعۡمَلُ مِن سُوٓءِۭۚ بَلَىٰٓۚ\nT;0;16:28:2:إِنَّ ٱللَّهَ عَلِيمُۢ بِمَا كُنتُمۡ تَعۡمَلُونَ¦16:29:1:فَٱدۡخُلُوٓاْ أَبۡوَٰبَ جَهَنَّمَ\nT;0;16:29:2:خَٰلِدِينَ فِيهَاۖ فَلَبِئۡسَ مَثۡوَى ٱلۡمُتَكَبِّرِينَ¦16:30:1:۞ وَقِيلَ\nT;0;16:30:0:لِلَّذِينَ ٱتَّقَوۡاْ مَاذَآ أَنزَلَ رَبُّكُمۡۚ قَالُواْ خَيۡرࣰاۗ لِّلَّذِينَ أَحۡسَنُواْ فِي\nT;0;16:30:2:هَٰذِهِ ٱلدُّنۡيَا حَسَنَةࣱۚ وَلَدَارُ ٱلۡأٓخِرَةِ خَيۡرࣱۚ وَلَنِعۡمَ دَارُ ٱلۡمُتَّقِينَ\nT;0;16:31:1:جَنَّٰتُ عَدۡنࣲ يَدۡخُلُونَهَا تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُۖ\nT;0;16:31:2:لَهُمۡ فِيهَا مَا يَشَآءُونَۚ كَذَٰلِكَ يَجۡزِي ٱللَّهُ ٱلۡمُتَّقِينَ\nT;0;16:32:1:ٱلَّذِينَ تَتَوَفَّىٰهُمُ ٱلۡمَلَٰٓئِكَةُ طَيِّبِينَ يَقُولُونَ سَلَٰمٌ عَلَيۡكُمُ\nT;0;16:32:2:ٱدۡخُلُواْ ٱلۡجَنَّةَ بِمَا كُنتُمۡ تَعۡمَلُونَ¦16:33:1:هَلۡ يَنظُرُونَ إِلَّآ أَن\nT;0;16:33:0:تَأۡتِيَهُمُ ٱلۡمَلَٰٓئِكَةُ أَوۡ يَأۡتِيَ أَمۡرُ رَبِّكَۚ كَذَٰلِكَ فَعَلَ ٱلَّذِينَ مِن\nT;0;16:33:2:قَبۡلِهِمۡۚ وَمَا ظَلَمَهُمُ ٱللَّهُ وَلَٰكِن كَانُوٓاْ أَنفُسَهُمۡ يَظۡلِمُونَ\nT;0;16:34:3:فَأَصَابَهُمۡ سَيِّـَٔاتُ مَا عَمِلُواْ وَحَاقَ بِهِم مَّا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ',
  '14;27;3;\nT;0;16:35:1:وَقَالَ ٱلَّذِينَ أَشۡرَكُواْ لَوۡ شَآءَ ٱللَّهُ مَا عَبَدۡنَا مِن دُونِهِۦ مِن\nT;0;16:35:0:شَيۡءࣲ نَّحۡنُ وَلَآ ءَابَآؤُنَا وَلَا حَرَّمۡنَا مِن دُونِهِۦ مِن شَيۡءࣲۚ كَذَٰلِكَ\nT;0;16:35:2:فَعَلَ ٱلَّذِينَ مِن قَبۡلِهِمۡۚ فَهَلۡ عَلَى ٱلرُّسُلِ إِلَّا ٱلۡبَلَٰغُ ٱلۡمُبِينُ\nT;0;16:36:1:وَلَقَدۡ بَعَثۡنَا فِي كُلِّ أُمَّةࣲ رَّسُولًا أَنِ ٱعۡبُدُواْ ٱللَّهَ\nT;0;16:36:0:وَٱجۡتَنِبُواْ ٱلطَّٰغُوتَۖ فَمِنۡهُم مَّنۡ هَدَى ٱللَّهُ وَمِنۡهُم مَّنۡ\nT;0;16:36:0:حَقَّتۡ عَلَيۡهِ ٱلضَّلَٰلَةُۚ فَسِيرُواْ فِي ٱلۡأَرۡضِ فَٱنظُرُواْ كَيۡفَ\nT;0;16:36:2:كَانَ عَٰقِبَةُ ٱلۡمُكَذِّبِينَ¦16:37:1:إِن تَحۡرِصۡ عَلَىٰ هُدَىٰهُمۡ\nT;0;16:37:2:فَإِنَّ ٱللَّهَ لَا يَهۡدِي مَن يُضِلُّۖ وَمَا لَهُم مِّن نَّٰصِرِينَ\nT;0;16:38:1:وَأَقۡسَمُواْ بِٱللَّهِ جَهۡدَ أَيۡمَٰنِهِمۡ لَا يَبۡعَثُ ٱللَّهُ مَن يَمُوتُۚ بَلَىٰ\nT;0;16:38:2:وَعۡدًا عَلَيۡهِ حَقࣰّا وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَعۡلَمُونَ\nT;0;16:39:1:لِيُبَيِّنَ لَهُمُ ٱلَّذِي يَخۡتَلِفُونَ فِيهِ وَلِيَعۡلَمَ ٱلَّذِينَ كَفَرُوٓاْ\nT;0;16:39:2:أَنَّهُمۡ كَانُواْ كَٰذِبِينَ¦16:40:1:إِنَّمَا قَوۡلُنَا لِشَيۡءٍ إِذَآ أَرَدۡنَٰهُ أَن نَّقُولَ\nT;0;16:40:2:لَهُۥ كُن فَيَكُونُ¦16:41:1:وَٱلَّذِينَ هَاجَرُواْ فِي ٱللَّهِ مِنۢ بَعۡدِ مَا ظُلِمُواْ\nT;0;16:41:0:لَنُبَوِّئَنَّهُمۡ فِي ٱلدُّنۡيَا حَسَنَةࣰۖ وَلَأَجۡرُ ٱلۡأٓخِرَةِ أَكۡبَرُۚ لَوۡ كَانُواْ\nT;0;16:41:2:يَعۡلَمُونَ¦16:42:3:ٱلَّذِينَ صَبَرُواْ وَعَلَىٰ رَبِّهِمۡ يَتَوَكَّلُونَ',
  '14;27;3;109\nT;0;16:43:1:وَمَآ أَرۡسَلۡنَا مِن قَبۡلِكَ إِلَّا رِجَالࣰا نُّوحِيٓ إِلَيۡهِمۡۖ فَسۡـَٔلُوٓاْ أَهۡلَ\nT;0;16:43:2:ٱلذِّكۡرِ إِن كُنتُمۡ لَا تَعۡلَمُونَ¦16:44:1:بِٱلۡبَيِّنَٰتِ وَٱلزُّبُرِۗ وَأَنزَلۡنَآ إِلَيۡكَ\nT;0;16:44:2:ٱلذِّكۡرَ لِتُبَيِّنَ لِلنَّاسِ مَا نُزِّلَ إِلَيۡهِمۡ وَلَعَلَّهُمۡ يَتَفَكَّرُونَ\nT;0;16:45:1:أَفَأَمِنَ ٱلَّذِينَ مَكَرُواْ ٱلسَّيِّـَٔاتِ أَن يَخۡسِفَ ٱللَّهُ بِهِمُ ٱلۡأَرۡضَ\nT;0;16:45:2:أَوۡ يَأۡتِيَهُمُ ٱلۡعَذَابُ مِنۡ حَيۡثُ لَا يَشۡعُرُونَ¦16:46:1:أَوۡ يَأۡخُذَهُمۡ\nT;0;16:46:2:فِي تَقَلُّبِهِمۡ فَمَا هُم بِمُعۡجِزِينَ¦16:47:1:أَوۡ يَأۡخُذَهُمۡ عَلَىٰ تَخَوُّفࣲ فَإِنَّ\nT;0;16:47:2:رَبَّكُمۡ لَرَءُوفࣱ رَّحِيمٌ¦16:48:1:أَوَلَمۡ يَرَوۡاْ إِلَىٰ مَا خَلَقَ ٱللَّهُ مِن شَيۡءࣲ\nT;0;16:48:2:يَتَفَيَّؤُاْ ظِلَٰلُهُۥ عَنِ ٱلۡيَمِينِ وَٱلشَّمَآئِلِ سُجَّدࣰا لِّلَّهِ وَهُمۡ دَٰخِرُونَ\nT;0;16:49:1:وَلِلَّهِۤ يَسۡجُدُۤ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِ مِن دَآبَّةࣲ\nT;0;16:49:2:وَٱلۡمَلَٰٓئِكَةُ وَهُمۡ لَا يَسۡتَكۡبِرُونَ¦16:50:1:يَخَافُونَ رَبَّهُم مِّن فَوۡقِهِمۡ\nT;0;16:50:2:وَيَفۡعَلُونَ مَا يُؤۡمَرُونَ۩¦16:51:1:۞ وَقَالَ ٱللَّهُ لَا تَتَّخِذُوٓاْ إِلَٰهَيۡنِ\nT;0;16:51:2:ٱثۡنَيۡنِۖ إِنَّمَا هُوَ إِلَٰهࣱ وَٰحِدࣱ فَإِيَّٰيَ فَٱرۡهَبُونِ¦16:52:1:وَلَهُۥ مَا فِي ٱلسَّمَٰوَٰتِ\nT;0;16:52:2:وَٱلۡأَرۡضِ وَلَهُ ٱلدِّينُ وَاصِبًاۚ أَفَغَيۡرَ ٱللَّهِ تَتَّقُونَ¦16:53:1:وَمَا بِكُم مِّن\nT;0;16:53:2:نِّعۡمَةࣲ فَمِنَ ٱللَّهِۖ ثُمَّ إِذَا مَسَّكُمُ ٱلضُّرُّ فَإِلَيۡهِ تَجۡـَٔرُونَ¦16:54:1:ثُمَّ إِذَا\nT;0;16:54:2:كَشَفَ ٱلضُّرَّ عَنكُمۡ إِذَا فَرِيقࣱ مِّنكُم بِرَبِّهِمۡ يُشۡرِكُونَ',
  '14;28;0;\nT;0;16:55:3:لِيَكۡفُرُواْ بِمَآ ءَاتَيۡنَٰهُمۡۚ فَتَمَتَّعُواْ فَسَوۡفَ تَعۡلَمُونَ¦16:56:1:وَيَجۡعَلُونَ\nT;0;16:56:0:لِمَا لَا يَعۡلَمُونَ نَصِيبࣰا مِّمَّا رَزَقۡنَٰهُمۡۗ تَٱللَّهِ لَتُسۡـَٔلُنَّ عَمَّا كُنتُمۡ\nT;0;16:56:2:تَفۡتَرُونَ¦16:57:3:وَيَجۡعَلُونَ لِلَّهِ ٱلۡبَنَٰتِ سُبۡحَٰنَهُۥ وَلَهُم مَّا يَشۡتَهُونَ\nT;0;16:58:3:وَإِذَا بُشِّرَ أَحَدُهُم بِٱلۡأُنثَىٰ ظَلَّ وَجۡهُهُۥ مُسۡوَدࣰّا وَهُوَ كَظِيمࣱ\nT;0;16:59:1:يَتَوَٰرَىٰ مِنَ ٱلۡقَوۡمِ مِن سُوٓءِ مَا بُشِّرَ بِهِۦٓۚ أَيُمۡسِكُهُۥ عَلَىٰ هُونٍ\nT;0;16:59:2:أَمۡ يَدُسُّهُۥ فِي ٱلتُّرَابِۗ أَلَا سَآءَ مَا يَحۡكُمُونَ¦16:60:1:لِلَّذِينَ لَا يُؤۡمِنُونَ\nT;0;16:60:2:بِٱلۡأٓخِرَةِ مَثَلُ ٱلسَّوۡءِۖ وَلِلَّهِ ٱلۡمَثَلُ ٱلۡأَعۡلَىٰۚ وَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ\nT;0;16:61:1:وَلَوۡ يُؤَاخِذُ ٱللَّهُ ٱلنَّاسَ بِظُلۡمِهِم مَّا تَرَكَ عَلَيۡهَا مِن دَآبَّةࣲ\nT;0;16:61:0:وَلَٰكِن يُؤَخِّرُهُمۡ إِلَىٰٓ أَجَلࣲ مُّسَمࣰّىۖ فَإِذَا جَآءَ أَجَلُهُمۡ لَا يَسۡتَـٔۡخِرُونَ\nT;0;16:61:2:سَاعَةࣰ وَلَا يَسۡتَقۡدِمُونَ¦16:62:1:وَيَجۡعَلُونَ لِلَّهِ مَا يَكۡرَهُونَۚ وَتَصِفُ\nT;0;16:62:0:أَلۡسِنَتُهُمُ ٱلۡكَذِبَ أَنَّ لَهُمُ ٱلۡحُسۡنَىٰۚ لَا جَرَمَ أَنَّ لَهُمُ ٱلنَّارَ\nT;0;16:62:2:وَأَنَّهُم مُّفۡرَطُونَ¦16:63:1:تَٱللَّهِ لَقَدۡ أَرۡسَلۡنَآ إِلَىٰٓ أُمَمࣲ مِّن قَبۡلِكَ\nT;0;16:63:0:فَزَيَّنَ لَهُمُ ٱلشَّيۡطَٰنُ أَعۡمَٰلَهُمۡ فَهُوَ وَلِيُّهُمُ ٱلۡيَوۡمَ وَلَهُمۡ\nT;0;16:63:2:عَذَابٌ أَلِيمࣱ¦16:64:1:وَمَآ أَنزَلۡنَا عَلَيۡكَ ٱلۡكِتَٰبَ إِلَّا لِتُبَيِّنَ لَهُمُ\nT;0;16:64:2:ٱلَّذِي ٱخۡتَلَفُواْ فِيهِ وَهُدࣰى وَرَحۡمَةࣰ لِّقَوۡمࣲ يُؤۡمِنُونَ',
  '14;28;0;\nT;0;16:65:1:وَٱللَّهُ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءࣰ فَأَحۡيَا بِهِ ٱلۡأَرۡضَ بَعۡدَ مَوۡتِهَآۚ إِنَّ فِي\nT;0;16:65:2:ذَٰلِكَ لَأٓيَةࣰ لِّقَوۡمࣲ يَسۡمَعُونَ¦16:66:1:وَإِنَّ لَكُمۡ فِي ٱلۡأَنۡعَٰمِ لَعِبۡرَةࣰۖ نُّسۡقِيكُم\nT;0;16:66:2:مِّمَّا فِي بُطُونِهِۦ مِنۢ بَيۡنِ فَرۡثࣲ وَدَمࣲ لَّبَنًا خَالِصࣰا سَآئِغࣰا لِّلشَّٰرِبِينَ\nT;0;16:67:1:وَمِن ثَمَرَٰتِ ٱلنَّخِيلِ وَٱلۡأَعۡنَٰبِ تَتَّخِذُونَ مِنۡهُ سَكَرࣰا وَرِزۡقًا\nT;0;16:67:2:حَسَنًاۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةࣰ لِّقَوۡمࣲ يَعۡقِلُونَ¦16:68:1:وَأَوۡحَىٰ رَبُّكَ إِلَى ٱلنَّحۡلِ\nT;0;16:68:2:أَنِ ٱتَّخِذِي مِنَ ٱلۡجِبَالِ بُيُوتࣰا وَمِنَ ٱلشَّجَرِ وَمِمَّا يَعۡرِشُونَ¦16:69:1:ثُمَّ\nT;0;16:69:0:كُلِي مِن كُلِّ ٱلثَّمَرَٰتِ فَٱسۡلُكِي سُبُلَ رَبِّكِ ذُلُلࣰاۚ يَخۡرُجُ مِنۢ بُطُونِهَا\nT;0;16:69:0:شَرَابࣱ مُّخۡتَلِفٌ أَلۡوَٰنُهُۥ فِيهِ شِفَآءࣱ لِّلنَّاسِۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةࣰ لِّقَوۡمࣲ\nT;0;16:69:2:يَتَفَكَّرُونَ¦16:70:1:وَٱللَّهُ خَلَقَكُمۡ ثُمَّ يَتَوَفَّىٰكُمۡۚ وَمِنكُم مَّن يُرَدُّ إِلَىٰٓ\nT;0;16:70:2:أَرۡذَلِ ٱلۡعُمُرِ لِكَيۡ لَا يَعۡلَمَ بَعۡدَ عِلۡمࣲ شَيۡـًٔاۚ إِنَّ ٱللَّهَ عَلِيمࣱ قَدِيرࣱ\nT;0;16:71:1:وَٱللَّهُ فَضَّلَ بَعۡضَكُمۡ عَلَىٰ بَعۡضࣲ فِي ٱلرِّزۡقِۚ فَمَا ٱلَّذِينَ فُضِّلُواْ\nT;0;16:71:0:بِرَآدِّي رِزۡقِهِمۡ عَلَىٰ مَا مَلَكَتۡ أَيۡمَٰنُهُمۡ فَهُمۡ فِيهِ سَوَآءٌۚ أَفَبِنِعۡمَةِ\nT;0;16:71:2:ٱللَّهِ يَجۡحَدُونَ¦16:72:1:وَٱللَّهُ جَعَلَ لَكُم مِّنۡ أَنفُسِكُمۡ أَزۡوَٰجࣰا\nT;0;16:72:0:وَجَعَلَ لَكُم مِّنۡ أَزۡوَٰجِكُم بَنِينَ وَحَفَدَةࣰ وَرَزَقَكُم مِّنَ\nT;0;16:72:2:ٱلطَّيِّبَٰتِۚ أَفَبِٱلۡبَٰطِلِ يُؤۡمِنُونَ وَبِنِعۡمَتِ ٱللَّهِ هُمۡ يَكۡفُرُونَ',
  '14;28;0;110\nT;0;16:73:1:وَيَعۡبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَمۡلِكُ لَهُمۡ رِزۡقࣰا مِّنَ ٱلسَّمَٰوَٰتِ\nT;0;16:73:2:وَٱلۡأَرۡضِ شَيۡـࣰٔا وَلَا يَسۡتَطِيعُونَ¦16:74:1:فَلَا تَضۡرِبُواْ لِلَّهِ ٱلۡأَمۡثَالَۚ\nT;0;16:74:2:إِنَّ ٱللَّهَ يَعۡلَمُ وَأَنتُمۡ لَا تَعۡلَمُونَ¦16:75:1:۞ ضَرَبَ ٱللَّهُ مَثَلًا عَبۡدࣰا\nT;0;16:75:0:مَّمۡلُوكࣰا لَّا يَقۡدِرُ عَلَىٰ شَيۡءࣲ وَمَن رَّزَقۡنَٰهُ مِنَّا رِزۡقًا حَسَنࣰا\nT;0;16:75:0:فَهُوَ يُنفِقُ مِنۡهُ سِرࣰّا وَجَهۡرًاۖ هَلۡ يَسۡتَوُۥنَۚ ٱلۡحَمۡدُ لِلَّهِۚ\nT;0;16:75:2:بَلۡ أَكۡثَرُهُمۡ لَا يَعۡلَمُونَ¦16:76:1:وَضَرَبَ ٱللَّهُ مَثَلࣰا رَّجُلَيۡنِ\nT;0;16:76:0:أَحَدُهُمَآ أَبۡكَمُ لَا يَقۡدِرُ عَلَىٰ شَيۡءࣲ وَهُوَ كَلٌّ عَلَىٰ مَوۡلَىٰهُ\nT;0;16:76:0:أَيۡنَمَا يُوَجِّههُّ لَا يَأۡتِ بِخَيۡرٍ هَلۡ يَسۡتَوِي هُوَ وَمَن يَأۡمُرُ\nT;0;16:76:2:بِٱلۡعَدۡلِ وَهُوَ عَلَىٰ صِرَٰطࣲ مُّسۡتَقِيمࣲ¦16:77:1:وَلِلَّهِ غَيۡبُ\nT;0;16:77:0:ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ وَمَآ أَمۡرُ ٱلسَّاعَةِ إِلَّا كَلَمۡحِ\nT;0;16:77:2:ٱلۡبَصَرِ أَوۡ هُوَ أَقۡرَبُۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءࣲ قَدِيرࣱ\nT;0;16:78:1:وَٱللَّهُ أَخۡرَجَكُم مِّنۢ بُطُونِ أُمَّهَٰتِكُمۡ لَا تَعۡلَمُونَ شَيۡـࣰٔا\nT;0;16:78:0:وَجَعَلَ لَكُمُ ٱلسَّمۡعَ وَٱلۡأَبۡصَٰرَ وَٱلۡأَفۡـِٔدَةَ لَعَلَّكُمۡ\nT;0;16:78:2:تَشۡكُرُونَ¦16:79:1:أَلَمۡ يَرَوۡاْ إِلَى ٱلطَّيۡرِ مُسَخَّرَٰتࣲ فِي جَوِّ ٱلسَّمَآءِ\nT;0;16:79:2:مَا يُمۡسِكُهُنَّ إِلَّا ٱللَّهُۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتࣲ لِّقَوۡمࣲ يُؤۡمِنُونَ',
  '14;28;1;\nT;0;16:80:1:وَٱللَّهُ جَعَلَ لَكُم مِّنۢ بُيُوتِكُمۡ سَكَنࣰا وَجَعَلَ لَكُم مِّن جُلُودِ\nT;0;16:80:0:ٱلۡأَنۡعَٰمِ بُيُوتࣰا تَسۡتَخِفُّونَهَا يَوۡمَ ظَعۡنِكُمۡ وَيَوۡمَ إِقَامَتِكُمۡ\nT;0;16:80:2:وَمِنۡ أَصۡوَافِهَا وَأَوۡبَارِهَا وَأَشۡعَارِهَآ أَثَٰثࣰا وَمَتَٰعًا إِلَىٰ حِينࣲ\nT;0;16:81:1:وَٱللَّهُ جَعَلَ لَكُم مِّمَّا خَلَقَ ظِلَٰلࣰا وَجَعَلَ لَكُم مِّنَ\nT;0;16:81:0:ٱلۡجِبَالِ أَكۡنَٰنࣰا وَجَعَلَ لَكُمۡ سَرَٰبِيلَ تَقِيكُمُ\nT;0;16:81:0:ٱلۡحَرَّ وَسَرَٰبِيلَ تَقِيكُم بَأۡسَكُمۡۚ كَذَٰلِكَ يُتِمُّ نِعۡمَتَهُۥ\nT;0;16:81:2:عَلَيۡكُمۡ لَعَلَّكُمۡ تُسۡلِمُونَ¦16:82:1:فَإِن تَوَلَّوۡاْ فَإِنَّمَا عَلَيۡكَ\nT;0;16:82:2:ٱلۡبَلَٰغُ ٱلۡمُبِينُ¦16:83:1:يَعۡرِفُونَ نِعۡمَتَ ٱللَّهِ ثُمَّ يُنكِرُونَهَا\nT;0;16:83:2:وَأَكۡثَرُهُمُ ٱلۡكَٰفِرُونَ¦16:84:1:وَيَوۡمَ نَبۡعَثُ مِن كُلِّ أُمَّةࣲ\nT;0;16:84:2:شَهِيدࣰا ثُمَّ لَا يُؤۡذَنُ لِلَّذِينَ كَفَرُواْ وَلَا هُمۡ يُسۡتَعۡتَبُونَ\nT;0;16:85:1:وَإِذَا رَءَا ٱلَّذِينَ ظَلَمُواْ ٱلۡعَذَابَ فَلَا يُخَفَّفُ عَنۡهُمۡ وَلَا هُمۡ\nT;0;16:85:2:يُنظَرُونَ¦16:86:1:وَإِذَا رَءَا ٱلَّذِينَ أَشۡرَكُواْ شُرَكَآءَهُمۡ قَالُواْ\nT;0;16:86:0:رَبَّنَا هَٰٓؤُلَآءِ شُرَكَآؤُنَا ٱلَّذِينَ كُنَّا نَدۡعُواْ مِن دُونِكَۖ\nT;0;16:86:2:فَأَلۡقَوۡاْ إِلَيۡهِمُ ٱلۡقَوۡلَ إِنَّكُمۡ لَكَٰذِبُونَ¦16:87:1:وَأَلۡقَوۡاْ إِلَى\nT;0;16:87:2:ٱللَّهِ يَوۡمَئِذٍ ٱلسَّلَمَۖ وَضَلَّ عَنۡهُم مَّا كَانُواْ يَفۡتَرُونَ',
  '14;28;1;111\nT;0;16:88:1:ٱلَّذِينَ كَفَرُواْ وَصَدُّواْ عَن سَبِيلِ ٱللَّهِ زِدۡنَٰهُمۡ عَذَابࣰا\nT;0;16:88:2:فَوۡقَ ٱلۡعَذَابِ بِمَا كَانُواْ يُفۡسِدُونَ¦16:89:1:وَيَوۡمَ نَبۡعَثُ فِي\nT;0;16:89:0:كُلِّ أُمَّةࣲ شَهِيدًا عَلَيۡهِم مِّنۡ أَنفُسِهِمۡۖ وَجِئۡنَا بِكَ\nT;0;16:89:0:شَهِيدًا عَلَىٰ هَٰٓؤُلَآءِۚ وَنَزَّلۡنَا عَلَيۡكَ ٱلۡكِتَٰبَ تِبۡيَٰنࣰا لِّكُلِّ\nT;0;16:89:2:شَيۡءࣲ وَهُدࣰى وَرَحۡمَةࣰ وَبُشۡرَىٰ لِلۡمُسۡلِمِينَ¦16:90:1:۞ إِنَّ ٱللَّهَ\nT;0;16:90:0:يَأۡمُرُ بِٱلۡعَدۡلِ وَٱلۡإِحۡسَٰنِ وَإِيتَآيِٕ ذِي ٱلۡقُرۡبَىٰ وَيَنۡهَىٰ عَنِ\nT;0;16:90:2:ٱلۡفَحۡشَآءِ وَٱلۡمُنكَرِ وَٱلۡبَغۡيِۚ يَعِظُكُمۡ لَعَلَّكُمۡ تَذَكَّرُونَ\nT;0;16:91:1:وَأَوۡفُواْ بِعَهۡدِ ٱللَّهِ إِذَا عَٰهَدتُّمۡ وَلَا تَنقُضُواْ ٱلۡأَيۡمَٰنَ\nT;0;16:91:0:بَعۡدَ تَوۡكِيدِهَا وَقَدۡ جَعَلۡتُمُ ٱللَّهَ عَلَيۡكُمۡ كَفِيلًاۚ إِنَّ\nT;0;16:91:2:ٱللَّهَ يَعۡلَمُ مَا تَفۡعَلُونَ¦16:92:1:وَلَا تَكُونُواْ كَٱلَّتِي نَقَضَتۡ\nT;0;16:92:0:غَزۡلَهَا مِنۢ بَعۡدِ قُوَّةٍ أَنكَٰثࣰا تَتَّخِذُونَ أَيۡمَٰنَكُمۡ دَخَلَۢا\nT;0;16:92:0:بَيۡنَكُمۡ أَن تَكُونَ أُمَّةٌ هِيَ أَرۡبَىٰ مِنۡ أُمَّةٍۚ إِنَّمَا يَبۡلُوكُمُ ٱللَّهُ\nT;0;16:92:2:بِهِۦۚ وَلَيُبَيِّنَنَّ لَكُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ مَا كُنتُمۡ فِيهِ تَخۡتَلِفُونَ\nT;0;16:93:1:وَلَوۡ شَآءَ ٱللَّهُ لَجَعَلَكُمۡ أُمَّةࣰ وَٰحِدَةࣰ وَلَٰكِن يُضِلُّ مَن\nT;0;16:93:2:يَشَآءُ وَيَهۡدِي مَن يَشَآءُۚ وَلَتُسۡـَٔلُنَّ عَمَّا كُنتُمۡ تَعۡمَلُونَ',
  '14;28;2;\nT;0;16:94:1:وَلَا تَتَّخِذُوٓاْ أَيۡمَٰنَكُمۡ دَخَلَۢا بَيۡنَكُمۡ فَتَزِلَّ قَدَمُۢ بَعۡدَ\nT;0;16:94:0:ثُبُوتِهَا وَتَذُوقُواْ ٱلسُّوٓءَ بِمَا صَدَدتُّمۡ عَن سَبِيلِ ٱللَّهِ وَلَكُمۡ\nT;0;16:94:2:عَذَابٌ عَظِيمࣱ¦16:95:1:وَلَا تَشۡتَرُواْ بِعَهۡدِ ٱللَّهِ ثَمَنࣰا قَلِيلًاۚ إِنَّمَا\nT;0;16:95:2:عِندَ ٱللَّهِ هُوَ خَيۡرࣱ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ¦16:96:1:مَا عِندَكُمۡ\nT;0;16:96:0:يَنفَدُ وَمَا عِندَ ٱللَّهِ بَاقࣲۗ وَلَنَجۡزِيَنَّ ٱلَّذِينَ صَبَرُوٓاْ أَجۡرَهُم\nT;0;16:96:2:بِأَحۡسَنِ مَا كَانُواْ يَعۡمَلُونَ¦16:97:1:مَنۡ عَمِلَ صَٰلِحࣰا\nT;0;16:97:0:مِّن ذَكَرٍ أَوۡ أُنثَىٰ وَهُوَ مُؤۡمِنࣱ فَلَنُحۡيِيَنَّهُۥ حَيَوٰةࣰ طَيِّبَةࣰۖ\nT;0;16:97:2:وَلَنَجۡزِيَنَّهُمۡ أَجۡرَهُم بِأَحۡسَنِ مَا كَانُواْ يَعۡمَلُونَ\nT;0;16:98:3:فَإِذَا قَرَأۡتَ ٱلۡقُرۡءَانَ فَٱسۡتَعِذۡ بِٱللَّهِ مِنَ ٱلشَّيۡطَٰنِ ٱلرَّجِيمِ\nT;0;16:99:1:إِنَّهُۥ لَيۡسَ لَهُۥ سُلۡطَٰنٌ عَلَى ٱلَّذِينَ ءَامَنُواْ وَعَلَىٰ رَبِّهِمۡ\nT;0;16:99:2:يَتَوَكَّلُونَ¦16:100:1:إِنَّمَا سُلۡطَٰنُهُۥ عَلَى ٱلَّذِينَ يَتَوَلَّوۡنَهُۥ وَٱلَّذِينَ\nT;0;16:100:2:هُم بِهِۦ مُشۡرِكُونَ¦16:101:1:وَإِذَا بَدَّلۡنَآ ءَايَةࣰ مَّكَانَ ءَايَةࣲ\nT;0;16:101:0:وَٱللَّهُ أَعۡلَمُ بِمَا يُنَزِّلُ قَالُوٓاْ إِنَّمَآ أَنتَ مُفۡتَرِۭۚ بَلۡ أَكۡثَرُهُمۡ\nT;0;16:101:2:لَا يَعۡلَمُونَ¦16:102:1:قُلۡ نَزَّلَهُۥ رُوحُ ٱلۡقُدُسِ مِن رَّبِّكَ بِٱلۡحَقِّ\nT;0;16:102:2:لِيُثَبِّتَ ٱلَّذِينَ ءَامَنُواْ وَهُدࣰى وَبُشۡرَىٰ لِلۡمُسۡلِمِينَ',
  '14;28;2;\nT;0;16:103:1:وَلَقَدۡ نَعۡلَمُ أَنَّهُمۡ يَقُولُونَ إِنَّمَا يُعَلِّمُهُۥ بَشَرࣱۗ لِّسَانُ\nT;0;16:103:2:ٱلَّذِي يُلۡحِدُونَ إِلَيۡهِ أَعۡجَمِيࣱّ وَهَٰذَا لِسَانٌ عَرَبِيࣱّ مُّبِينٌ\nT;0;16:104:1:إِنَّ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِـَٔايَٰتِ ٱللَّهِ لَا يَهۡدِيهِمُ ٱللَّهُ\nT;0;16:104:2:وَلَهُمۡ عَذَابٌ أَلِيمٌ¦16:105:1:إِنَّمَا يَفۡتَرِي ٱلۡكَذِبَ ٱلَّذِينَ\nT;0;16:105:2:لَا يُؤۡمِنُونَ بِـَٔايَٰتِ ٱللَّهِۖ وَأُوْلَٰٓئِكَ هُمُ ٱلۡكَٰذِبُونَ\nT;0;16:106:1:مَن كَفَرَ بِٱللَّهِ مِنۢ بَعۡدِ إِيمَٰنِهِۦٓ إِلَّا مَنۡ أُكۡرِهَ وَقَلۡبُهُۥ\nT;0;16:106:0:مُطۡمَئِنُّۢ بِٱلۡإِيمَٰنِ وَلَٰكِن مَّن شَرَحَ بِٱلۡكُفۡرِ\nT;0;16:106:2:صَدۡرࣰا فَعَلَيۡهِمۡ غَضَبࣱ مِّنَ ٱللَّهِ وَلَهُمۡ عَذَابٌ عَظِيمࣱ\nT;0;16:107:1:ذَٰلِكَ بِأَنَّهُمُ ٱسۡتَحَبُّواْ ٱلۡحَيَوٰةَ ٱلدُّنۡيَا عَلَى\nT;0;16:107:2:ٱلۡأٓخِرَةِ وَأَنَّ ٱللَّهَ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلۡكَٰفِرِينَ\nT;0;16:108:1:أُوْلَٰٓئِكَ ٱلَّذِينَ طَبَعَ ٱللَّهُ عَلَىٰ قُلُوبِهِمۡ وَسَمۡعِهِمۡ\nT;0;16:108:2:وَأَبۡصَٰرِهِمۡۖ وَأُوْلَٰٓئِكَ هُمُ ٱلۡغَٰفِلُونَ¦16:109:1:لَا جَرَمَ\nT;0;16:109:2:أَنَّهُمۡ فِي ٱلۡأٓخِرَةِ هُمُ ٱلۡخَٰسِرُونَ¦16:110:1:ثُمَّ إِنَّ رَبَّكَ\nT;0;16:110:0:لِلَّذِينَ هَاجَرُواْ مِنۢ بَعۡدِ مَا فُتِنُواْ ثُمَّ جَٰهَدُواْ\nT;0;16:110:2:وَصَبَرُوٓاْ إِنَّ رَبَّكَ مِنۢ بَعۡدِهَا لَغَفُورࣱ رَّحِيمࣱ',
  '14;28;3;112\nT;0;16:111:1:۞ يَوۡمَ تَأۡتِي كُلُّ نَفۡسࣲ تُجَٰدِلُ عَن نَّفۡسِهَا وَتُوَفَّىٰ كُلُّ\nT;0;16:111:2:نَفۡسࣲ مَّا عَمِلَتۡ وَهُمۡ لَا يُظۡلَمُونَ¦16:112:1:وَضَرَبَ ٱللَّهُ مَثَلࣰا\nT;0;16:112:0:قَرۡيَةࣰ كَانَتۡ ءَامِنَةࣰ مُّطۡمَئِنَّةࣰ يَأۡتِيهَا رِزۡقُهَا رَغَدࣰا مِّن\nT;0;16:112:0:كُلِّ مَكَانࣲ فَكَفَرَتۡ بِأَنۡعُمِ ٱللَّهِ فَأَذَٰقَهَا ٱللَّهُ لِبَاسَ\nT;0;16:112:2:ٱلۡجُوعِ وَٱلۡخَوۡفِ بِمَا كَانُواْ يَصۡنَعُونَ¦16:113:1:وَلَقَدۡ جَآءَهُمۡ\nT;0;16:113:2:رَسُولࣱ مِّنۡهُمۡ فَكَذَّبُوهُ فَأَخَذَهُمُ ٱلۡعَذَابُ وَهُمۡ ظَٰلِمُونَ\nT;0;16:114:1:فَكُلُواْ مِمَّا رَزَقَكُمُ ٱللَّهُ حَلَٰلࣰا طَيِّبࣰا وَٱشۡكُرُواْ\nT;0;16:114:2:نِعۡمَتَ ٱللَّهِ إِن كُنتُمۡ إِيَّاهُ تَعۡبُدُونَ¦16:115:1:إِنَّمَا حَرَّمَ\nT;0;16:115:0:عَلَيۡكُمُ ٱلۡمَيۡتَةَ وَٱلدَّمَ وَلَحۡمَ ٱلۡخِنزِيرِ وَمَآ أُهِلَّ لِغَيۡرِ\nT;0;16:115:0:ٱللَّهِ بِهِۦۖ فَمَنِ ٱضۡطُرَّ غَيۡرَ بَاغࣲ وَلَا عَادࣲ فَإِنَّ ٱللَّهَ غَفُورࣱ\nT;0;16:115:2:رَّحِيمࣱ¦16:116:1:وَلَا تَقُولُواْ لِمَا تَصِفُ أَلۡسِنَتُكُمُ ٱلۡكَذِبَ\nT;0;16:116:0:هَٰذَا حَلَٰلࣱ وَهَٰذَا حَرَامࣱ لِّتَفۡتَرُواْ عَلَى ٱللَّهِ ٱلۡكَذِبَۚ إِنَّ\nT;0;16:116:2:ٱلَّذِينَ يَفۡتَرُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَ لَا يُفۡلِحُونَ¦16:117:1:مَتَٰعࣱ قَلِيلࣱ\nT;0;16:117:2:وَلَهُمۡ عَذَابٌ أَلِيمࣱ¦16:118:1:وَعَلَى ٱلَّذِينَ هَادُواْ حَرَّمۡنَا مَا قَصَصۡنَا عَلَيۡكَ\nT;0;16:118:2:مِن قَبۡلُۖ وَمَا ظَلَمۡنَٰهُمۡ وَلَٰكِن كَانُوٓاْ أَنفُسَهُمۡ يَظۡلِمُونَ',
  '14;28;3;\nT;0;16:119:1:ثُمَّ إِنَّ رَبَّكَ لِلَّذِينَ عَمِلُواْ ٱلسُّوٓءَ بِجَهَٰلَةࣲ ثُمَّ تَابُواْ مِنۢ بَعۡدِ\nT;0;16:119:2:ذَٰلِكَ وَأَصۡلَحُوٓاْ إِنَّ رَبَّكَ مِنۢ بَعۡدِهَا لَغَفُورࣱ رَّحِيمٌ¦16:120:1:إِنَّ\nT;0;16:120:2:إِبۡرَٰهِيمَ كَانَ أُمَّةࣰ قَانِتࣰا لِّلَّهِ حَنِيفࣰا وَلَمۡ يَكُ مِنَ ٱلۡمُشۡرِكِينَ\nT;0;16:121:3:شَاكِرࣰا لِّأَنۡعُمِهِۚ ٱجۡتَبَىٰهُ وَهَدَىٰهُ إِلَىٰ صِرَٰطࣲ مُّسۡتَقِيمࣲ\nT;0;16:122:3:وَءَاتَيۡنَٰهُ فِي ٱلدُّنۡيَا حَسَنَةࣰۖ وَإِنَّهُۥ فِي ٱلۡأٓخِرَةِ لَمِنَ ٱلصَّٰلِحِينَ\nT;0;16:123:1:ثُمَّ أَوۡحَيۡنَآ إِلَيۡكَ أَنِ ٱتَّبِعۡ مِلَّةَ إِبۡرَٰهِيمَ حَنِيفࣰاۖ وَمَا كَانَ\nT;0;16:123:2:مِنَ ٱلۡمُشۡرِكِينَ¦16:124:1:إِنَّمَا جُعِلَ ٱلسَّبۡتُ عَلَى ٱلَّذِينَ ٱخۡتَلَفُواْ\nT;0;16:124:0:فِيهِۚ وَإِنَّ رَبَّكَ لَيَحۡكُمُ بَيۡنَهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ فِيمَا\nT;0;16:124:2:كَانُواْ فِيهِ يَخۡتَلِفُونَ¦16:125:1:ٱدۡعُ إِلَىٰ سَبِيلِ رَبِّكَ بِٱلۡحِكۡمَةِ\nT;0;16:125:0:وَٱلۡمَوۡعِظَةِ ٱلۡحَسَنَةِۖ وَجَٰدِلۡهُم بِٱلَّتِي هِيَ أَحۡسَنُۚ إِنَّ رَبَّكَ\nT;0;16:125:2:هُوَ أَعۡلَمُ بِمَن ضَلَّ عَن سَبِيلِهِۦ وَهُوَ أَعۡلَمُ بِٱلۡمُهۡتَدِينَ\nT;0;16:126:1:وَإِنۡ عَاقَبۡتُمۡ فَعَاقِبُواْ بِمِثۡلِ مَا عُوقِبۡتُم بِهِۦۖ وَلَئِن\nT;0;16:126:2:صَبَرۡتُمۡ لَهُوَ خَيۡرࣱ لِّلصَّٰبِرِينَ¦16:127:1:وَٱصۡبِرۡ وَمَا صَبۡرُكَ\nT;0;16:127:2:إِلَّا بِٱللَّهِۚ وَلَا تَحۡزَنۡ عَلَيۡهِمۡ وَلَا تَكُ فِي ضَيۡقࣲ مِّمَّا يَمۡكُرُونَ\nT;2;16:128:3:إِنَّ ٱللَّهَ مَعَ ٱلَّذِينَ ٱتَّقَواْ وَّٱلَّذِينَ هُم مُّحۡسِنُونَ',
  '15;29;0;113\nH;17\nB;17\nT;0;17:1:1:سُبۡحَٰنَ ٱلَّذِيٓ أَسۡرَىٰ بِعَبۡدِهِۦ لَيۡلࣰا مِّنَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ إِلَى\nT;0;17:1:0:ٱلۡمَسۡجِدِ ٱلۡأَقۡصَا ٱلَّذِي بَٰرَكۡنَا حَوۡلَهُۥ لِنُرِيَهُۥ مِنۡ ءَايَٰتِنَآۚ إِنَّهُۥ\nT;0;17:1:2:هُوَ ٱلسَّمِيعُ ٱلۡبَصِيرُ¦17:2:1:وَءَاتَيۡنَا مُوسَى ٱلۡكِتَٰبَ وَجَعَلۡنَٰهُ\nT;0;17:2:2:هُدࣰى لِّبَنِيٓ إِسۡرَٰٓءِيلَ أَلَّا تَتَّخِذُواْ مِن دُونِي وَكِيلࣰا\nT;0;17:3:3:ذُرِّيَّةَ مَنۡ حَمَلۡنَا مَعَ نُوحٍۚ إِنَّهُۥ كَانَ عَبۡدࣰا شَكُورࣰا\nT;0;17:4:1:وَقَضَيۡنَآ إِلَىٰ بَنِيٓ إِسۡرَٰٓءِيلَ فِي ٱلۡكِتَٰبِ لَتُفۡسِدُنَّ فِي ٱلۡأَرۡضِ\nT;0;17:4:2:مَرَّتَيۡنِ وَلَتَعۡلُنَّ عُلُوࣰّا كَبِيرࣰا¦17:5:1:فَإِذَا جَآءَ وَعۡدُ أُولَىٰهُمَا\nT;0;17:5:0:بَعَثۡنَا عَلَيۡكُمۡ عِبَادࣰا لَّنَآ أُوْلِي بَأۡسࣲ شَدِيدࣲ فَجَاسُواْ خِلَٰلَ\nT;0;17:5:2:ٱلدِّيَارِۚ وَكَانَ وَعۡدࣰا مَّفۡعُولࣰا¦17:6:1:ثُمَّ رَدَدۡنَا لَكُمُ ٱلۡكَرَّةَ\nT;0;17:6:2:عَلَيۡهِمۡ وَأَمۡدَدۡنَٰكُم بِأَمۡوَٰلࣲ وَبَنِينَ وَجَعَلۡنَٰكُمۡ أَكۡثَرَ نَفِيرًا\nT;0;17:7:1:إِنۡ أَحۡسَنتُمۡ أَحۡسَنتُمۡ لِأَنفُسِكُمۡۖ وَإِنۡ أَسَأۡتُمۡ فَلَهَاۚ فَإِذَا\nT;0;17:7:0:جَآءَ وَعۡدُ ٱلۡأٓخِرَةِ لِيَسُـُٔواْ وُجُوهَكُمۡ وَلِيَدۡخُلُواْ ٱلۡمَسۡجِدَ\nT;0;17:7:2:كَمَا دَخَلُوهُ أَوَّلَ مَرَّةࣲ وَلِيُتَبِّرُواْ مَا عَلَوۡاْ تَتۡبِيرًا',
  '15;29;0;\nT;0;17:8:1:عَسَىٰ رَبُّكُمۡ أَن يَرۡحَمَكُمۡۚ وَإِنۡ عُدتُّمۡ عُدۡنَاۚ وَجَعَلۡنَا جَهَنَّمَ لِلۡكَٰفِرِينَ\nT;0;17:8:2:حَصِيرًا¦17:9:1:إِنَّ هَٰذَا ٱلۡقُرۡءَانَ يَهۡدِي لِلَّتِي هِيَ أَقۡوَمُ وَيُبَشِّرُ\nT;0;17:9:2:ٱلۡمُؤۡمِنِينَ ٱلَّذِينَ يَعۡمَلُونَ ٱلصَّٰلِحَٰتِ أَنَّ لَهُمۡ أَجۡرࣰا كَبِيرࣰا\nT;0;17:10:3:وَأَنَّ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ أَعۡتَدۡنَا لَهُمۡ عَذَابًا أَلِيمࣰا\nT;0;17:11:3:وَيَدۡعُ ٱلۡإِنسَٰنُ بِٱلشَّرِّ دُعَآءَهُۥ بِٱلۡخَيۡرِۖ وَكَانَ ٱلۡإِنسَٰنُ عَجُولࣰا\nT;0;17:12:1:وَجَعَلۡنَا ٱلَّيۡلَ وَٱلنَّهَارَ ءَايَتَيۡنِۖ فَمَحَوۡنَآ ءَايَةَ ٱلَّيۡلِ وَجَعَلۡنَآ ءَايَةَ\nT;0;17:12:0:ٱلنَّهَارِ مُبۡصِرَةࣰ لِّتَبۡتَغُواْ فَضۡلࣰا مِّن رَّبِّكُمۡ وَلِتَعۡلَمُواْ عَدَدَ\nT;0;17:12:2:ٱلسِّنِينَ وَٱلۡحِسَابَۚ وَكُلَّ شَيۡءࣲ فَصَّلۡنَٰهُ تَفۡصِيلࣰا¦17:13:1:وَكُلَّ إِنسَٰنٍ\nT;0;17:13:0:أَلۡزَمۡنَٰهُ طَٰٓئِرَهُۥ فِي عُنُقِهِۦۖ وَنُخۡرِجُ لَهُۥ يَوۡمَ ٱلۡقِيَٰمَةِ كِتَٰبࣰا يَلۡقَىٰهُ\nT;0;17:13:2:مَنشُورًا¦17:14:3:ٱقۡرَأۡ كِتَٰبَكَ كَفَىٰ بِنَفۡسِكَ ٱلۡيَوۡمَ عَلَيۡكَ حَسِيبࣰا\nT;0;17:15:1:مَّنِ ٱهۡتَدَىٰ فَإِنَّمَا يَهۡتَدِي لِنَفۡسِهِۦۖ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ\nT;0;17:15:0:عَلَيۡهَاۚ وَلَا تَزِرُ وَازِرَةࣱ وِزۡرَ أُخۡرَىٰۗ وَمَا كُنَّا مُعَذِّبِينَ حَتَّىٰ نَبۡعَثَ\nT;0;17:15:2:رَسُولࣰا¦17:16:1:وَإِذَآ أَرَدۡنَآ أَن نُّهۡلِكَ قَرۡيَةً أَمَرۡنَا مُتۡرَفِيهَا فَفَسَقُواْ فِيهَا\nT;0;17:16:2:فَحَقَّ عَلَيۡهَا ٱلۡقَوۡلُ فَدَمَّرۡنَٰهَا تَدۡمِيرࣰا¦17:17:1:وَكَمۡ أَهۡلَكۡنَا مِنَ ٱلۡقُرُونِ\nT;0;17:17:2:مِنۢ بَعۡدِ نُوحࣲۗ وَكَفَىٰ بِرَبِّكَ بِذُنُوبِ عِبَادِهِۦ خَبِيرَۢا بَصِيرࣰا',
  '15;29;0;114\nT;0;17:18:1:مَّن كَانَ يُرِيدُ ٱلۡعَاجِلَةَ عَجَّلۡنَا لَهُۥ فِيهَا مَا نَشَآءُ لِمَن نُّرِيدُ ثُمَّ\nT;0;17:18:2:جَعَلۡنَا لَهُۥ جَهَنَّمَ يَصۡلَىٰهَا مَذۡمُومࣰا مَّدۡحُورࣰا¦17:19:1:وَمَنۡ أَرَادَ\nT;0;17:19:0:ٱلۡأٓخِرَةَ وَسَعَىٰ لَهَا سَعۡيَهَا وَهُوَ مُؤۡمِنࣱ فَأُوْلَٰٓئِكَ كَانَ\nT;0;17:19:2:سَعۡيُهُم مَّشۡكُورࣰا¦17:20:1:كُلࣰّا نُّمِدُّ هَٰٓؤُلَآءِ وَهَٰٓؤُلَآءِ مِنۡ\nT;0;17:20:2:عَطَآءِ رَبِّكَۚ وَمَا كَانَ عَطَآءُ رَبِّكَ مَحۡظُورًا¦17:21:1:ٱنظُرۡ كَيۡفَ\nT;0;17:21:0:فَضَّلۡنَا بَعۡضَهُمۡ عَلَىٰ بَعۡضࣲۚ وَلَلۡأٓخِرَةُ أَكۡبَرُ دَرَجَٰتࣲ وَأَكۡبَرُ\nT;0;17:21:2:تَفۡضِيلࣰا¦17:22:1:لَّا تَجۡعَلۡ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ فَتَقۡعُدَ مَذۡمُومࣰا\nT;0;17:22:2:مَّخۡذُولࣰا¦17:23:1:۞ وَقَضَىٰ رَبُّكَ أَلَّا تَعۡبُدُوٓاْ إِلَّآ إِيَّاهُ وَبِٱلۡوَٰلِدَيۡنِ إِحۡسَٰنًاۚ\nT;0;17:23:0:إِمَّا يَبۡلُغَنَّ عِندَكَ ٱلۡكِبَرَ أَحَدُهُمَآ أَوۡ كِلَاهُمَا فَلَا تَقُل لَّهُمَآ\nT;0;17:23:2:أُفࣲّ وَلَا تَنۡهَرۡهُمَا وَقُل لَّهُمَا قَوۡلࣰا كَرِيمࣰا¦17:24:1:وَٱخۡفِضۡ لَهُمَا\nT;0;17:24:0:جَنَاحَ ٱلذُّلِّ مِنَ ٱلرَّحۡمَةِ وَقُل رَّبِّ ٱرۡحَمۡهُمَا كَمَا رَبَّيَانِي\nT;0;17:24:2:صَغِيرࣰا¦17:25:1:رَّبُّكُمۡ أَعۡلَمُ بِمَا فِي نُفُوسِكُمۡۚ إِن تَكُونُواْ صَٰلِحِينَ\nT;0;17:25:2:فَإِنَّهُۥ كَانَ لِلۡأَوَّٰبِينَ غَفُورࣰا¦17:26:1:وَءَاتِ ذَا ٱلۡقُرۡبَىٰ حَقَّهُۥ\nT;0;17:26:2:وَٱلۡمِسۡكِينَ وَٱبۡنَ ٱلسَّبِيلِ وَلَا تُبَذِّرۡ تَبۡذِيرًا¦17:27:1:إِنَّ ٱلۡمُبَذِّرِينَ\nT;0;17:27:2:كَانُوٓاْ إِخۡوَٰنَ ٱلشَّيَٰطِينِۖ وَكَانَ ٱلشَّيۡطَٰنُ لِرَبِّهِۦ كَفُورࣰا',
  '15;29;1;\nT;0;17:28:1:وَإِمَّا تُعۡرِضَنَّ عَنۡهُمُ ٱبۡتِغَآءَ رَحۡمَةࣲ مِّن رَّبِّكَ تَرۡجُوهَا فَقُل لَّهُمۡ قَوۡلࣰا\nT;0;17:28:2:مَّيۡسُورࣰا¦17:29:1:وَلَا تَجۡعَلۡ يَدَكَ مَغۡلُولَةً إِلَىٰ عُنُقِكَ وَلَا تَبۡسُطۡهَا\nT;0;17:29:2:كُلَّ ٱلۡبَسۡطِ فَتَقۡعُدَ مَلُومࣰا مَّحۡسُورًا¦17:30:1:إِنَّ رَبَّكَ يَبۡسُطُ ٱلرِّزۡقَ\nT;0;17:30:2:لِمَن يَشَآءُ وَيَقۡدِرُۚ إِنَّهُۥ كَانَ بِعِبَادِهِۦ خَبِيرَۢا بَصِيرࣰا¦17:31:1:وَلَا تَقۡتُلُوٓاْ\nT;0;17:31:0:أَوۡلَٰدَكُمۡ خَشۡيَةَ إِمۡلَٰقࣲۖ نَّحۡنُ نَرۡزُقُهُمۡ وَإِيَّاكُمۡۚ إِنَّ قَتۡلَهُمۡ كَانَ\nT;0;17:31:2:خِطۡـࣰٔا كَبِيرࣰا¦17:32:1:وَلَا تَقۡرَبُواْ ٱلزِّنَىٰٓۖ إِنَّهُۥ كَانَ فَٰحِشَةࣰ وَسَآءَ\nT;0;17:32:2:سَبِيلࣰا¦17:33:1:وَلَا تَقۡتُلُواْ ٱلنَّفۡسَ ٱلَّتِي حَرَّمَ ٱللَّهُ إِلَّا بِٱلۡحَقِّۗ\nT;0;17:33:0:وَمَن قُتِلَ مَظۡلُومࣰا فَقَدۡ جَعَلۡنَا لِوَلِيِّهِۦ سُلۡطَٰنࣰا فَلَا يُسۡرِف فِّي\nT;0;17:33:2:ٱلۡقَتۡلِۖ إِنَّهُۥ كَانَ مَنصُورࣰا¦17:34:1:وَلَا تَقۡرَبُواْ مَالَ ٱلۡيَتِيمِ إِلَّا بِٱلَّتِي\nT;0;17:34:0:هِيَ أَحۡسَنُ حَتَّىٰ يَبۡلُغَ أَشُدَّهُۥۚ وَأَوۡفُواْ بِٱلۡعَهۡدِۖ إِنَّ ٱلۡعَهۡدَ كَانَ\nT;0;17:34:2:مَسۡـُٔولࣰا¦17:35:1:وَأَوۡفُواْ ٱلۡكَيۡلَ إِذَا كِلۡتُمۡ وَزِنُواْ بِٱلۡقِسۡطَاسِ ٱلۡمُسۡتَقِيمِۚ\nT;0;17:35:2:ذَٰلِكَ خَيۡرࣱ وَأَحۡسَنُ تَأۡوِيلࣰا¦17:36:1:وَلَا تَقۡفُ مَا لَيۡسَ لَكَ بِهِۦ عِلۡمٌۚ إِنَّ\nT;0;17:36:2:ٱلسَّمۡعَ وَٱلۡبَصَرَ وَٱلۡفُؤَادَ كُلُّ أُوْلَٰٓئِكَ كَانَ عَنۡهُ مَسۡـُٔولࣰا\nT;0;17:37:1:وَلَا تَمۡشِ فِي ٱلۡأَرۡضِ مَرَحًاۖ إِنَّكَ لَن تَخۡرِقَ ٱلۡأَرۡضَ وَلَن تَبۡلُغَ\nT;0;17:37:2:ٱلۡجِبَالَ طُولࣰا¦17:38:3:كُلُّ ذَٰلِكَ كَانَ سَيِّئُهُۥ عِندَ رَبِّكَ مَكۡرُوهࣰا',
  '15;29;1;\nT;0;17:39:1:ذَٰلِكَ مِمَّآ أَوۡحَىٰٓ إِلَيۡكَ رَبُّكَ مِنَ ٱلۡحِكۡمَةِۗ وَلَا تَجۡعَلۡ مَعَ ٱللَّهِ إِلَٰهًا\nT;0;17:39:2:ءَاخَرَ فَتُلۡقَىٰ فِي جَهَنَّمَ مَلُومࣰا مَّدۡحُورًا¦17:40:1:أَفَأَصۡفَىٰكُمۡ رَبُّكُم\nT;0;17:40:2:بِٱلۡبَنِينَ وَٱتَّخَذَ مِنَ ٱلۡمَلَٰٓئِكَةِ إِنَٰثًاۚ إِنَّكُمۡ لَتَقُولُونَ قَوۡلًا عَظِيمࣰا\nT;0;17:41:3:وَلَقَدۡ صَرَّفۡنَا فِي هَٰذَا ٱلۡقُرۡءَانِ لِيَذَّكَّرُواْ وَمَا يَزِيدُهُمۡ إِلَّا نُفُورࣰا\nT;0;17:42:3:قُل لَّوۡ كَانَ مَعَهُۥٓ ءَالِهَةࣱ كَمَا يَقُولُونَ إِذࣰا لَّٱبۡتَغَوۡاْ إِلَىٰ ذِي ٱلۡعَرۡشِ سَبِيلࣰا\nT;0;17:43:3:سُبۡحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا يَقُولُونَ عُلُوࣰّا كَبِيرࣰا¦17:44:1:تُسَبِّحُ لَهُ ٱلسَّمَٰوَٰتُ\nT;0;17:44:0:ٱلسَّبۡعُ وَٱلۡأَرۡضُ وَمَن فِيهِنَّۚ وَإِن مِّن شَيۡءٍ إِلَّا يُسَبِّحُ بِحَمۡدِهِۦ وَلَٰكِن\nT;0;17:44:2:لَّا تَفۡقَهُونَ تَسۡبِيحَهُمۡۚ إِنَّهُۥ كَانَ حَلِيمًا غَفُورࣰا¦17:45:1:وَإِذَا قَرَأۡتَ\nT;0;17:45:0:ٱلۡقُرۡءَانَ جَعَلۡنَا بَيۡنَكَ وَبَيۡنَ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ حِجَابࣰا\nT;0;17:45:2:مَّسۡتُورࣰا¦17:46:1:وَجَعَلۡنَا عَلَىٰ قُلُوبِهِمۡ أَكِنَّةً أَن يَفۡقَهُوهُ وَفِيٓ ءَاذَانِهِمۡ\nT;0;17:46:2:وَقۡرࣰاۚ وَإِذَا ذَكَرۡتَ رَبَّكَ فِي ٱلۡقُرۡءَانِ وَحۡدَهُۥ وَلَّوۡاْ عَلَىٰٓ أَدۡبَٰرِهِمۡ نُفُورࣰا\nT;0;17:47:1:نَّحۡنُ أَعۡلَمُ بِمَا يَسۡتَمِعُونَ بِهِۦٓ إِذۡ يَسۡتَمِعُونَ إِلَيۡكَ وَإِذۡ هُمۡ نَجۡوَىٰٓ\nT;0;17:47:2:إِذۡ يَقُولُ ٱلظَّٰلِمُونَ إِن تَتَّبِعُونَ إِلَّا رَجُلࣰا مَّسۡحُورًا¦17:48:1:ٱنظُرۡ\nT;0;17:48:2:كَيۡفَ ضَرَبُواْ لَكَ ٱلۡأَمۡثَالَ فَضَلُّواْ فَلَا يَسۡتَطِيعُونَ سَبِيلࣰا\nT;0;17:49:3:وَقَالُوٓاْ أَءِذَا كُنَّا عِظَٰمࣰا وَرُفَٰتًا أَءِنَّا لَمَبۡعُوثُونَ خَلۡقࣰا جَدِيدࣰا',
  '15;29;2;115\nT;0;17:50:3:۞ قُلۡ كُونُواْ حِجَارَةً أَوۡ حَدِيدًا¦17:51:1:أَوۡ خَلۡقࣰا مِّمَّا يَكۡبُرُ فِي\nT;0;17:51:0:صُدُورِكُمۡۚ فَسَيَقُولُونَ مَن يُعِيدُنَاۖ قُلِ ٱلَّذِي فَطَرَكُمۡ أَوَّلَ مَرَّةࣲۚ\nT;0;17:51:0:فَسَيُنۡغِضُونَ إِلَيۡكَ رُءُوسَهُمۡ وَيَقُولُونَ مَتَىٰ هُوَۖ قُلۡ عَسَىٰٓ أَن\nT;0;17:51:2:يَكُونَ قَرِيبࣰا¦17:52:1:يَوۡمَ يَدۡعُوكُمۡ فَتَسۡتَجِيبُونَ بِحَمۡدِهِۦ وَتَظُنُّونَ\nT;0;17:52:2:إِن لَّبِثۡتُمۡ إِلَّا قَلِيلࣰا¦17:53:1:وَقُل لِّعِبَادِي يَقُولُواْ ٱلَّتِي هِيَ أَحۡسَنُۚ\nT;0;17:53:0:إِنَّ ٱلشَّيۡطَٰنَ يَنزَغُ بَيۡنَهُمۡۚ إِنَّ ٱلشَّيۡطَٰنَ كَانَ لِلۡإِنسَٰنِ عَدُوࣰّا\nT;0;17:53:2:مُّبِينࣰا¦17:54:1:رَّبُّكُمۡ أَعۡلَمُ بِكُمۡۖ إِن يَشَأۡ يَرۡحَمۡكُمۡ أَوۡ إِن يَشَأۡ\nT;0;17:54:2:يُعَذِّبۡكُمۡۚ وَمَآ أَرۡسَلۡنَٰكَ عَلَيۡهِمۡ وَكِيلࣰا¦17:55:1:وَرَبُّكَ أَعۡلَمُ\nT;0;17:55:0:بِمَن فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۗ وَلَقَدۡ فَضَّلۡنَا بَعۡضَ ٱلنَّبِيِّـۧنَ عَلَىٰ\nT;0;17:55:2:بَعۡضࣲۖ وَءَاتَيۡنَا دَاوُۥدَ زَبُورࣰا¦17:56:1:قُلِ ٱدۡعُواْ ٱلَّذِينَ زَعَمۡتُم مِّن\nT;0;17:56:2:دُونِهِۦ فَلَا يَمۡلِكُونَ كَشۡفَ ٱلضُّرِّ عَنكُمۡ وَلَا تَحۡوِيلًا¦17:57:1:أُوْلَٰٓئِكَ\nT;0;17:57:0:ٱلَّذِينَ يَدۡعُونَ يَبۡتَغُونَ إِلَىٰ رَبِّهِمُ ٱلۡوَسِيلَةَ أَيُّهُمۡ أَقۡرَبُ\nT;0;17:57:0:وَيَرۡجُونَ رَحۡمَتَهُۥ وَيَخَافُونَ عَذَابَهُۥٓۚ إِنَّ عَذَابَ رَبِّكَ كَانَ\nT;0;17:57:2:مَحۡذُورࣰا¦17:58:1:وَإِن مِّن قَرۡيَةٍ إِلَّا نَحۡنُ مُهۡلِكُوهَا قَبۡلَ يَوۡمِ ٱلۡقِيَٰمَةِ\nT;0;17:58:2:أَوۡ مُعَذِّبُوهَا عَذَابࣰا شَدِيدࣰاۚ كَانَ ذَٰلِكَ فِي ٱلۡكِتَٰبِ مَسۡطُورࣰا',
  '15;29;2;\nT;0;17:59:1:وَمَا مَنَعَنَآ أَن نُّرۡسِلَ بِٱلۡأٓيَٰتِ إِلَّآ أَن كَذَّبَ بِهَا ٱلۡأَوَّلُونَۚ\nT;0;17:59:0:وَءَاتَيۡنَا ثَمُودَ ٱلنَّاقَةَ مُبۡصِرَةࣰ فَظَلَمُواْ بِهَاۚ وَمَا نُرۡسِلُ بِٱلۡأٓيَٰتِ\nT;0;17:59:2:إِلَّا تَخۡوِيفࣰا¦17:60:1:وَإِذۡ قُلۡنَا لَكَ إِنَّ رَبَّكَ أَحَاطَ بِٱلنَّاسِۚ وَمَا جَعَلۡنَا\nT;0;17:60:0:ٱلرُّءۡيَا ٱلَّتِيٓ أَرَيۡنَٰكَ إِلَّا فِتۡنَةࣰ لِّلنَّاسِ وَٱلشَّجَرَةَ ٱلۡمَلۡعُونَةَ\nT;0;17:60:2:فِي ٱلۡقُرۡءَانِۚ وَنُخَوِّفُهُمۡ فَمَا يَزِيدُهُمۡ إِلَّا طُغۡيَٰنࣰا كَبِيرࣰا\nT;0;17:61:1:وَإِذۡ قُلۡنَا لِلۡمَلَٰٓئِكَةِ ٱسۡجُدُواْ لِأٓدَمَ فَسَجَدُوٓاْ إِلَّآ إِبۡلِيسَ\nT;0;17:61:2:قَالَ ءَأَسۡجُدُ لِمَنۡ خَلَقۡتَ طِينࣰا¦17:62:1:قَالَ أَرَءَيۡتَكَ هَٰذَا ٱلَّذِي\nT;0;17:62:0:كَرَّمۡتَ عَلَيَّ لَئِنۡ أَخَّرۡتَنِ إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِ لَأَحۡتَنِكَنَّ\nT;0;17:62:2:ذُرِّيَّتَهُۥٓ إِلَّا قَلِيلࣰا¦17:63:1:قَالَ ٱذۡهَبۡ فَمَن تَبِعَكَ مِنۡهُمۡ فَإِنَّ\nT;0;17:63:2:جَهَنَّمَ جَزَآؤُكُمۡ جَزَآءࣰ مَّوۡفُورࣰا¦17:64:1:وَٱسۡتَفۡزِزۡ مَنِ ٱسۡتَطَعۡتَ\nT;0;17:64:0:مِنۡهُم بِصَوۡتِكَ وَأَجۡلِبۡ عَلَيۡهِم بِخَيۡلِكَ وَرَجِلِكَ وَشَارِكۡهُمۡ\nT;0;17:64:0:فِي ٱلۡأَمۡوَٰلِ وَٱلۡأَوۡلَٰدِ وَعِدۡهُمۡۚ وَمَا يَعِدُهُمُ ٱلشَّيۡطَٰنُ إِلَّا\nT;0;17:64:2:غُرُورًا¦17:65:1:إِنَّ عِبَادِي لَيۡسَ لَكَ عَلَيۡهِمۡ سُلۡطَٰنࣱۚ وَكَفَىٰ\nT;0;17:65:2:بِرَبِّكَ وَكِيلࣰا¦17:66:1:رَّبُّكُمُ ٱلَّذِي يُزۡجِي لَكُمُ ٱلۡفُلۡكَ فِي\nT;0;17:66:2:ٱلۡبَحۡرِ لِتَبۡتَغُواْ مِن فَضۡلِهِۦٓۚ إِنَّهُۥ كَانَ بِكُمۡ رَحِيمࣰا',
  '15;29;2;116\nT;0;17:67:1:وَإِذَا مَسَّكُمُ ٱلضُّرُّ فِي ٱلۡبَحۡرِ ضَلَّ مَن تَدۡعُونَ إِلَّآ إِيَّاهُۖ فَلَمَّا\nT;0;17:67:2:نَجَّىٰكُمۡ إِلَى ٱلۡبَرِّ أَعۡرَضۡتُمۡۚ وَكَانَ ٱلۡإِنسَٰنُ كَفُورًا¦17:68:1:أَفَأَمِنتُمۡ\nT;0;17:68:0:أَن يَخۡسِفَ بِكُمۡ جَانِبَ ٱلۡبَرِّ أَوۡ يُرۡسِلَ عَلَيۡكُمۡ حَاصِبࣰا ثُمَّ\nT;0;17:68:2:لَا تَجِدُواْ لَكُمۡ وَكِيلًا¦17:69:1:أَمۡ أَمِنتُمۡ أَن يُعِيدَكُمۡ فِيهِ تَارَةً\nT;0;17:69:0:أُخۡرَىٰ فَيُرۡسِلَ عَلَيۡكُمۡ قَاصِفࣰا مِّنَ ٱلرِّيحِ فَيُغۡرِقَكُم بِمَا كَفَرۡتُمۡ\nT;0;17:69:2:ثُمَّ لَا تَجِدُواْ لَكُمۡ عَلَيۡنَا بِهِۦ تَبِيعࣰا¦17:70:1:۞ وَلَقَدۡ كَرَّمۡنَا بَنِيٓ\nT;0;17:70:0:ءَادَمَ وَحَمَلۡنَٰهُمۡ فِي ٱلۡبَرِّ وَٱلۡبَحۡرِ وَرَزَقۡنَٰهُم مِّنَ ٱلطَّيِّبَٰتِ\nT;0;17:70:2:وَفَضَّلۡنَٰهُمۡ عَلَىٰ كَثِيرࣲ مِّمَّنۡ خَلَقۡنَا تَفۡضِيلࣰا¦17:71:1:يَوۡمَ نَدۡعُواْ\nT;0;17:71:0:كُلَّ أُنَاسِۭ بِإِمَٰمِهِمۡۖ فَمَنۡ أُوتِيَ كِتَٰبَهُۥ بِيَمِينِهِۦ فَأُوْلَٰٓئِكَ\nT;0;17:71:2:يَقۡرَءُونَ كِتَٰبَهُمۡ وَلَا يُظۡلَمُونَ فَتِيلࣰا¦17:72:1:وَمَن كَانَ\nT;0;17:72:2:فِي هَٰذِهِۦٓ أَعۡمَىٰ فَهُوَ فِي ٱلۡأٓخِرَةِ أَعۡمَىٰ وَأَضَلُّ سَبِيلࣰا¦17:73:1:وَإِن\nT;0;17:73:0:كَادُواْ لَيَفۡتِنُونَكَ عَنِ ٱلَّذِيٓ أَوۡحَيۡنَآ إِلَيۡكَ لِتَفۡتَرِيَ\nT;0;17:73:2:عَلَيۡنَا غَيۡرَهُۥۖ وَإِذࣰا لَّٱتَّخَذُوكَ خَلِيلࣰا¦17:74:1:وَلَوۡلَآ أَن ثَبَّتۡنَٰكَ\nT;0;17:74:2:لَقَدۡ كِدتَّ تَرۡكَنُ إِلَيۡهِمۡ شَيۡـࣰٔا قَلِيلًا¦17:75:1:إِذࣰا لَّأَذَقۡنَٰكَ ضِعۡفَ\nT;0;17:75:2:ٱلۡحَيَوٰةِ وَضِعۡفَ ٱلۡمَمَاتِ ثُمَّ لَا تَجِدُ لَكَ عَلَيۡنَا نَصِيرࣰا',
  '15;29;3;\nT;0;17:76:1:وَإِن كَادُواْ لَيَسۡتَفِزُّونَكَ مِنَ ٱلۡأَرۡضِ لِيُخۡرِجُوكَ مِنۡهَاۖ\nT;0;17:76:2:وَإِذࣰا لَّا يَلۡبَثُونَ خِلَٰفَكَ إِلَّا قَلِيلࣰا¦17:77:1:سُنَّةَ مَن قَدۡ أَرۡسَلۡنَا\nT;0;17:77:2:قَبۡلَكَ مِن رُّسُلِنَاۖ وَلَا تَجِدُ لِسُنَّتِنَا تَحۡوِيلًا¦17:78:1:أَقِمِ\nT;0;17:78:0:ٱلصَّلَوٰةَ لِدُلُوكِ ٱلشَّمۡسِ إِلَىٰ غَسَقِ ٱلَّيۡلِ وَقُرۡءَانَ ٱلۡفَجۡرِۖ\nT;0;17:78:2:إِنَّ قُرۡءَانَ ٱلۡفَجۡرِ كَانَ مَشۡهُودࣰا¦17:79:1:وَمِنَ ٱلَّيۡلِ فَتَهَجَّدۡ\nT;0;17:79:2:بِهِۦ نَافِلَةࣰ لَّكَ عَسَىٰٓ أَن يَبۡعَثَكَ رَبُّكَ مَقَامࣰا مَّحۡمُودࣰا\nT;0;17:80:1:وَقُل رَّبِّ أَدۡخِلۡنِي مُدۡخَلَ صِدۡقࣲ وَأَخۡرِجۡنِي مُخۡرَجَ صِدۡقࣲ\nT;0;17:80:2:وَٱجۡعَل لِّي مِن لَّدُنكَ سُلۡطَٰنࣰا نَّصِيرࣰا¦17:81:1:وَقُلۡ جَآءَ ٱلۡحَقُّ وَزَهَقَ\nT;0;17:81:2:ٱلۡبَٰطِلُۚ إِنَّ ٱلۡبَٰطِلَ كَانَ زَهُوقࣰا¦17:82:1:وَنُنَزِّلُ مِنَ ٱلۡقُرۡءَانِ مَا هُوَ\nT;0;17:82:2:شِفَآءࣱ وَرَحۡمَةࣱ لِّلۡمُؤۡمِنِينَ وَلَا يَزِيدُ ٱلظَّٰلِمِينَ إِلَّا خَسَارࣰا\nT;0;17:83:1:وَإِذَآ أَنۡعَمۡنَا عَلَى ٱلۡإِنسَٰنِ أَعۡرَضَ وَنَـَٔا بِجَانِبِهِۦ وَإِذَا مَسَّهُ\nT;0;17:83:2:ٱلشَّرُّ كَانَ يَـُٔوسࣰا¦17:84:1:قُلۡ كُلࣱّ يَعۡمَلُ عَلَىٰ شَاكِلَتِهِۦ فَرَبُّكُمۡ أَعۡلَمُ\nT;0;17:84:2:بِمَنۡ هُوَ أَهۡدَىٰ سَبِيلࣰا¦17:85:1:وَيَسۡـَٔلُونَكَ عَنِ ٱلرُّوحِۖ قُلِ ٱلرُّوحُ مِنۡ\nT;0;17:85:2:أَمۡرِ رَبِّي وَمَآ أُوتِيتُم مِّنَ ٱلۡعِلۡمِ إِلَّا قَلِيلࣰا¦17:86:1:وَلَئِن شِئۡنَا لَنَذۡهَبَنَّ\nT;0;17:86:2:بِٱلَّذِيٓ أَوۡحَيۡنَآ إِلَيۡكَ ثُمَّ لَا تَجِدُ لَكَ بِهِۦ عَلَيۡنَا وَكِيلًا',
  '15;29;3;\nT;0;17:87:3:إِلَّا رَحۡمَةࣰ مِّن رَّبِّكَۚ إِنَّ فَضۡلَهُۥ كَانَ عَلَيۡكَ كَبِيرࣰا¦17:88:1:قُل\nT;0;17:88:0:لَّئِنِ ٱجۡتَمَعَتِ ٱلۡإِنسُ وَٱلۡجِنُّ عَلَىٰٓ أَن يَأۡتُواْ بِمِثۡلِ هَٰذَا ٱلۡقُرۡءَانِ\nT;0;17:88:2:لَا يَأۡتُونَ بِمِثۡلِهِۦ وَلَوۡ كَانَ بَعۡضُهُمۡ لِبَعۡضࣲ ظَهِيرࣰا\nT;0;17:89:1:وَلَقَدۡ صَرَّفۡنَا لِلنَّاسِ فِي هَٰذَا ٱلۡقُرۡءَانِ مِن كُلِّ مَثَلࣲ فَأَبَىٰٓ أَكۡثَرُ\nT;0;17:89:2:ٱلنَّاسِ إِلَّا كُفُورࣰا¦17:90:1:وَقَالُواْ لَن نُّؤۡمِنَ لَكَ حَتَّىٰ تَفۡجُرَ\nT;0;17:90:2:لَنَا مِنَ ٱلۡأَرۡضِ يَنۢبُوعًا¦17:91:1:أَوۡ تَكُونَ لَكَ جَنَّةࣱ مِّن نَّخِيلࣲ\nT;0;17:91:2:وَعِنَبࣲ فَتُفَجِّرَ ٱلۡأَنۡهَٰرَ خِلَٰلَهَا تَفۡجِيرًا¦17:92:1:أَوۡ تُسۡقِطَ ٱلسَّمَآءَ\nT;0;17:92:0:كَمَا زَعَمۡتَ عَلَيۡنَا كِسَفًا أَوۡ تَأۡتِيَ بِٱللَّهِ وَٱلۡمَلَٰٓئِكَةِ\nT;0;17:92:2:قَبِيلًا¦17:93:1:أَوۡ يَكُونَ لَكَ بَيۡتࣱ مِّن زُخۡرُفٍ أَوۡ تَرۡقَىٰ فِي ٱلسَّمَآءِ\nT;0;17:93:0:وَلَن نُّؤۡمِنَ لِرُقِيِّكَ حَتَّىٰ تُنَزِّلَ عَلَيۡنَا كِتَٰبࣰا نَّقۡرَؤُهُۥۗ قُلۡ\nT;0;17:93:2:سُبۡحَانَ رَبِّي هَلۡ كُنتُ إِلَّا بَشَرࣰا رَّسُولࣰا¦17:94:1:وَمَا مَنَعَ ٱلنَّاسَ\nT;0;17:94:0:أَن يُؤۡمِنُوٓاْ إِذۡ جَآءَهُمُ ٱلۡهُدَىٰٓ إِلَّآ أَن قَالُوٓاْ أَبَعَثَ ٱللَّهُ بَشَرࣰا\nT;0;17:94:2:رَّسُولࣰا¦17:95:1:قُل لَّوۡ كَانَ فِي ٱلۡأَرۡضِ مَلَٰٓئِكَةࣱ يَمۡشُونَ مُطۡمَئِنِّينَ\nT;0;17:95:2:لَنَزَّلۡنَا عَلَيۡهِم مِّنَ ٱلسَّمَآءِ مَلَكࣰا رَّسُولࣰا¦17:96:1:قُلۡ كَفَىٰ بِٱللَّهِ\nT;0;17:96:2:شَهِيدَۢا بَيۡنِي وَبَيۡنَكُمۡۚ إِنَّهُۥ كَانَ بِعِبَادِهِۦ خَبِيرَۢا بَصِيرࣰا',
  '15;29;3;117\nT;0;17:97:1:وَمَن يَهۡدِ ٱللَّهُ فَهُوَ ٱلۡمُهۡتَدِۖ وَمَن يُضۡلِلۡ فَلَن تَجِدَ لَهُمۡ أَوۡلِيَآءَ\nT;0;17:97:0:مِن دُونِهِۦۖ وَنَحۡشُرُهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ عَلَىٰ وُجُوهِهِمۡ عُمۡيࣰا وَبُكۡمࣰا\nT;0;17:97:2:وَصُمࣰّاۖ مَّأۡوَىٰهُمۡ جَهَنَّمُۖ كُلَّمَا خَبَتۡ زِدۡنَٰهُمۡ سَعِيرࣰا\nT;0;17:98:1:ذَٰلِكَ جَزَآؤُهُم بِأَنَّهُمۡ كَفَرُواْ بِـَٔايَٰتِنَا وَقَالُوٓاْ أَءِذَا كُنَّا عِظَٰمࣰا\nT;0;17:98:2:وَرُفَٰتًا أَءِنَّا لَمَبۡعُوثُونَ خَلۡقࣰا جَدِيدًا¦17:99:1:۞ أَوَلَمۡ يَرَوۡاْ أَنَّ ٱللَّهَ\nT;0;17:99:0:ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ قَادِرٌ عَلَىٰٓ أَن يَخۡلُقَ مِثۡلَهُمۡ\nT;0;17:99:2:وَجَعَلَ لَهُمۡ أَجَلࣰا لَّا رَيۡبَ فِيهِ فَأَبَى ٱلظَّٰلِمُونَ إِلَّا كُفُورࣰا\nT;0;17:100:1:قُل لَّوۡ أَنتُمۡ تَمۡلِكُونَ خَزَآئِنَ رَحۡمَةِ رَبِّيٓ إِذࣰا لَّأَمۡسَكۡتُمۡ خَشۡيَةَ\nT;0;17:100:2:ٱلۡإِنفَاقِۚ وَكَانَ ٱلۡإِنسَٰنُ قَتُورࣰا¦17:101:1:وَلَقَدۡ ءَاتَيۡنَا مُوسَىٰ تِسۡعَ\nT;0;17:101:0:ءَايَٰتِۭ بَيِّنَٰتࣲۖ فَسۡـَٔلۡ بَنِيٓ إِسۡرَٰٓءِيلَ إِذۡ جَآءَهُمۡ فَقَالَ لَهُۥ فِرۡعَوۡنُ\nT;0;17:101:2:إِنِّي لَأَظُنُّكَ يَٰمُوسَىٰ مَسۡحُورࣰا¦17:102:1:قَالَ لَقَدۡ عَلِمۡتَ مَآ أَنزَلَ\nT;0;17:102:0:هَٰٓؤُلَآءِ إِلَّا رَبُّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ بَصَآئِرَ وَإِنِّي لَأَظُنُّكَ\nT;0;17:102:2:يَٰفِرۡعَوۡنُ مَثۡبُورࣰا¦17:103:1:فَأَرَادَ أَن يَسۡتَفِزَّهُم مِّنَ ٱلۡأَرۡضِ\nT;0;17:103:2:فَأَغۡرَقۡنَٰهُ وَمَن مَّعَهُۥ جَمِيعࣰا¦17:104:1:وَقُلۡنَا مِنۢ بَعۡدِهِۦ لِبَنِيٓ إِسۡرَٰٓءِيلَ\nT;0;17:104:2:ٱسۡكُنُواْ ٱلۡأَرۡضَ فَإِذَا جَآءَ وَعۡدُ ٱلۡأٓخِرَةِ جِئۡنَا بِكُمۡ لَفِيفࣰا',
  '15;30;0;\nT;0;17:105:3:وَبِٱلۡحَقِّ أَنزَلۡنَٰهُ وَبِٱلۡحَقِّ نَزَلَۗ وَمَآ أَرۡسَلۡنَٰكَ إِلَّا مُبَشِّرࣰا وَنَذِيرࣰا\nT;0;17:106:3:وَقُرۡءَانࣰا فَرَقۡنَٰهُ لِتَقۡرَأَهُۥ عَلَى ٱلنَّاسِ عَلَىٰ مُكۡثࣲ وَنَزَّلۡنَٰهُ تَنزِيلࣰا\nT;0;17:107:1:قُلۡ ءَامِنُواْ بِهِۦٓ أَوۡ لَا تُؤۡمِنُوٓاْۚ إِنَّ ٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ مِن قَبۡلِهِۦٓ إِذَا يُتۡلَىٰ\nT;0;17:107:2:عَلَيۡهِمۡ يَخِرُّونَۤ لِلۡأَذۡقَانِۤ سُجَّدࣰاۤ¦17:108:1:وَيَقُولُونَ سُبۡحَٰنَ رَبِّنَآ إِن كَانَ\nT;0;17:108:2:وَعۡدُ رَبِّنَا لَمَفۡعُولࣰا¦17:109:1:وَيَخِرُّونَ لِلۡأَذۡقَانِ يَبۡكُونَ وَيَزِيدُهُمۡ\nT;0;17:109:2:خُشُوعࣰا۩¦17:110:1:قُلِ ٱدۡعُواْ ٱللَّهَ أَوِ ٱدۡعُواْ ٱلرَّحۡمَٰنَۖ أَيࣰّا مَّا تَدۡعُواْ فَلَهُ\nT;0;17:110:0:ٱلۡأَسۡمَآءُ ٱلۡحُسۡنَىٰۚ وَلَا تَجۡهَرۡ بِصَلَاتِكَ وَلَا تُخَافِتۡ بِهَا وَٱبۡتَغِ\nT;0;17:110:2:بَيۡنَ ذَٰلِكَ سَبِيلࣰا¦17:111:1:وَقُلِ ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِي لَمۡ يَتَّخِذۡ وَلَدࣰا وَلَمۡ يَكُن\nT;2;17:111:2:لَّهُۥ شَرِيكࣱ فِي ٱلۡمُلۡكِ وَلَمۡ يَكُن لَّهُۥ وَلِيࣱّ مِّنَ ٱلذُّلِّۖ وَكَبِّرۡهُ تَكۡبِيرَۢا\nH;18\nB;18\nT;0;18:1:3:ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِيٓ أَنزَلَ عَلَىٰ عَبۡدِهِ ٱلۡكِتَٰبَ وَلَمۡ يَجۡعَل لَّهُۥ عِوَجَاۜ\nT;0;18:2:1:قَيِّمࣰا لِّيُنذِرَ بَأۡسࣰا شَدِيدࣰا مِّن لَّدُنۡهُ وَيُبَشِّرَ ٱلۡمُؤۡمِنِينَ\nT;0;18:2:2:ٱلَّذِينَ يَعۡمَلُونَ ٱلصَّٰلِحَٰتِ أَنَّ لَهُمۡ أَجۡرًا حَسَنࣰا\nT;0;18:3:3:مَّٰكِثِينَ فِيهِ أَبَدࣰا¦18:4:3:وَيُنذِرَ ٱلَّذِينَ قَالُواْ ٱتَّخَذَ ٱللَّهُ وَلَدࣰا',
  '15;30;0;\nT;0;18:5:1:مَّا لَهُم بِهِۦ مِنۡ عِلۡمࣲ وَلَا لِأٓبَآئِهِمۡۚ كَبُرَتۡ كَلِمَةࣰ تَخۡرُجُ مِنۡ\nT;0;18:5:2:أَفۡوَٰهِهِمۡۚ إِن يَقُولُونَ إِلَّا كَذِبࣰا¦18:6:1:فَلَعَلَّكَ بَٰخِعࣱ نَّفۡسَكَ\nT;0;18:6:2:عَلَىٰٓ ءَاثَٰرِهِمۡ إِن لَّمۡ يُؤۡمِنُواْ بِهَٰذَا ٱلۡحَدِيثِ أَسَفًا¦18:7:1:إِنَّا\nT;0;18:7:2:جَعَلۡنَا مَا عَلَى ٱلۡأَرۡضِ زِينَةࣰ لَّهَا لِنَبۡلُوَهُمۡ أَيُّهُمۡ أَحۡسَنُ عَمَلࣰا\nT;0;18:8:3:وَإِنَّا لَجَٰعِلُونَ مَا عَلَيۡهَا صَعِيدࣰا جُرُزًا¦18:9:1:أَمۡ حَسِبۡتَ\nT;0;18:9:2:أَنَّ أَصۡحَٰبَ ٱلۡكَهۡفِ وَٱلرَّقِيمِ كَانُواْ مِنۡ ءَايَٰتِنَا عَجَبًا\nT;0;18:10:1:إِذۡ أَوَى ٱلۡفِتۡيَةُ إِلَى ٱلۡكَهۡفِ فَقَالُواْ رَبَّنَآ ءَاتِنَا مِن لَّدُنكَ\nT;0;18:10:2:رَحۡمَةࣰ وَهَيِّئۡ لَنَا مِنۡ أَمۡرِنَا رَشَدࣰا¦18:11:1:فَضَرَبۡنَا عَلَىٰٓ ءَاذَانِهِمۡ\nT;0;18:11:2:فِي ٱلۡكَهۡفِ سِنِينَ عَدَدࣰا¦18:12:1:ثُمَّ بَعَثۡنَٰهُمۡ لِنَعۡلَمَ أَيُّ\nT;0;18:12:2:ٱلۡحِزۡبَيۡنِ أَحۡصَىٰ لِمَا لَبِثُوٓاْ أَمَدࣰا¦18:13:1:نَّحۡنُ نَقُصُّ عَلَيۡكَ نَبَأَهُم\nT;0;18:13:2:بِٱلۡحَقِّۚ إِنَّهُمۡ فِتۡيَةٌ ءَامَنُواْ بِرَبِّهِمۡ وَزِدۡنَٰهُمۡ هُدࣰى\nT;0;18:14:1:وَرَبَطۡنَا عَلَىٰ قُلُوبِهِمۡ إِذۡ قَامُواْ فَقَالُواْ رَبُّنَا رَبُّ ٱلسَّمَٰوَٰتِ\nT;0;18:14:2:وَٱلۡأَرۡضِ لَن نَّدۡعُوَاْ مِن دُونِهِۦٓ إِلَٰهࣰاۖ لَّقَدۡ قُلۡنَآ إِذࣰا شَطَطًا\nT;0;18:15:1:هَٰٓؤُلَآءِ قَوۡمُنَا ٱتَّخَذُواْ مِن دُونِهِۦٓ ءَالِهَةࣰۖ لَّوۡلَا يَأۡتُونَ عَلَيۡهِم\nT;0;18:15:2:بِسُلۡطَٰنِۭ بَيِّنࣲۖ فَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبࣰا',
  '15;30;0;118\nT;0;18:16:1:وَإِذِ ٱعۡتَزَلۡتُمُوهُمۡ وَمَا يَعۡبُدُونَ إِلَّا ٱللَّهَ فَأۡوُۥٓاْ إِلَى ٱلۡكَهۡفِ\nT;0;18:16:2:يَنشُرۡ لَكُمۡ رَبُّكُم مِّن رَّحۡمَتِهِۦ وَيُهَيِّئۡ لَكُم مِّنۡ أَمۡرِكُم مِّرۡفَقࣰا\nT;0;18:17:1:۞ وَتَرَى ٱلشَّمۡسَ إِذَا طَلَعَت تَّزَٰوَرُ عَن كَهۡفِهِمۡ ذَاتَ\nT;0;18:17:0:ٱلۡيَمِينِ وَإِذَا غَرَبَت تَّقۡرِضُهُمۡ ذَاتَ ٱلشِّمَالِ وَهُمۡ فِي فَجۡوَةࣲ\nT;0;18:17:0:مِّنۡهُۚ ذَٰلِكَ مِنۡ ءَايَٰتِ ٱللَّهِۗ مَن يَهۡدِ ٱللَّهُ فَهُوَ ٱلۡمُهۡتَدِۖ وَمَن\nT;0;18:17:2:يُضۡلِلۡ فَلَن تَجِدَ لَهُۥ وَلِيࣰّا مُّرۡشِدࣰا¦18:18:1:وَتَحۡسَبُهُمۡ أَيۡقَاظࣰا\nT;0;18:18:0:وَهُمۡ رُقُودࣱۚ وَنُقَلِّبُهُمۡ ذَاتَ ٱلۡيَمِينِ وَذَاتَ ٱلشِّمَالِۖ وَكَلۡبُهُم\nT;0;18:18:0:بَٰسِطࣱ ذِرَاعَيۡهِ بِٱلۡوَصِيدِۚ لَوِ ٱطَّلَعۡتَ عَلَيۡهِمۡ لَوَلَّيۡتَ مِنۡهُمۡ\nT;0;18:18:2:فِرَارࣰا وَلَمُلِئۡتَ مِنۡهُمۡ رُعۡبࣰا¦18:19:1:وَكَذَٰلِكَ بَعَثۡنَٰهُمۡ\nT;0;18:19:0:لِيَتَسَآءَلُواْ بَيۡنَهُمۡۚ قَالَ قَآئِلࣱ مِّنۡهُمۡ كَمۡ لَبِثۡتُمۡۖ قَالُواْ لَبِثۡنَا\nT;0;18:19:0:يَوۡمًا أَوۡ بَعۡضَ يَوۡمࣲۚ قَالُواْ رَبُّكُمۡ أَعۡلَمُ بِمَا لَبِثۡتُمۡ فَٱبۡعَثُوٓاْ\nT;0;18:19:0:أَحَدَكُم بِوَرِقِكُمۡ هَٰذِهِۦٓ إِلَى ٱلۡمَدِينَةِ فَلۡيَنظُرۡ أَيُّهَآ أَزۡكَىٰ\nT;0;18:19:0:طَعَامࣰا فَلۡيَأۡتِكُم بِرِزۡقࣲ مِّنۡهُ وَلۡيَتَلَطَّفۡ وَلَا يُشۡعِرَنَّ\nT;0;18:19:2:بِكُمۡ أَحَدًا¦18:20:1:إِنَّهُمۡ إِن يَظۡهَرُواْ عَلَيۡكُمۡ يَرۡجُمُوكُمۡ\nT;0;18:20:2:أَوۡ يُعِيدُوكُمۡ فِي مِلَّتِهِمۡ وَلَن تُفۡلِحُوٓاْ إِذًا أَبَدࣰا',
  '15;30;1;\nT;0;18:21:1:وَكَذَٰلِكَ أَعۡثَرۡنَا عَلَيۡهِمۡ لِيَعۡلَمُوٓاْ أَنَّ وَعۡدَ ٱللَّهِ حَقࣱّ وَأَنَّ\nT;0;18:21:0:ٱلسَّاعَةَ لَا رَيۡبَ فِيهَآ إِذۡ يَتَنَٰزَعُونَ بَيۡنَهُمۡ أَمۡرَهُمۡۖ فَقَالُواْ\nT;0;18:21:0:ٱبۡنُواْ عَلَيۡهِم بُنۡيَٰنࣰاۖ رَّبُّهُمۡ أَعۡلَمُ بِهِمۡۚ قَالَ ٱلَّذِينَ غَلَبُواْ عَلَىٰٓ\nT;0;18:21:2:أَمۡرِهِمۡ لَنَتَّخِذَنَّ عَلَيۡهِم مَّسۡجِدࣰا¦18:22:1:سَيَقُولُونَ ثَلَٰثَةࣱ\nT;0;18:22:0:رَّابِعُهُمۡ كَلۡبُهُمۡ وَيَقُولُونَ خَمۡسَةࣱ سَادِسُهُمۡ كَلۡبُهُمۡ\nT;0;18:22:0:رَجۡمَۢا بِٱلۡغَيۡبِۖ وَيَقُولُونَ سَبۡعَةࣱ وَثَامِنُهُمۡ كَلۡبُهُمۡۚ قُل رَّبِّيٓ\nT;0;18:22:0:أَعۡلَمُ بِعِدَّتِهِم مَّا يَعۡلَمُهُمۡ إِلَّا قَلِيلࣱۗ فَلَا تُمَارِ فِيهِمۡ إِلَّا مِرَآءࣰ\nT;0;18:22:2:ظَٰهِرࣰا وَلَا تَسۡتَفۡتِ فِيهِم مِّنۡهُمۡ أَحَدࣰا¦18:23:1:وَلَا تَقُولَنَّ لِشَاْيۡءٍ\nT;0;18:23:2:إِنِّي فَاعِلࣱ ذَٰلِكَ غَدًا¦18:24:1:إِلَّآ أَن يَشَآءَ ٱللَّهُۚ وَٱذۡكُر رَّبَّكَ\nT;0;18:24:2:إِذَا نَسِيتَ وَقُلۡ عَسَىٰٓ أَن يَهۡدِيَنِ رَبِّي لِأَقۡرَبَ مِنۡ هَٰذَا رَشَدࣰا\nT;0;18:25:3:وَلَبِثُواْ فِي كَهۡفِهِمۡ ثَلَٰثَ مِاْئَةࣲ سِنِينَ وَٱزۡدَادُواْ تِسۡعࣰا\nT;0;18:26:1:قُلِ ٱللَّهُ أَعۡلَمُ بِمَا لَبِثُواْۖ لَهُۥ غَيۡبُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ\nT;0;18:26:0:أَبۡصِرۡ بِهِۦ وَأَسۡمِعۡۚ مَا لَهُم مِّن دُونِهِۦ مِن وَلِيࣲّ وَلَا يُشۡرِكُ\nT;0;18:26:2:فِي حُكۡمِهِۦٓ أَحَدࣰا¦18:27:1:وَٱتۡلُ مَآ أُوحِيَ إِلَيۡكَ مِن كِتَابِ\nT;0;18:27:2:رَبِّكَۖ لَا مُبَدِّلَ لِكَلِمَٰتِهِۦ وَلَن تَجِدَ مِن دُونِهِۦ مُلۡتَحَدࣰا',
  '15;30;1;119\nT;0;18:28:1:وَٱصۡبِرۡ نَفۡسَكَ مَعَ ٱلَّذِينَ يَدۡعُونَ رَبَّهُم بِٱلۡغَدَوٰةِ وَٱلۡعَشِيِّ\nT;0;18:28:0:يُرِيدُونَ وَجۡهَهُۥۖ وَلَا تَعۡدُ عَيۡنَاكَ عَنۡهُمۡ تُرِيدُ زِينَةَ ٱلۡحَيَوٰةِ\nT;0;18:28:0:ٱلدُّنۡيَاۖ وَلَا تُطِعۡ مَنۡ أَغۡفَلۡنَا قَلۡبَهُۥ عَن ذِكۡرِنَا وَٱتَّبَعَ هَوَىٰهُ وَكَانَ\nT;0;18:28:2:أَمۡرُهُۥ فُرُطࣰا¦18:29:1:وَقُلِ ٱلۡحَقُّ مِن رَّبِّكُمۡۖ فَمَن شَآءَ فَلۡيُؤۡمِن وَمَن\nT;0;18:29:0:شَآءَ فَلۡيَكۡفُرۡۚ إِنَّآ أَعۡتَدۡنَا لِلظَّٰلِمِينَ نَارًا أَحَاطَ بِهِمۡ سُرَادِقُهَاۚ\nT;0;18:29:0:وَإِن يَسۡتَغِيثُواْ يُغَاثُواْ بِمَآءࣲ كَٱلۡمُهۡلِ يَشۡوِي ٱلۡوُجُوهَۚ بِئۡسَ\nT;0;18:29:2:ٱلشَّرَابُ وَسَآءَتۡ مُرۡتَفَقًا¦18:30:1:إِنَّ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ\nT;0;18:30:2:ٱلصَّٰلِحَٰتِ إِنَّا لَا نُضِيعُ أَجۡرَ مَنۡ أَحۡسَنَ عَمَلًا¦18:31:1:أُوْلَٰٓئِكَ\nT;0;18:31:0:لَهُمۡ جَنَّٰتُ عَدۡنࣲ تَجۡرِي مِن تَحۡتِهِمُ ٱلۡأَنۡهَٰرُ يُحَلَّوۡنَ فِيهَا مِنۡ أَسَاوِرَ\nT;0;18:31:0:مِن ذَهَبࣲ وَيَلۡبَسُونَ ثِيَابًا خُضۡرࣰا مِّن سُندُسࣲ وَإِسۡتَبۡرَقࣲ مُّتَّكِـِٔينَ\nT;0;18:31:2:فِيهَا عَلَى ٱلۡأَرَآئِكِۚ نِعۡمَ ٱلثَّوَابُ وَحَسُنَتۡ مُرۡتَفَقࣰا¦18:32:1:۞ وَٱضۡرِبۡ\nT;0;18:32:0:لَهُم مَّثَلࣰا رَّجُلَيۡنِ جَعَلۡنَا لِأَحَدِهِمَا جَنَّتَيۡنِ مِنۡ أَعۡنَٰبࣲ وَحَفَفۡنَٰهُمَا\nT;0;18:32:2:بِنَخۡلࣲ وَجَعَلۡنَا بَيۡنَهُمَا زَرۡعࣰا¦18:33:1:كِلۡتَا ٱلۡجَنَّتَيۡنِ ءَاتَتۡ أُكُلَهَا وَلَمۡ\nT;0;18:33:2:تَظۡلِم مِّنۡهُ شَيۡـࣰٔاۚ وَفَجَّرۡنَا خِلَٰلَهُمَا نَهَرࣰا¦18:34:1:وَكَانَ لَهُۥ ثَمَرࣱ فَقَالَ\nT;0;18:34:2:لِصَٰحِبِهِۦ وَهُوَ يُحَاوِرُهُۥٓ أَنَا۠ أَكۡثَرُ مِنكَ مَالࣰا وَأَعَزُّ نَفَرࣰا',
  '15;30;2;\nT;0;18:35:1:وَدَخَلَ جَنَّتَهُۥ وَهُوَ ظَالِمࣱ لِّنَفۡسِهِۦ قَالَ مَآ أَظُنُّ أَن تَبِيدَ هَٰذِهِۦٓ\nT;0;18:35:2:أَبَدࣰا¦18:36:1:وَمَآ أَظُنُّ ٱلسَّاعَةَ قَآئِمَةࣰ وَلَئِن رُّدِدتُّ إِلَىٰ رَبِّي لَأَجِدَنَّ\nT;0;18:36:2:خَيۡرࣰا مِّنۡهَا مُنقَلَبࣰا¦18:37:1:قَالَ لَهُۥ صَاحِبُهُۥ وَهُوَ يُحَاوِرُهُۥٓ أَكَفَرۡتَ\nT;0;18:37:2:بِٱلَّذِي خَلَقَكَ مِن تُرَابࣲ ثُمَّ مِن نُّطۡفَةࣲ ثُمَّ سَوَّىٰكَ رَجُلࣰا\nT;0;18:38:3:لَّٰكِنَّا۠ هُوَ ٱللَّهُ رَبِّي وَلَآ أُشۡرِكُ بِرَبِّيٓ أَحَدࣰا¦18:39:1:وَلَوۡلَآ إِذۡ دَخَلۡتَ\nT;0;18:39:0:جَنَّتَكَ قُلۡتَ مَا شَآءَ ٱللَّهُ لَا قُوَّةَ إِلَّا بِٱللَّهِۚ إِن تَرَنِ أَنَا۠ أَقَلَّ مِنكَ\nT;0;18:39:2:مَالࣰا وَوَلَدࣰا¦18:40:1:فَعَسَىٰ رَبِّيٓ أَن يُؤۡتِيَنِ خَيۡرࣰا مِّن جَنَّتِكَ وَيُرۡسِلَ\nT;0;18:40:2:عَلَيۡهَا حُسۡبَانࣰا مِّنَ ٱلسَّمَآءِ فَتُصۡبِحَ صَعِيدࣰا زَلَقًا¦18:41:1:أَوۡ يُصۡبِحَ\nT;0;18:41:2:مَآؤُهَا غَوۡرࣰا فَلَن تَسۡتَطِيعَ لَهُۥ طَلَبࣰا¦18:42:1:وَأُحِيطَ بِثَمَرِهِۦ\nT;0;18:42:0:فَأَصۡبَحَ يُقَلِّبُ كَفَّيۡهِ عَلَىٰ مَآ أَنفَقَ فِيهَا وَهِيَ خَاوِيَةٌ عَلَىٰ\nT;0;18:42:2:عُرُوشِهَا وَيَقُولُ يَٰلَيۡتَنِي لَمۡ أُشۡرِكۡ بِرَبِّيٓ أَحَدࣰا¦18:43:1:وَلَمۡ تَكُن لَّهُۥ\nT;0;18:43:2:فِئَةࣱ يَنصُرُونَهُۥ مِن دُونِ ٱللَّهِ وَمَا كَانَ مُنتَصِرًا¦18:44:1:هُنَالِكَ ٱلۡوَلَٰيَةُ\nT;0;18:44:2:لِلَّهِ ٱلۡحَقِّۚ هُوَ خَيۡرࣱ ثَوَابࣰا وَخَيۡرٌ عُقۡبࣰا¦18:45:1:وَٱضۡرِبۡ لَهُم مَّثَلَ ٱلۡحَيَوٰةِ\nT;0;18:45:0:ٱلدُّنۡيَا كَمَآءٍ أَنزَلۡنَٰهُ مِنَ ٱلسَّمَآءِ فَٱخۡتَلَطَ بِهِۦ نَبَاتُ ٱلۡأَرۡضِ\nT;0;18:45:2:فَأَصۡبَحَ هَشِيمࣰا تَذۡرُوهُ ٱلرِّيَٰحُۗ وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَيۡءࣲ مُّقۡتَدِرًا',
  '15;30;2;120\nT;0;18:46:1:ٱلۡمَالُ وَٱلۡبَنُونَ زِينَةُ ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۖ وَٱلۡبَٰقِيَٰتُ ٱلصَّٰلِحَٰتُ\nT;0;18:46:2:خَيۡرٌ عِندَ رَبِّكَ ثَوَابࣰا وَخَيۡرٌ أَمَلࣰا¦18:47:1:وَيَوۡمَ نُسَيِّرُ ٱلۡجِبَالَ وَتَرَى\nT;0;18:47:2:ٱلۡأَرۡضَ بَارِزَةࣰ وَحَشَرۡنَٰهُمۡ فَلَمۡ نُغَادِرۡ مِنۡهُمۡ أَحَدࣰا¦18:48:1:وَعُرِضُواْ\nT;0;18:48:0:عَلَىٰ رَبِّكَ صَفࣰّا لَّقَدۡ جِئۡتُمُونَا كَمَا خَلَقۡنَٰكُمۡ أَوَّلَ مَرَّةِۭۚ بَلۡ زَعَمۡتُمۡ\nT;0;18:48:2:أَلَّن نَّجۡعَلَ لَكُم مَّوۡعِدࣰا¦18:49:1:وَوُضِعَ ٱلۡكِتَٰبُ فَتَرَى ٱلۡمُجۡرِمِينَ\nT;0;18:49:0:مُشۡفِقِينَ مِمَّا فِيهِ وَيَقُولُونَ يَٰوَيۡلَتَنَا مَالِ هَٰذَا ٱلۡكِتَٰبِ\nT;0;18:49:0:لَا يُغَادِرُ صَغِيرَةࣰ وَلَا كَبِيرَةً إِلَّآ أَحۡصَىٰهَاۚ وَوَجَدُواْ مَا عَمِلُواْ\nT;0;18:49:2:حَاضِرࣰاۗ وَلَا يَظۡلِمُ رَبُّكَ أَحَدࣰا¦18:50:1:وَإِذۡ قُلۡنَا لِلۡمَلَٰٓئِكَةِ ٱسۡجُدُواْ\nT;0;18:50:0:لِأٓدَمَ فَسَجَدُوٓاْ إِلَّآ إِبۡلِيسَ كَانَ مِنَ ٱلۡجِنِّ فَفَسَقَ عَنۡ أَمۡرِ رَبِّهِۦٓۗ\nT;0;18:50:0:أَفَتَتَّخِذُونَهُۥ وَذُرِّيَّتَهُۥٓ أَوۡلِيَآءَ مِن دُونِي وَهُمۡ لَكُمۡ عَدُوُّۢۚ\nT;0;18:50:2:بِئۡسَ لِلظَّٰلِمِينَ بَدَلࣰا¦18:51:1:۞ مَّآ أَشۡهَدتُّهُمۡ خَلۡقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ\nT;0;18:51:2:وَلَا خَلۡقَ أَنفُسِهِمۡ وَمَا كُنتُ مُتَّخِذَ ٱلۡمُضِلِّينَ عَضُدࣰا\nT;0;18:52:1:وَيَوۡمَ يَقُولُ نَادُواْ شُرَكَآءِيَ ٱلَّذِينَ زَعَمۡتُمۡ فَدَعَوۡهُمۡ\nT;0;18:52:2:فَلَمۡ يَسۡتَجِيبُواْ لَهُمۡ وَجَعَلۡنَا بَيۡنَهُم مَّوۡبِقࣰا¦18:53:1:وَرَءَا ٱلۡمُجۡرِمُونَ\nT;0;18:53:2:ٱلنَّارَ فَظَنُّوٓاْ أَنَّهُم مُّوَاقِعُوهَا وَلَمۡ يَجِدُواْ عَنۡهَا مَصۡرِفࣰا',
  '15;30;3;\nT;0;18:54:1:وَلَقَدۡ صَرَّفۡنَا فِي هَٰذَا ٱلۡقُرۡءَانِ لِلنَّاسِ مِن كُلِّ مَثَلࣲۚ وَكَانَ\nT;0;18:54:2:ٱلۡإِنسَٰنُ أَكۡثَرَ شَيۡءࣲ جَدَلࣰا¦18:55:1:وَمَا مَنَعَ ٱلنَّاسَ أَن يُؤۡمِنُوٓاْ\nT;0;18:55:0:إِذۡ جَآءَهُمُ ٱلۡهُدَىٰ وَيَسۡتَغۡفِرُواْ رَبَّهُمۡ إِلَّآ أَن تَأۡتِيَهُمۡ سُنَّةُ\nT;0;18:55:2:ٱلۡأَوَّلِينَ أَوۡ يَأۡتِيَهُمُ ٱلۡعَذَابُ قُبُلࣰا¦18:56:1:وَمَا نُرۡسِلُ ٱلۡمُرۡسَلِينَ\nT;0;18:56:0:إِلَّا مُبَشِّرِينَ وَمُنذِرِينَۚ وَيُجَٰدِلُ ٱلَّذِينَ كَفَرُواْ بِٱلۡبَٰطِلِ\nT;0;18:56:2:لِيُدۡحِضُواْ بِهِ ٱلۡحَقَّۖ وَٱتَّخَذُوٓاْ ءَايَٰتِي وَمَآ أُنذِرُواْ هُزُوࣰا\nT;0;18:57:1:وَمَنۡ أَظۡلَمُ مِمَّن ذُكِّرَ بِـَٔايَٰتِ رَبِّهِۦ فَأَعۡرَضَ عَنۡهَا وَنَسِيَ\nT;0;18:57:0:مَا قَدَّمَتۡ يَدَاهُۚ إِنَّا جَعَلۡنَا عَلَىٰ قُلُوبِهِمۡ أَكِنَّةً أَن يَفۡقَهُوهُ\nT;0;18:57:0:وَفِيٓ ءَاذَانِهِمۡ وَقۡرࣰاۖ وَإِن تَدۡعُهُمۡ إِلَى ٱلۡهُدَىٰ فَلَن يَهۡتَدُوٓاْ إِذًا\nT;0;18:57:2:أَبَدࣰا¦18:58:1:وَرَبُّكَ ٱلۡغَفُورُ ذُو ٱلرَّحۡمَةِۖ لَوۡ يُؤَاخِذُهُم بِمَا كَسَبُواْ\nT;0;18:58:0:لَعَجَّلَ لَهُمُ ٱلۡعَذَابَۚ بَل لَّهُم مَّوۡعِدࣱ لَّن يَجِدُواْ مِن دُونِهِۦ\nT;0;18:58:2:مَوۡئِلࣰا¦18:59:1:وَتِلۡكَ ٱلۡقُرَىٰٓ أَهۡلَكۡنَٰهُمۡ لَمَّا ظَلَمُواْ وَجَعَلۡنَا\nT;0;18:59:2:لِمَهۡلِكِهِم مَّوۡعِدࣰا¦18:60:1:وَإِذۡ قَالَ مُوسَىٰ لِفَتَىٰهُ لَآ أَبۡرَحُ حَتَّىٰٓ\nT;0;18:60:2:أَبۡلُغَ مَجۡمَعَ ٱلۡبَحۡرَيۡنِ أَوۡ أَمۡضِيَ حُقُبࣰا¦18:61:1:فَلَمَّا بَلَغَا مَجۡمَعَ\nT;0;18:61:2:بَيۡنِهِمَا نَسِيَا حُوتَهُمَا فَٱتَّخَذَ سَبِيلَهُۥ فِي ٱلۡبَحۡرِ سَرَبࣰا',
  '15;30;3;\nT;0;18:62:1:فَلَمَّا جَاوَزَا قَالَ لِفَتَىٰهُ ءَاتِنَا غَدَآءَنَا لَقَدۡ لَقِينَا مِن سَفَرِنَا\nT;0;18:62:2:هَٰذَا نَصَبࣰا¦18:63:1:قَالَ أَرَءَيۡتَ إِذۡ أَوَيۡنَآ إِلَى ٱلصَّخۡرَةِ فَإِنِّي نَسِيتُ\nT;0;18:63:0:ٱلۡحُوتَ وَمَآ أَنسَىٰنِيهُ إِلَّا ٱلشَّيۡطَٰنُ أَنۡ أَذۡكُرَهُۥۚ وَٱتَّخَذَ سَبِيلَهُۥ\nT;0;18:63:2:فِي ٱلۡبَحۡرِ عَجَبࣰا¦18:64:1:قَالَ ذَٰلِكَ مَا كُنَّا نَبۡغِۚ فَٱرۡتَدَّا عَلَىٰٓ ءَاثَارِهِمَا\nT;0;18:64:2:قَصَصࣰا¦18:65:1:فَوَجَدَا عَبۡدࣰا مِّنۡ عِبَادِنَآ ءَاتَيۡنَٰهُ رَحۡمَةࣰ مِّنۡ عِندِنَا\nT;0;18:65:2:وَعَلَّمۡنَٰهُ مِن لَّدُنَّا عِلۡمࣰا¦18:66:1:قَالَ لَهُۥ مُوسَىٰ هَلۡ أَتَّبِعُكَ عَلَىٰٓ أَن\nT;0;18:66:2:تُعَلِّمَنِ مِمَّا عُلِّمۡتَ رُشۡدࣰا¦18:67:1:قَالَ إِنَّكَ لَن تَسۡتَطِيعَ مَعِيَ\nT;0;18:67:2:صَبۡرࣰا¦18:68:3:وَكَيۡفَ تَصۡبِرُ عَلَىٰ مَا لَمۡ تُحِطۡ بِهِۦ خُبۡرࣰا¦18:69:1:قَالَ\nT;0;18:69:2:سَتَجِدُنِيٓ إِن شَآءَ ٱللَّهُ صَابِرࣰا وَلَآ أَعۡصِي لَكَ أَمۡرࣰا¦18:70:1:قَالَ فَإِنِ\nT;0;18:70:2:ٱتَّبَعۡتَنِي فَلَا تَسۡـَٔلۡنِي عَن شَيۡءٍ حَتَّىٰٓ أُحۡدِثَ لَكَ مِنۡهُ ذِكۡرࣰا\nT;0;18:71:1:فَٱنطَلَقَا حَتَّىٰٓ إِذَا رَكِبَا فِي ٱلسَّفِينَةِ خَرَقَهَاۖ قَالَ أَخَرَقۡتَهَا\nT;0;18:71:2:لِتُغۡرِقَ أَهۡلَهَا لَقَدۡ جِئۡتَ شَيۡـًٔا إِمۡرࣰا¦18:72:1:قَالَ أَلَمۡ أَقُلۡ إِنَّكَ\nT;0;18:72:2:لَن تَسۡتَطِيعَ مَعِيَ صَبۡرࣰا¦18:73:1:قَالَ لَا تُؤَاخِذۡنِي بِمَا نَسِيتُ وَلَا\nT;0;18:73:2:تُرۡهِقۡنِي مِنۡ أَمۡرِي عُسۡرࣰا¦18:74:1:فَٱنطَلَقَا حَتَّىٰٓ إِذَا لَقِيَا غُلَٰمࣰا فَقَتَلَهُۥ\nT;0;18:74:2:قَالَ أَقَتَلۡتَ نَفۡسࣰا زَكِيَّةَۢ بِغَيۡرِ نَفۡسࣲ لَّقَدۡ جِئۡتَ شَيۡـࣰٔا نُّكۡرࣰا',
  '16;31;0;121\nT;0;18:75:3:۞ قَالَ أَلَمۡ أَقُل لَّكَ إِنَّكَ لَن تَسۡتَطِيعَ مَعِيَ صَبۡرࣰا¦18:76:1:قَالَ إِن\nT;0;18:76:0:سَأَلۡتُكَ عَن شَيۡءِۭ بَعۡدَهَا فَلَا تُصَٰحِبۡنِيۖ قَدۡ بَلَغۡتَ مِن لَّدُنِّي\nT;0;18:76:2:عُذۡرࣰا¦18:77:1:فَٱنطَلَقَا حَتَّىٰٓ إِذَآ أَتَيَآ أَهۡلَ قَرۡيَةٍ ٱسۡتَطۡعَمَآ أَهۡلَهَا فَأَبَوۡاْ\nT;0;18:77:0:أَن يُضَيِّفُوهُمَا فَوَجَدَا فِيهَا جِدَارࣰا يُرِيدُ أَن يَنقَضَّ فَأَقَامَهُۥۖ\nT;0;18:77:2:قَالَ لَوۡ شِئۡتَ لَتَّخَذۡتَ عَلَيۡهِ أَجۡرࣰا¦18:78:1:قَالَ هَٰذَا فِرَاقُ بَيۡنِي\nT;0;18:78:2:وَبَيۡنِكَۚ سَأُنَبِّئُكَ بِتَأۡوِيلِ مَا لَمۡ تَسۡتَطِع عَّلَيۡهِ صَبۡرًا¦18:79:1:أَمَّا\nT;0;18:79:0:ٱلسَّفِينَةُ فَكَانَتۡ لِمَسَٰكِينَ يَعۡمَلُونَ فِي ٱلۡبَحۡرِ فَأَرَدتُّ أَنۡ\nT;0;18:79:2:أَعِيبَهَا وَكَانَ وَرَآءَهُم مَّلِكࣱ يَأۡخُذُ كُلَّ سَفِينَةٍ غَصۡبࣰا¦18:80:1:وَأَمَّا\nT;0;18:80:0:ٱلۡغُلَٰمُ فَكَانَ أَبَوَاهُ مُؤۡمِنَيۡنِ فَخَشِينَآ أَن يُرۡهِقَهُمَا طُغۡيَٰنࣰا\nT;0;18:80:2:وَكُفۡرࣰا¦18:81:1:فَأَرَدۡنَآ أَن يُبۡدِلَهُمَا رَبُّهُمَا خَيۡرࣰا مِّنۡهُ زَكَوٰةࣰ وَأَقۡرَبَ\nT;0;18:81:2:رُحۡمࣰا¦18:82:1:وَأَمَّا ٱلۡجِدَارُ فَكَانَ لِغُلَٰمَيۡنِ يَتِيمَيۡنِ فِي ٱلۡمَدِينَةِ\nT;0;18:82:0:وَكَانَ تَحۡتَهُۥ كَنزࣱ لَّهُمَا وَكَانَ أَبُوهُمَا صَٰلِحࣰا فَأَرَادَ رَبُّكَ أَن\nT;0;18:82:0:يَبۡلُغَآ أَشُدَّهُمَا وَيَسۡتَخۡرِجَا كَنزَهُمَا رَحۡمَةࣰ مِّن رَّبِّكَۚ\nT;0;18:82:2:وَمَا فَعَلۡتُهُۥ عَنۡ أَمۡرِيۚ ذَٰلِكَ تَأۡوِيلُ مَا لَمۡ تَسۡطِع عَّلَيۡهِ صَبۡرࣰا\nT;0;18:83:3:وَيَسۡـَٔلُونَكَ عَن ذِي ٱلۡقَرۡنَيۡنِۖ قُلۡ سَأَتۡلُواْ عَلَيۡكُم مِّنۡهُ ذِكۡرًا',
  '16;31;0;\nT;0;18:84:3:إِنَّا مَكَّنَّا لَهُۥ فِي ٱلۡأَرۡضِ وَءَاتَيۡنَٰهُ مِن كُلِّ شَيۡءࣲ سَبَبࣰا¦18:85:1:فَأَتۡبَعَ\nT;0;18:85:2:سَبَبًا¦18:86:1:حَتَّىٰٓ إِذَا بَلَغَ مَغۡرِبَ ٱلشَّمۡسِ وَجَدَهَا تَغۡرُبُ فِي عَيۡنٍ حَمِئَةࣲ\nT;0;18:86:0:وَوَجَدَ عِندَهَا قَوۡمࣰاۖ قُلۡنَا يَٰذَا ٱلۡقَرۡنَيۡنِ إِمَّآ أَن تُعَذِّبَ وَإِمَّآ أَن تَتَّخِذَ\nT;0;18:86:2:فِيهِمۡ حُسۡنࣰا¦18:87:1:قَالَ أَمَّا مَن ظَلَمَ فَسَوۡفَ نُعَذِّبُهُۥ ثُمَّ يُرَدُّ إِلَىٰ رَبِّهِۦ\nT;0;18:87:2:فَيُعَذِّبُهُۥ عَذَابࣰا نُّكۡرࣰا¦18:88:1:وَأَمَّا مَنۡ ءَامَنَ وَعَمِلَ صَٰلِحࣰا فَلَهُۥ جَزَآءً\nT;0;18:88:2:ٱلۡحُسۡنَىٰۖ وَسَنَقُولُ لَهُۥ مِنۡ أَمۡرِنَا يُسۡرࣰا¦18:89:3:ثُمَّ أَتۡبَعَ سَبَبًا¦18:90:1:حَتَّىٰٓ\nT;0;18:90:0:إِذَا بَلَغَ مَطۡلِعَ ٱلشَّمۡسِ وَجَدَهَا تَطۡلُعُ عَلَىٰ قَوۡمࣲ لَّمۡ نَجۡعَل لَّهُم مِّن\nT;0;18:90:2:دُونِهَا سِتۡرࣰا¦18:91:3:كَذَٰلِكَۖ وَقَدۡ أَحَطۡنَا بِمَا لَدَيۡهِ خُبۡرࣰا¦18:92:1:ثُمَّ\nT;0;18:92:2:أَتۡبَعَ سَبَبًا¦18:93:1:حَتَّىٰٓ إِذَا بَلَغَ بَيۡنَ ٱلسَّدَّيۡنِ وَجَدَ مِن دُونِهِمَا قَوۡمࣰا\nT;0;18:93:2:لَّا يَكَادُونَ يَفۡقَهُونَ قَوۡلࣰا¦18:94:1:قَالُواْ يَٰذَا ٱلۡقَرۡنَيۡنِ إِنَّ يَأۡجُوجَ\nT;0;18:94:0:وَمَأۡجُوجَ مُفۡسِدُونَ فِي ٱلۡأَرۡضِ فَهَلۡ نَجۡعَلُ لَكَ خَرۡجًا عَلَىٰٓ أَن\nT;0;18:94:2:تَجۡعَلَ بَيۡنَنَا وَبَيۡنَهُمۡ سَدࣰّا¦18:95:1:قَالَ مَا مَكَّنِّي فِيهِ رَبِّي خَيۡرࣱ فَأَعِينُونِي\nT;0;18:95:2:بِقُوَّةٍ أَجۡعَلۡ بَيۡنَكُمۡ وَبَيۡنَهُمۡ رَدۡمًا¦18:96:1:ءَاتُونِي زُبَرَ ٱلۡحَدِيدِۖ حَتَّىٰٓ إِذَا سَاوَىٰ\nT;0;18:96:0:بَيۡنَ ٱلصَّدَفَيۡنِ قَالَ ٱنفُخُواْۖ حَتَّىٰٓ إِذَا جَعَلَهُۥ نَارࣰا قَالَ ءَاتُونِيٓ أُفۡرِغۡ عَلَيۡهِ\nT;0;18:96:2:قِطۡرࣰا¦18:97:3:فَمَا ٱسۡطَٰعُوٓاْ أَن يَظۡهَرُوهُ وَمَا ٱسۡتَطَٰعُواْ لَهُۥ نَقۡبࣰا',
];
